fn instruction_generation_priority_dispositions(
    request_success: bool,
    release_blocked: bool,
    artifact_count: usize,
    blocker_count: usize,
    missing_release_evidence: bool,
) -> Vec<Value> {
    vec![
        instruction_generation_priority_disposition(
            "generated-artifact-readiness",
            if artifact_count == 0 {
                "blocked"
            } else if request_success && !release_blocked {
                "closed"
            } else {
                "needs-review"
            },
            vec![format!("artifactCount:{artifact_count}")],
            vec![
                "POST /fabrication/instructions/generation/result",
                "POST /fabrication/instructions/validate",
                "POST /fabrication/release/result",
            ],
            if artifact_count == 0 {
                "machineReady remains blocked until generated instruction artifacts are retained"
            } else {
                "generated instruction artifacts are present for downstream review"
            },
        ),
        instruction_generation_priority_disposition(
            "blocker-review-closure",
            if blocker_count > 0 {
                "blocked"
            } else if request_success && !release_blocked {
                "closed"
            } else {
                "needs-review"
            },
            vec![format!("blockerCount:{blocker_count}")],
            vec![
                "POST /fabrication/instructions/review/result",
                "POST /fabrication/remediation/plan",
                "POST /fabrication/release/result",
            ],
            if blocker_count > 0 {
                "machineReady remains blocked until instruction-generation blockers are reviewed into remediation or release gates"
            } else {
                "instruction-generation worker did not report open blockers"
            },
        ),
        instruction_generation_priority_disposition(
            "release-evidence-retention",
            if missing_release_evidence {
                "blocked"
            } else if request_success && !release_blocked {
                "closed"
            } else {
                "needs-review"
            },
            vec![format!("missingReleaseEvidence:{missing_release_evidence}")],
            vec![
                "POST /fabrication/instructions/generation/result",
                "POST /fabrication/simulation/result",
                "POST /fabrication/release/result",
            ],
            if missing_release_evidence {
                "machineReady remains blocked until generated instruction artifacts carry URI, checksum, and evidence labels"
            } else {
                "generated instruction artifacts retain release evidence"
            },
        ),
        instruction_generation_priority_disposition(
            "learning-feedback-after-disposition",
            if release_blocked {
                "pending-blocker-resolution"
            } else {
                "ready-for-learning"
            },
            vec![
                format!("releaseBlocked:{release_blocked}"),
                format!("requestSuccess:{request_success}"),
            ],
            vec![
                "POST /fabrication/learning/outcomes",
                "GET /fabrication/learning/policy",
                "GET /fabrication/learning/corpus",
            ],
            if release_blocked {
                "learning feedback should preserve blocked instruction-generation priorities before advisory promotion"
            } else {
                "instruction-generation result can be submitted as positive generated-instruction learning evidence after release review"
            },
        ),
    ]
}

fn instruction_generation_result_review_response(
    request: InstructionGenerationResultReviewRequest,
) -> Result<Value, String> {
    let request_id = request_id(request.request_id.as_ref(), "instruction-generation-result");
    let generated_at_ms = now_ms();
    let generation_result_job_id = safe_job_id(
        "instruction-generation-result",
        &request_id,
        generated_at_ms,
    );
    let plan_request_id = validate_optional_label(request.plan_request_id, "planRequestId")?;
    let job_id = validate_optional_label(request.job_id, "jobId")?;
    let worker_id = validate_label(&request.worker_id, "workerId")?;
    let generator = validate_optional_text(request.generator, "generator", MAX_LABEL_LEN)?;
    let generator_version =
        validate_optional_text(request.generator_version, "generatorVersion", MAX_LABEL_LEN)?;
    let artifacts = validate_instruction_generation_result_artifacts(request.artifacts)?;
    let blockers = validate_instruction_generation_result_blockers(request.blockers)?;
    let warnings = validate_signal_list(request.warnings, "warnings", MAX_TEXT_LEN)?;
    let missing_release_evidence = artifacts.iter().any(|artifact| {
        let evidence = artifact.get("releaseEvidence").unwrap_or(&Value::Null);
        !evidence
            .get("hasRetainedArtifact")
            .and_then(Value::as_bool)
            .unwrap_or(false)
            || !evidence
                .get("hasChecksum")
                .and_then(Value::as_bool)
                .unwrap_or(false)
            || !evidence
                .get("hasEvidence")
                .and_then(Value::as_bool)
                .unwrap_or(false)
    });
    let release_blocked = !request.success
        || !request.machine_ready
        || artifacts.is_empty()
        || !blockers.is_empty()
        || missing_release_evidence;
    let review_status = if artifacts.is_empty() {
        "no-generated-instruction-artifacts-release-blocked"
    } else if !request.success {
        "instruction-generation-worker-failed-release-blocked"
    } else if !blockers.is_empty() {
        "instruction-generation-blockers-review-required"
    } else if missing_release_evidence {
        "instruction-generation-evidence-review-required"
    } else if request.machine_ready {
        "instruction-generation-result-ready-for-release-review"
    } else {
        "instruction-generation-result-machine-ready-review-required"
    };
    let mut learning_observations = vec![
        format!("instruction-generation-worker:{worker_id}"),
        format!("instruction-generation-review:{review_status}"),
    ];
    if let Some(generator) = generator.as_ref() {
        learning_observations.push(format!(
            "instruction-generation-generator:{}",
            normalize_token(generator)
        ));
    }
    if release_blocked {
        learning_observations.push("instruction-generation:release-blocked".to_string());
    }
    let priority_dispositions = instruction_generation_priority_dispositions(
        request.success,
        release_blocked,
        artifacts.len(),
        blockers.len(),
        missing_release_evidence,
    );
    learning_observations.extend(priority_dispositions.iter().filter_map(|disposition| {
        disposition
            .get("learningObservation")
            .and_then(Value::as_str)
            .map(str::to_string)
    }));
    learning_observations.extend(blockers.iter().filter_map(|blocker| {
        blocker
            .get("code")
            .and_then(Value::as_str)
            .map(|code| format!("instruction-generation-blocker:{}", normalize_token(code)))
    }));
    learning_observations.sort();
    learning_observations.dedup();

    Ok(json!({
        "ok": true,
        "service": SERVICE_NAME,
        "schemaVersion": "dd.fabrication.instruction-generation-result-review.v1",
        "serviceSchemaVersion": SCHEMA_VERSION,
        "requestId": request_id,
        "generationResultJobId": generation_result_job_id,
        "generatedAtMs": generated_at_ms,
        "routes": [
            "POST /instructions/generation/result",
            "POST /fabrication/instructions/generation/result"
        ],
        "requestSubject": FABRICATION_INSTRUCTION_GENERATION_REQUESTS_SUBJECT,
        "resultSubject": FABRICATION_INSTRUCTION_GENERATION_RESULTS_SUBJECT,
        "queueGroup": FABRICATION_INSTRUCTION_GENERATION_REQUESTS_QUEUE_GROUP,
        "generationRoutes": [
            "POST /slicers/plan",
            "POST /fabrication/slicers/plan",
            "POST /instructions/generate",
            "POST /fabrication/instructions/generate",
            "POST /machine-code/generate",
            "POST /fabrication/machine-code/generate"
        ],
        "catalogRoutes": [
            "GET /instructions/generation/catalog",
            "GET /fabrication/instructions/generation/catalog"
        ],
        "reviewStatus": review_status,
        "machineReady": request.machine_ready && !release_blocked,
        "releaseBlocked": release_blocked,
        "artifactCount": artifacts.len(),
        "blockerCount": blockers.len(),
        "warningCount": warnings.len(),
        "missingReleaseEvidence": missing_release_evidence,
        "priorityDispositions": priority_dispositions.clone(),
        "instructionGenerationResult": {
            "planRequestId": plan_request_id,
            "jobId": job_id,
            "workerId": worker_id,
            "generator": generator,
            "generatorVersion": generator_version,
            "success": request.success,
            "machineReady": request.machine_ready,
            "artifacts": artifacts,
            "blockers": blockers,
            "warnings": warnings,
            "reviewMetadata": request.review_metadata
        },
        "releaseUpdate": {
            "machineReleaseBlocked": release_blocked,
            "requiredBeforeMachineReady": [
                "generated machine-code or instruction artifact retained with checksum",
                "worker evidence attached for controller, slicer, setup, simulation, inspection, or postprocess target",
                "blockers reviewed into machineRelease, executionPlan, and releasePackagePlan",
                "operator or automation signoff attached for any human-intervention or split/combine boundary"
            ],
            "targetSurfaces": [
                "generatedPrograms",
                "controllerPlan",
                "simulation.programs",
                "executionPlan.programRuns",
                "machineRelease.blockers",
                "releasePackagePlan.packages"
            ]
        },
        "learning": {
            "observations": learning_observations,
            "engineTargets": ["MDP", "POMDP", "neural"],
            "outcomeRoute": "POST /fabrication/learning/outcomes",
            "outcomeDraft": {
                "schemaVersion": "dd.fabrication.instruction-generation-learning-outcome-draft.v1",
                "sourceKind": "instruction-generation-result",
                "sourceJobId": generation_result_job_id,
                "sourceRequestId": request_id,
                "success": !release_blocked,
                "rewardHint": if release_blocked { -0.55 } else { 0.5 },
                "generator": generator,
                "formatHints": artifacts
                    .iter()
                    .filter_map(|artifact| artifact.get("format").and_then(Value::as_str))
                    .collect::<Vec<_>>(),
                "targetHints": artifacts
                    .iter()
                    .filter_map(|artifact| artifact.get("targetId").and_then(Value::as_str))
                    .collect::<Vec<_>>(),
                "blockerHints": blockers
                    .iter()
                    .filter_map(|blocker| blocker.get("code").and_then(Value::as_str))
                    .collect::<Vec<_>>(),
                "featureHints": [
                    format!("artifact-count:{}", artifacts.len()),
                    format!("blocker-count:{}", blockers.len()),
                    format!("missing-release-evidence:{missing_release_evidence}")
                ],
                "priorityDispositions": priority_dispositions,
                "recommendedSubmitRoute": "POST /fabrication/learning/outcomes"
            }
        },
        "artifactSurfaces": [
            "instruction-generation-result",
            "generated-machine-program",
            "program-*",
            "simulation-report",
            "controller-plan",
            "execution-plan",
            "release-package-plan",
            "instruction-generation-priority-dispositions",
            "mdp-request.artifacts.generatedPrograms"
        ],
        "releasePolicy": [
            "instruction generation results are worker evidence for generated machine code, setup sheets, simulation reports, inspection plans, postprocess instructions, or operator travelers",
            "machine-ready release remains blocked until retained artifacts, checksums, evidence, blocker review, simulation or dry-run evidence, controller review, and signoff are attached",
            "instruction generation result observations feed MDP/POMDP/neural learning so future plans can prefer reliable slicer, CAM, postprocessor, simulation, and setup-sheet workers"
        ]
    }))
}

fn instruction_generation_result_job_severity(response: &Value) -> String {
    let status = response_str_field(response, "reviewStatus", "");
    let release_blocked = response
        .get("releaseBlocked")
        .and_then(Value::as_bool)
        .unwrap_or(true);
    if status.contains("worker-failed")
        || status.contains("no-generated-instruction-artifacts")
        || status.contains("blockers")
    {
        "error".to_string()
    } else if release_blocked {
        "warning".to_string()
    } else {
        "ok".to_string()
    }
}

fn stored_instruction_generation_result_job(response: &Value) -> StoredFabricationJob {
    let generated_at_ms = response_u128_field(response, "generatedAtMs");
    let request_id = response_str_field(response, "requestId", "instruction-generation-result");
    let job_id = response_str_field(
        response,
        "generationResultJobId",
        &safe_job_id(
            "instruction-generation-result",
            &request_id,
            generated_at_ms,
        ),
    );
    let review_status =
        response_str_field(response, "reviewStatus", "instruction-generation-result");
    let release_blocked = response
        .get("releaseBlocked")
        .and_then(Value::as_bool)
        .unwrap_or(true);
    let result = response
        .get("instructionGenerationResult")
        .cloned()
        .unwrap_or(Value::Null);
    let generated_artifacts = result
        .get("artifacts")
        .cloned()
        .unwrap_or_else(|| json!([]));
    let blockers = result.get("blockers").cloned().unwrap_or_else(|| json!([]));
    let warnings = result.get("warnings").cloned().unwrap_or_else(|| json!([]));
    let release_update = response
        .get("releaseUpdate")
        .cloned()
        .unwrap_or_else(|| json!({}));
    let priority_dispositions = response
        .get("priorityDispositions")
        .cloned()
        .unwrap_or_else(|| json!([]));
    let learning_observations = response
        .get("learning")
        .and_then(|learning| learning.get("observations"))
        .cloned()
        .unwrap_or_else(|| json!([]));
    let artifacts = vec![
        json_artifact(
            "instruction-generation-result".to_string(),
            "instruction-generation-result",
            response.clone(),
            generated_at_ms,
        ),
        json_artifact(
            "instruction-generation-artifacts".to_string(),
            "instruction-generation-artifacts",
            generated_artifacts,
            generated_at_ms,
        ),
        json_artifact(
            "instruction-generation-blockers".to_string(),
            "instruction-generation-blockers",
            blockers,
            generated_at_ms,
        ),
        json_artifact(
            "instruction-generation-warnings".to_string(),
            "instruction-generation-warnings",
            warnings,
            generated_at_ms,
        ),
        json_artifact(
            "instruction-generation-release-update".to_string(),
            "instruction-generation-release-update",
            release_update,
            generated_at_ms,
        ),
        json_artifact(
            "instruction-generation-priority-dispositions".to_string(),
            "instruction-generation-priority-dispositions",
            priority_dispositions,
            generated_at_ms,
        ),
        json_artifact(
            "instruction-generation-learning-observations".to_string(),
            "instruction-generation-learning-observations",
            learning_observations,
            generated_at_ms,
        ),
    ]
    .into_iter()
    .map(|artifact| (artifact.artifact_id.clone(), artifact))
    .collect::<BTreeMap<_, _>>();
    let artifact_ids = artifacts.keys().cloned().collect::<Vec<_>>();

    StoredFabricationJob {
        record: FabricationJobRecord {
            job_id,
            request_id,
            kind: "instruction-generation-result".to_string(),
            status: review_status.clone(),
            ok: !release_blocked,
            severity: instruction_generation_result_job_severity(response),
            summary: format!("instruction generation result review: {review_status}"),
            artifact_count: artifact_ids.len(),
            artifact_ids,
            created_at_ms: generated_at_ms,
            updated_at_ms: generated_at_ms,
        },
        plan: None,
        analysis: None,
        learning: None,
        artifacts,
    }
}

fn store_instruction_generation_result_response(state: &AppState, response: &Value) {
    store_job(state, stored_instruction_generation_result_job(response));
}

fn validate_machine_code_result_programs(
    programs: Option<Vec<MachineCodeResultProgram>>,
) -> Result<Vec<Value>, String> {
    let programs = programs.unwrap_or_default();
    if programs.len() > MAX_PROGRAMS * 4 {
        return Err(format!(
            "programs must contain at most {} entries",
            MAX_PROGRAMS * 4
        ));
    }
    let mut seen = BTreeSet::new();
    programs
        .into_iter()
        .enumerate()
        .map(|(index, program)| {
            let program_id =
                validate_label(&program.program_id, &format!("programs[{index}].programId"))?;
            if !seen.insert(program_id.clone()) {
                return Err(format!(
                    "programs must have unique programId values; duplicate {program_id}"
                ));
            }
            let estimated_runtime_sec = program
                .estimated_runtime_sec
                .map(|runtime| {
                    if runtime < 0 {
                        Err(format!(
                            "programs[{index}].estimatedRuntimeSec must be non-negative"
                        ))
                    } else {
                        Ok(runtime)
                    }
                })
                .transpose()?;
            let uri = validate_optional_text(
                program.uri,
                &format!("programs[{index}].uri"),
                MAX_TEXT_LEN,
            )?;
            let sha256 =
                validate_optional_label(program.sha256, &format!("programs[{index}].sha256"))?;
            let evidence = validate_signal_list(
                program.evidence,
                &format!("programs[{index}].evidence"),
                MAX_TEXT_LEN,
            )?;
            let has_retained_artifact = uri.as_ref().is_some_and(|value| !value.is_empty());
            let has_checksum = sha256.as_ref().is_some_and(|value| !value.is_empty());
            let has_evidence = !evidence.is_empty();
            Ok(json!({
                "programId": program_id,
                "sourceProgramId": validate_optional_label(program.source_program_id, &format!("programs[{index}].sourceProgramId"))?,
                "targetId": validate_optional_label(program.target_id, &format!("programs[{index}].targetId"))?,
                "operationId": validate_optional_label(program.operation_id, &format!("programs[{index}].operationId"))?,
                "language": validate_label(&program.language, &format!("programs[{index}].language"))?,
                "status": validate_label(&program.status, &format!("programs[{index}].status"))?,
                "outputFormat": validate_optional_label(program.output_format, &format!("programs[{index}].outputFormat"))?,
                "controllerDialect": validate_optional_text(program.controller_dialect, &format!("programs[{index}].controllerDialect"), MAX_LABEL_LEN)?,
                "uri": uri,
                "sha256": sha256,
                "estimatedRuntimeSec": estimated_runtime_sec,
                "releaseBlocker": program.release_blocker.unwrap_or(false),
                "evidence": evidence,
                "previewLines": validate_signal_list(program.preview_lines, &format!("programs[{index}].previewLines"), MAX_TEXT_LEN)?,
                "releaseEvidence": {
                    "hasRetainedArtifact": has_retained_artifact,
                    "hasChecksum": has_checksum,
                    "hasEvidence": has_evidence
                }
            }))
        })
        .collect()
}

fn validate_machine_code_result_controller_checks(
    checks: Option<Vec<MachineCodeResultControllerCheck>>,
) -> Result<Vec<Value>, String> {
    let checks = checks.unwrap_or_default();
    if checks.len() > MAX_LEARNING_SIGNALS {
        return Err(format!(
            "controllerChecks must contain at most {MAX_LEARNING_SIGNALS} entries"
        ));
    }
    let mut seen = BTreeSet::new();
    checks
        .into_iter()
        .enumerate()
        .map(|(index, check)| {
            let check_id =
                validate_label(&check.check_id, &format!("controllerChecks[{index}].checkId"))?;
            if !seen.insert(check_id.clone()) {
                return Err(format!(
                    "controllerChecks must have unique checkId values; duplicate {check_id}"
                ));
            }
            Ok(json!({
                "checkId": check_id,
                "checkKind": validate_label(&check.check_kind, &format!("controllerChecks[{index}].checkKind"))?,
                "status": validate_label(&check.status, &format!("controllerChecks[{index}].status"))?,
                "controller": validate_optional_label(check.controller, &format!("controllerChecks[{index}].controller"))?,
                "postprocessor": validate_optional_label(check.postprocessor, &format!("controllerChecks[{index}].postprocessor"))?,
                "machineId": validate_optional_label(check.machine_id, &format!("controllerChecks[{index}].machineId"))?,
                "releaseBlocker": check.release_blocker.unwrap_or(false),
                "requiresHumanIntervention": check.requires_human_intervention.unwrap_or(false),
                "evidence": validate_signal_list(check.evidence, &format!("controllerChecks[{index}].evidence"), MAX_TEXT_LEN)?
            }))
        })
        .collect()
}

