fn validate_machine_code_result_artifacts(
    artifacts: Option<Vec<MachineCodeResultArtifact>>,
) -> Result<Vec<Value>, String> {
    let artifacts = artifacts.unwrap_or_default();
    if artifacts.len() > MAX_LEARNING_SIGNALS {
        return Err(format!(
            "artifacts must contain at most {MAX_LEARNING_SIGNALS} entries"
        ));
    }
    let mut seen = BTreeSet::new();
    artifacts
        .into_iter()
        .enumerate()
        .map(|(index, artifact)| {
            let artifact_id =
                validate_label(&artifact.artifact_id, &format!("artifacts[{index}].artifactId"))?;
            if !seen.insert(artifact_id.clone()) {
                return Err(format!(
                    "artifacts must have unique artifactId values; duplicate {artifact_id}"
                ));
            }
            Ok(json!({
                "artifactId": artifact_id,
                "artifactKind": validate_label(&artifact.artifact_kind, &format!("artifacts[{index}].artifactKind"))?,
                "programId": validate_optional_label(artifact.program_id, &format!("artifacts[{index}].programId"))?,
                "uri": validate_optional_text(artifact.uri, &format!("artifacts[{index}].uri"), MAX_TEXT_LEN)?,
                "sha256": validate_optional_label(artifact.sha256, &format!("artifacts[{index}].sha256"))?,
                "format": validate_optional_label(artifact.format, &format!("artifacts[{index}].format"))?,
                "evidence": validate_signal_list(artifact.evidence, &format!("artifacts[{index}].evidence"), MAX_TEXT_LEN)?
            }))
        })
        .collect()
}

fn machine_code_result_status_blocks_release(status: &str) -> bool {
    let status = normalize_token(status);
    !matches!(
        status.as_str(),
        "complete"
            | "completed"
            | "success"
            | "succeeded"
            | "ok"
            | "pass"
            | "passed"
            | "ready"
            | "approved"
            | "released"
            | "clear"
            | "cleared"
            | "resolved"
            | "verified"
            | "accepted"
            | "compatible"
            | "postprocessed"
    )
}

fn machine_code_result_program_blocks_release(program: &Value) -> bool {
    if program
        .get("releaseBlocker")
        .and_then(Value::as_bool)
        .unwrap_or(false)
    {
        return true;
    }
    let status = program
        .get("status")
        .and_then(Value::as_str)
        .unwrap_or("unresolved");
    machine_code_result_status_blocks_release(status)
}

fn machine_code_result_controller_check_blocks_release(check: &Value) -> bool {
    if check
        .get("releaseBlocker")
        .and_then(Value::as_bool)
        .unwrap_or(false)
        || check
            .get("requiresHumanIntervention")
            .and_then(Value::as_bool)
            .unwrap_or(false)
    {
        return true;
    }
    let status = check
        .get("status")
        .and_then(Value::as_str)
        .unwrap_or("unresolved");
    machine_code_result_status_blocks_release(status)
}

fn machine_code_result_boundary_blocks_release(boundary: &Value) -> bool {
    boundary
        .get("releaseBlocker")
        .and_then(Value::as_bool)
        .unwrap_or(false)
        || boundary
            .get("requiresHumanIntervention")
            .and_then(Value::as_bool)
            .unwrap_or(false)
}

fn machine_code_result_program_missing_release_evidence(program: &Value) -> bool {
    let evidence = program.get("releaseEvidence").unwrap_or(&Value::Null);
    !evidence
        .get("hasRetainedArtifact")
        .and_then(Value::as_bool)
        .unwrap_or(false)
        || !evidence
            .get("hasChecksum")
            .and_then(Value::as_bool)
            .unwrap_or(false)
        || !evidence
            .get("hasEvidence")
            .and_then(Value::as_bool)
            .unwrap_or(false)
}

fn machine_code_result_artifact_missing_release_evidence(artifact: &Value) -> bool {
    artifact.get("uri").and_then(Value::as_str).is_none()
        || artifact.get("sha256").and_then(Value::as_str).is_none()
        || artifact
            .get("evidence")
            .and_then(Value::as_array)
            .is_none_or(Vec::is_empty)
}

fn machine_code_priority_disposition(
    priority_id: &str,
    disposition: &str,
    evidence: Vec<String>,
    next_routes: Vec<&str>,
    release_impact: &str,
) -> Value {
    json!({
        "priorityId": priority_id,
        "disposition": disposition,
        "evidence": evidence,
        "nextRoutes": next_routes,
        "releaseImpact": release_impact,
        "learningObservation": format!("machine-code-priority:{priority_id}:{}", normalize_token(disposition))
    })
}

fn machine_code_priority_dispositions(
    request_success: bool,
    release_blocked: bool,
    program_blocker_count: usize,
    controller_check_blocker_count: usize,
    boundary_blocker_count: usize,
    human_intervention_required: bool,
    artifact_evidence_missing: bool,
    programs: &[Value],
) -> Vec<Value> {
    let program_languages = programs
        .iter()
        .filter_map(|program| program.get("language").and_then(Value::as_str))
        .map(normalize_token)
        .collect::<Vec<_>>();
    let printer_or_slicer_output = program_languages.iter().any(|language| {
        language.contains("printer")
            || language.contains("slicer")
            || language.contains("marlin")
            || language.contains("reprap")
            || language.contains("3mf")
            || language.contains("resin")
    });

    vec![
        machine_code_priority_disposition(
            "machine-failure-boundary-first",
            if program_blocker_count > 0
                || controller_check_blocker_count > 0
                || boundary_blocker_count > 0
            {
                "blocked"
            } else if request_success && !release_blocked {
                "closed"
            } else {
                "needs-review"
            },
            vec![
                format!("programBlockerCount:{program_blocker_count}"),
                format!("controllerCheckBlockerCount:{controller_check_blocker_count}"),
                format!("boundaryBlockerCount:{boundary_blocker_count}"),
            ],
            vec![
                "POST /fabrication/machine-code/result",
                "POST /fabrication/simulation/run",
                "POST /fabrication/release/result",
            ],
            if program_blocker_count > 0
                || controller_check_blocker_count > 0
                || boundary_blocker_count > 0
            {
                "machineReady remains blocked by controller, program, or machine-code failure evidence"
            } else {
                "machine-code review did not report an open machine-failure priority blocker"
            },
        ),
        machine_code_priority_disposition(
            "human-intervention-required",
            if human_intervention_required {
                "blocked"
            } else if request_success && !release_blocked {
                "closed"
            } else {
                "needs-review"
            },
            vec![format!(
                "humanInterventionRequired:{human_intervention_required}"
            )],
            vec![
                "POST /fabrication/interventions/result",
                "POST /fabrication/execution/plan",
                "POST /fabrication/release/result",
            ],
            if human_intervention_required {
                "machineReady remains blocked until operator or automation signoff is retained"
            } else {
                "machine-code review did not report an open human-intervention priority blocker"
            },
        ),
        machine_code_priority_disposition(
            "non-gcode-job-sheet-evidence",
            if artifact_evidence_missing && printer_or_slicer_output {
                "blocked"
            } else if artifact_evidence_missing {
                "partially-reviewed"
            } else if printer_or_slicer_output {
                "closed"
            } else {
                "not-observed"
            },
            vec![
                format!("printerOrSlicerOutput:{printer_or_slicer_output}"),
                format!("artifactEvidenceMissing:{artifact_evidence_missing}"),
            ],
            vec![
                "POST /fabrication/instructions/import/review",
                "POST /fabrication/instructions/validate",
                "POST /fabrication/machine-code/result",
                "POST /fabrication/release/result",
            ],
            if artifact_evidence_missing {
                "machine-code evidence remains blocked until retained URI, checksum, and evidence labels are attached"
            } else {
                "machine-code artifact evidence is retained for this output stream"
            },
        ),
        machine_code_priority_disposition(
            "learning-feedback-after-disposition",
            "ready-to-submit",
            vec![
                format!("releaseBlocked:{release_blocked}"),
                format!("machineCodeSuccess:{request_success}"),
            ],
            vec![
                "POST /fabrication/learning/outcomes",
                "GET /fabrication/learning/replay/catalog",
                "GET /fabrication/learning/features/catalog",
            ],
            "machine-code disposition is ready for advisory learning, but learning cannot promote machine-ready release without retained validation, simulation, and release evidence",
        ),
    ]
}

fn machine_code_result_review_response(
    request: MachineCodeResultReviewRequest,
) -> Result<Value, String> {
    let request_id = request_id(request.request_id.as_ref(), "machine-code-result");
    let generated_at_ms = now_ms();
    let machine_code_result_job_id =
        safe_job_id("machine-code-result", &request_id, generated_at_ms);
    let plan_request_id = validate_optional_label(request.plan_request_id, "planRequestId")?;
    let job_id = validate_optional_label(request.job_id, "jobId")?;
    let worker_id = validate_label(&request.worker_id, "workerId")?;
    let generator = validate_optional_label(request.generator, "generator")?;
    let generator_version =
        validate_optional_text(request.generator_version, "generatorVersion", MAX_LABEL_LEN)?;
    let machine_id = validate_optional_label(request.machine_id, "machineId")?;
    let machine_kind = validate_optional_label(request.machine_kind, "machineKind")?;
    let controller = validate_optional_label(request.controller, "controller")?;
    let postprocessor = validate_optional_label(request.postprocessor, "postprocessor")?;
    let release_ready = request.release_ready.unwrap_or(false);
    let programs = validate_machine_code_result_programs(request.programs)?;
    let controller_checks =
        validate_machine_code_result_controller_checks(request.controller_checks)?;
    let failure_boundaries =
        validate_machine_code_result_failure_boundaries(request.failure_boundaries)?;
    let artifacts = validate_machine_code_result_artifacts(request.artifacts)?;
    let warnings = validate_signal_list(request.warnings, "warnings", MAX_TEXT_LEN)?;

    let program_blocker_count = programs
        .iter()
        .filter(|program| machine_code_result_program_blocks_release(program))
        .count();
    let controller_check_blocker_count = controller_checks
        .iter()
        .filter(|check| machine_code_result_controller_check_blocks_release(check))
        .count();
    let boundary_blocker_count = failure_boundaries
        .iter()
        .filter(|boundary| machine_code_result_boundary_blocks_release(boundary))
        .count();
    let human_intervention_check_count = controller_checks
        .iter()
        .filter(|check| {
            check
                .get("requiresHumanIntervention")
                .and_then(Value::as_bool)
                .unwrap_or(false)
        })
        .count();
    let human_intervention_boundary_count = failure_boundaries
        .iter()
        .filter(|boundary| {
            boundary
                .get("requiresHumanIntervention")
                .and_then(Value::as_bool)
                .unwrap_or(false)
        })
        .count();
    let missing_program_evidence_count = programs
        .iter()
        .filter(|program| machine_code_result_program_missing_release_evidence(program))
        .count();
    let missing_artifact_evidence_count = artifacts
        .iter()
        .filter(|artifact| machine_code_result_artifact_missing_release_evidence(artifact))
        .count();
    let artifact_evidence_missing = artifacts.is_empty()
        || missing_artifact_evidence_count > 0
        || missing_program_evidence_count > 0;
    let human_intervention_required =
        human_intervention_check_count > 0 || human_intervention_boundary_count > 0;
    let release_blocked = !request.success
        || !request.machine_ready
        || !release_ready
        || programs.is_empty()
        || program_blocker_count > 0
        || controller_check_blocker_count > 0
        || boundary_blocker_count > 0
        || artifact_evidence_missing;
    let priority_dispositions = machine_code_priority_dispositions(
        request.success,
        release_blocked,
        program_blocker_count,
        controller_check_blocker_count,
        boundary_blocker_count,
        human_intervention_required,
        artifact_evidence_missing,
        &programs,
    );
    let review_status = if programs.is_empty() {
        "machine-code-result-no-programs-release-blocked"
    } else if !request.success {
        "machine-code-result-worker-failed-release-blocked"
    } else if program_blocker_count > 0 {
        "machine-code-result-programs-release-blocked"
    } else if controller_check_blocker_count > 0 {
        "machine-code-result-controller-checks-release-blocked"
    } else if boundary_blocker_count > 0 {
        "machine-code-result-boundaries-release-blocked"
    } else if artifact_evidence_missing {
        "machine-code-result-artifact-evidence-required"
    } else if !request.machine_ready {
        "machine-code-result-machine-ready-review-required"
    } else if !release_ready {
        "machine-code-result-release-ready-review-required"
    } else {
        "machine-code-result-ready-for-release-review"
    };

    let mut learning_observations = vec![
        format!("machine-code-worker:{worker_id}"),
        format!("machine-code-result:{review_status}"),
    ];
    if let Some(generator) = generator.as_ref() {
        learning_observations.push(format!(
            "machine-code-generator:{}",
            normalize_token(generator)
        ));
    }
    if let Some(controller) = controller.as_ref() {
        learning_observations.push(format!(
            "machine-code-controller:{}",
            normalize_token(controller)
        ));
    }
    if let Some(postprocessor) = postprocessor.as_ref() {
        learning_observations.push(format!(
            "machine-code-postprocessor:{}",
            normalize_token(postprocessor)
        ));
    }
    if let Some(machine_id) = machine_id.as_ref() {
        learning_observations.push(format!(
            "machine-code-machine:{}",
            normalize_token(machine_id)
        ));
    }
    if let Some(machine_kind) = machine_kind.as_ref() {
        learning_observations.push(format!(
            "machine-code-machine-kind:{}",
            normalize_token(machine_kind)
        ));
    }
    if release_blocked {
        learning_observations.push("machine-code:release-blocked".to_string());
    }
    if human_intervention_required {
        learning_observations.push("machine-code:human-intervention-required".to_string());
    }
    if artifact_evidence_missing {
        learning_observations.push("machine-code:artifact-evidence-missing".to_string());
    }
    if program_blocker_count > 0 {
        learning_observations.push("machine-code:program-blocked".to_string());
    }
    if controller_check_blocker_count > 0 {
        learning_observations.push("machine-code:controller-check-blocked".to_string());
    }
    if boundary_blocker_count > 0 {
        learning_observations.push("machine-code:boundary-blocked".to_string());
    }
    learning_observations.extend(programs.iter().filter_map(|program| {
        program
            .get("language")
            .and_then(Value::as_str)
            .map(|language| {
                format!(
                    "machine-code-program-language:{}",
                    normalize_token(language)
                )
            })
    }));
    learning_observations.extend(programs.iter().filter_map(|program| {
        program
            .get("status")
            .and_then(Value::as_str)
            .map(|status| format!("machine-code-program-status:{}", normalize_token(status)))
    }));
    learning_observations.extend(controller_checks.iter().filter_map(|check| {
        check
            .get("checkKind")
            .and_then(Value::as_str)
            .map(|kind| format!("machine-code-check:{}", normalize_token(kind)))
    }));
    learning_observations.extend(controller_checks.iter().filter_map(|check| {
        check
            .get("status")
            .and_then(Value::as_str)
            .map(|status| format!("machine-code-check-status:{}", normalize_token(status)))
    }));
    learning_observations.extend(failure_boundaries.iter().filter_map(|boundary| {
        boundary
            .get("boundaryKind")
            .and_then(Value::as_str)
            .map(|kind| format!("machine-code-boundary:{}", normalize_token(kind)))
    }));
    learning_observations.extend(failure_boundaries.iter().filter_map(|boundary| {
        boundary
            .get("code")
            .and_then(Value::as_str)
            .map(|code| format!("machine-code-boundary-code:{}", normalize_token(code)))
    }));
    learning_observations.extend(failure_boundaries.iter().filter_map(|boundary| {
        boundary
            .get("recommendedAction")
            .and_then(Value::as_str)
            .map(|action| {
                format!(
                    "machine-code-recommended-action:{}",
                    normalize_token(action)
                )
            })
    }));
    learning_observations.extend(artifacts.iter().filter_map(|artifact| {
        artifact
            .get("artifactKind")
            .and_then(Value::as_str)
            .map(|kind| format!("machine-code-artifact:{}", normalize_token(kind)))
    }));
    learning_observations.extend(priority_dispositions.iter().filter_map(|disposition| {
        disposition
            .get("learningObservation")
            .and_then(Value::as_str)
            .map(str::to_string)
    }));
    learning_observations.sort();
    learning_observations.dedup();

    Ok(json!({
        "ok": true,
        "service": SERVICE_NAME,
        "schemaVersion": "dd.fabrication.machine-code-result-review.v1",
        "serviceSchemaVersion": SCHEMA_VERSION,
        "requestId": request_id,
        "machineCodeResultJobId": machine_code_result_job_id,
        "generatedAtMs": generated_at_ms,
        "routes": [
            "POST /machine-code/result",
            "POST /fabrication/machine-code/result"
        ],
        "generationRoutes": [
            "POST /machine-code/generate",
            "POST /fabrication/machine-code/generate",
            "POST /instructions/generate",
            "POST /fabrication/instructions/generate"
        ],
        "toolpathRoutes": [
            "POST /toolpaths/plan",
            "POST /fabrication/toolpaths/plan",
            "POST /toolpaths/result",
            "POST /fabrication/toolpaths/result"
        ],
        "controllerRoutes": [
            "GET /controllers/catalog",
            "GET /fabrication/controllers/catalog"
        ],
        "simulationRoutes": [
            "POST /simulation/run",
            "POST /fabrication/simulation/run",
            "POST /simulation/result",
            "POST /fabrication/simulation/result"
        ],
        "releaseRoutes": [
            "POST /release/preview",
            "POST /fabrication/release/preview",
            "POST /release/result",
            "POST /fabrication/release/result"
        ],
        "reviewStatus": review_status,
        "machineReady": request.machine_ready && !release_blocked,
        "releaseReady": release_ready && !release_blocked,
        "releaseBlocked": release_blocked,
        "programCount": programs.len(),
        "programBlockerCount": program_blocker_count,
        "controllerCheckCount": controller_checks.len(),
        "controllerCheckBlockerCount": controller_check_blocker_count,
        "failureBoundaryCount": failure_boundaries.len(),
        "boundaryBlockerCount": boundary_blocker_count,
        "humanInterventionCheckCount": human_intervention_check_count,
        "humanInterventionBoundaryCount": human_intervention_boundary_count,
        "artifactCount": artifacts.len(),
        "missingProgramEvidenceCount": missing_program_evidence_count,
        "missingArtifactEvidenceCount": missing_artifact_evidence_count,
        "artifactEvidenceMissing": artifact_evidence_missing,
        "humanInterventionRequired": human_intervention_required,
        "warningCount": warnings.len(),
        "priorityDispositions": priority_dispositions.clone(),
        "machineCodeResult": {
            "planRequestId": plan_request_id,
            "jobId": job_id,
            "workerId": worker_id,
            "generator": generator,
            "generatorVersion": generator_version,
            "machineId": machine_id,
            "machineKind": machine_kind,
            "controller": controller,
            "postprocessor": postprocessor,
            "success": request.success,
            "machineReady": request.machine_ready,
            "releaseReady": release_ready,
            "programs": programs,
            "controllerChecks": controller_checks,
            "failureBoundaries": failure_boundaries,
            "artifacts": artifacts,
            "warnings": warnings,
            "reviewMetadata": request.review_metadata
        },
        "releaseUpdate": {
            "machineReleaseBlocked": release_blocked,
            "requiredBeforeMachineReady": [
                "controller-specific machine-code output is retained with URI, checksum, postprocessor, and controller dialect evidence",
                "controller checks prove modal state, offsets, macros, units, and postprocessor assumptions are compatible with the selected machine",
                "failure boundaries and human-intervention gates are resolved or routed into execution, simulation, and release-package reviews",
                "simulation or dry-run evidence and operator or automation signoff are retained before machine-ready release"
            ],
            "targetSurfaces": [
                "generatedPrograms",
                "controllerPlan",
                "instructionIntentMap.reviewPriorities",
                "postprocessPlan",
                "simulation",
                "executionPlan",
                "machineRelease",
                "releasePackagePlan",
                "learning.outcomes"
            ]
        },
        "learning": {
            "observations": learning_observations,
            "engineTargets": ["MDP", "POMDP", "neural"],
            "outcomeRoute": "POST /fabrication/learning/outcomes",
            "outcomeDraft": {
                "schemaVersion": "dd.fabrication.machine-code-learning-outcome-draft.v1",
                "sourceKind": "machine-code-result",
                "sourceJobId": machine_code_result_job_id,
                "sourceRequestId": request_id,
                "success": !release_blocked,
                "rewardHint": if release_blocked { -0.8 } else { 0.6 },
                "machineKind": machine_kind,
                "controller": controller,
                "postprocessor": postprocessor,
                "methodHints": programs
                    .iter()
                    .filter_map(|program| program.get("language").and_then(Value::as_str))
                    .collect::<Vec<_>>(),
                "boundaryHints": failure_boundaries
                    .iter()
                    .filter_map(|boundary| boundary.get("boundaryKind").and_then(Value::as_str))
                    .collect::<Vec<_>>(),
                "featureHints": [
                    format!("program-blockers:{program_blocker_count}"),
                    format!("controller-check-blockers:{controller_check_blocker_count}"),
                    format!("boundary-blockers:{boundary_blocker_count}"),
                    format!("human-intervention-required:{human_intervention_required}"),
                    format!("artifact-evidence-missing:{artifact_evidence_missing}"),
                    format!("priority-dispositions:{}", priority_dispositions.len())
                ],
                "priorityDispositions": priority_dispositions,
                "recommendedActions": failure_boundaries
                    .iter()
                    .filter_map(|boundary| boundary.get("recommendedAction").and_then(Value::as_str))
                    .collect::<Vec<_>>(),
                "recommendedSubmitRoute": "POST /fabrication/learning/outcomes"
            }
        },
        "artifactSurfaces": [
            "machine-code-result",
            "machine-code-programs",
            "machine-code-controller-checks",
            "machine-code-failure-boundaries",
            "machine-code-artifacts",
            "machine-code-priority-dispositions",
            "machine-code-learning-observations",
            "generated-machine-program",
            "controller-plan",
            "postprocess-plan",
            "mdp-request.artifacts.machineCodeResult"
        ],
        "machineCodePolicy": [
            "machine-code results are retained controller, postprocessor, CAM, slicer, setup, and dry-run evidence, not certified machine safety approval",
            "machine-ready release remains blocked until controller checks, failure boundaries, retained artifacts, simulation or dry-run evidence, and signoff clear",
            "machine-code result observations feed MDP/POMDP/neural learning so future plans can prefer reliable postprocessors, controllers, machine routes, or human review gates"
        ]
    }))
}

fn machine_code_result_job_severity(response: &Value) -> String {
    let status = response_str_field(response, "reviewStatus", "");
    let release_blocked = response
        .get("releaseBlocked")
        .and_then(Value::as_bool)
        .unwrap_or(true);
    if status.contains("worker-failed")
        || status.contains("no-programs")
        || status.contains("programs-release-blocked")
        || status.contains("controller-checks-release-blocked")
        || status.contains("boundaries-release-blocked")
    {
        "error".to_string()
    } else if release_blocked {
        "warning".to_string()
    } else {
        "ok".to_string()
    }
}

fn stored_machine_code_result_job(response: &Value) -> StoredFabricationJob {
    let generated_at_ms = response_u128_field(response, "generatedAtMs");
    let request_id = response_str_field(response, "requestId", "machine-code-result");
    let job_id = response_str_field(
        response,
        "machineCodeResultJobId",
        &safe_job_id("machine-code-result", &request_id, generated_at_ms),
    );
    let review_status = response_str_field(response, "reviewStatus", "machine-code-result");
    let release_blocked = response
        .get("releaseBlocked")
        .and_then(Value::as_bool)
        .unwrap_or(true);
    let result = response
        .get("machineCodeResult")
        .cloned()
        .unwrap_or(Value::Null);
    let programs = result.get("programs").cloned().unwrap_or_else(|| json!([]));
    let controller_checks = result
        .get("controllerChecks")
        .cloned()
        .unwrap_or_else(|| json!([]));
    let failure_boundaries = result
        .get("failureBoundaries")
        .cloned()
        .unwrap_or_else(|| json!([]));
    let machine_code_artifacts = result
        .get("artifacts")
        .cloned()
        .unwrap_or_else(|| json!([]));
    let priority_dispositions = response
        .get("priorityDispositions")
        .cloned()
        .unwrap_or_else(|| json!([]));
    let learning_observations = response
        .get("learning")
        .and_then(|learning| learning.get("observations"))
        .cloned()
        .unwrap_or_else(|| json!([]));
    let artifacts = vec![
        json_artifact(
            "machine-code-result".to_string(),
            "machine-code-result",
            response.clone(),
            generated_at_ms,
        ),
        json_artifact(
            "machine-code-programs".to_string(),
            "machine-code-programs",
            programs,
            generated_at_ms,
        ),
        json_artifact(
            "machine-code-controller-checks".to_string(),
            "machine-code-controller-checks",
            controller_checks,
            generated_at_ms,
        ),
        json_artifact(
            "machine-code-failure-boundaries".to_string(),
            "machine-code-failure-boundaries",
            failure_boundaries,
            generated_at_ms,
        ),
        json_artifact(
            "machine-code-artifacts".to_string(),
            "machine-code-artifacts",
            machine_code_artifacts,
            generated_at_ms,
        ),
        json_artifact(
            "machine-code-priority-dispositions".to_string(),
            "machine-code-priority-dispositions",
            priority_dispositions,
            generated_at_ms,
        ),
        json_artifact(
            "machine-code-learning-observations".to_string(),
            "machine-code-learning-observations",
            learning_observations,
            generated_at_ms,
        ),
    ]
    .into_iter()
    .map(|artifact| (artifact.artifact_id.clone(), artifact))
    .collect::<BTreeMap<_, _>>();
    let artifact_ids = artifacts.keys().cloned().collect::<Vec<_>>();

    StoredFabricationJob {
        record: FabricationJobRecord {
            job_id,
            request_id,
            kind: "machine-code-result".to_string(),
            status: review_status.clone(),
            ok: !release_blocked,
            severity: machine_code_result_job_severity(response),
            summary: format!("machine-code result review: {review_status}"),
            artifact_count: artifact_ids.len(),
            artifact_ids,
            created_at_ms: generated_at_ms,
            updated_at_ms: generated_at_ms,
        },
        plan: None,
        analysis: None,
        learning: None,
        artifacts,
    }
}

fn store_machine_code_result_response(state: &AppState, response: &Value) {
    store_job(state, stored_machine_code_result_job(response));
}

fn validate_instruction_review_result_findings(
    findings: Option<Vec<InstructionReviewResultFinding>>,
) -> Result<Vec<Value>, String> {
    let findings = findings.unwrap_or_default();
    if findings.len() > MAX_LEARNING_SIGNALS {
        return Err(format!(
            "findings must contain at most {MAX_LEARNING_SIGNALS} entries"
        ));
    }
    let mut seen = BTreeSet::new();
    findings
        .into_iter()
        .enumerate()
        .map(|(index, finding)| {
            let finding_id =
                validate_label(&finding.finding_id, &format!("findings[{index}].findingId"))?;
            if !seen.insert(finding_id.clone()) {
                return Err(format!(
                    "findings must have unique findingId values; duplicate {finding_id}"
                ));
            }
            Ok(json!({
                "findingId": finding_id,
                "severity": validate_label(&finding.severity, &format!("findings[{index}].severity"))?,
                "code": validate_label(&finding.code, &format!("findings[{index}].code"))?,
                "message": validate_text(&finding.message, &format!("findings[{index}].message"), MAX_TEXT_LEN)?,
                "instructionId": validate_optional_label(finding.instruction_id, &format!("findings[{index}].instructionId"))?,
                "scopeId": validate_optional_label(finding.scope_id, &format!("findings[{index}].scopeId"))?,
                "lineRef": validate_optional_text(finding.line_ref, &format!("findings[{index}].lineRef"), MAX_LABEL_LEN)?,
                "machineReadyImpact": validate_optional_text(
                    finding.machine_ready_impact,
                    &format!("findings[{index}].machineReadyImpact"),
                    MAX_LABEL_LEN,
                )?,
                "evidence": validate_signal_list(finding.evidence, &format!("findings[{index}].evidence"), MAX_TEXT_LEN)?
            }))
        })
        .collect()
}

fn validate_instruction_review_result_boundaries(
    boundaries: Option<Vec<InstructionReviewResultBoundary>>,
) -> Result<Vec<Value>, String> {
    let boundaries = boundaries.unwrap_or_default();
    if boundaries.len() > MAX_LEARNING_SIGNALS {
        return Err(format!(
            "failureBoundaries must contain at most {MAX_LEARNING_SIGNALS} entries"
        ));
    }
    let mut seen = BTreeSet::new();
    boundaries
        .into_iter()
        .enumerate()
        .map(|(index, boundary)| {
            let boundary_id = validate_label(
                &boundary.boundary_id,
                &format!("failureBoundaries[{index}].boundaryId"),
            )?;
            if !seen.insert(boundary_id.clone()) {
                return Err(format!(
                    "failureBoundaries must have unique boundaryId values; duplicate {boundary_id}"
                ));
            }
            Ok(json!({
                "boundaryId": boundary_id,
                "boundaryKind": validate_label(&boundary.boundary_kind, &format!("failureBoundaries[{index}].boundaryKind"))?,
                "code": validate_label(&boundary.code, &format!("failureBoundaries[{index}].code"))?,
                "message": validate_text(&boundary.message, &format!("failureBoundaries[{index}].message"), MAX_TEXT_LEN)?,
                "instructionId": validate_optional_label(boundary.instruction_id, &format!("failureBoundaries[{index}].instructionId"))?,
                "lineRef": validate_optional_text(boundary.line_ref, &format!("failureBoundaries[{index}].lineRef"), MAX_LABEL_LEN)?,
                "humanInterventionRequired": boundary.human_intervention_required.unwrap_or(false),
                "recommendedAction": validate_optional_text(
                    boundary.recommended_action,
                    &format!("failureBoundaries[{index}].recommendedAction"),
                    MAX_LABEL_LEN,
                )?,
                "evidence": validate_signal_list(boundary.evidence, &format!("failureBoundaries[{index}].evidence"), MAX_TEXT_LEN)?
            }))
        })
        .collect()
}

fn validate_instruction_review_result_improvements(
    drafts: Option<Vec<InstructionReviewResultImprovementDraft>>,
) -> Result<Vec<Value>, String> {
    let drafts = drafts.unwrap_or_default();
    if drafts.len() > MAX_LEARNING_SIGNALS {
        return Err(format!(
            "improvementDrafts must contain at most {MAX_LEARNING_SIGNALS} entries"
        ));
    }
    let mut seen = BTreeSet::new();
    drafts
        .into_iter()
        .enumerate()
        .map(|(index, draft)| {
            let draft_id =
                validate_label(&draft.draft_id, &format!("improvementDrafts[{index}].draftId"))?;
            if !seen.insert(draft_id.clone()) {
                return Err(format!(
                    "improvementDrafts must have unique draftId values; duplicate {draft_id}"
                ));
            }
            Ok(json!({
                "draftId": draft_id,
                "instructionId": validate_label(&draft.instruction_id, &format!("improvementDrafts[{index}].instructionId"))?,
                "draftKind": validate_label(&draft.draft_kind, &format!("improvementDrafts[{index}].draftKind"))?,
                "summary": validate_text(&draft.summary, &format!("improvementDrafts[{index}].summary"), MAX_TEXT_LEN)?,
                "patchUri": validate_optional_text(draft.patch_uri, &format!("improvementDrafts[{index}].patchUri"), MAX_TEXT_LEN)?,
                "previewLines": validate_signal_list(draft.preview_lines, &format!("improvementDrafts[{index}].previewLines"), MAX_TEXT_LEN)?,
                "requiresHumanApproval": draft.requires_human_approval.unwrap_or(false),
                "evidence": validate_signal_list(draft.evidence, &format!("improvementDrafts[{index}].evidence"), MAX_TEXT_LEN)?
            }))
        })
        .collect()
}

fn review_finding_blocks_machine_ready(finding: &Value) -> bool {
    let severity = finding
        .get("severity")
        .and_then(Value::as_str)
        .map(normalize_token)
        .unwrap_or_default();
    let impact = finding
        .get("machineReadyImpact")
        .and_then(Value::as_str)
        .map(normalize_token)
        .unwrap_or_default();
    matches!(severity.as_str(), "error" | "blocker" | "critical")
        || impact.contains("block")
        || impact.contains("operator")
}

fn values_contain_review_tokens(values: &[Value], tokens: &[&str]) -> bool {
    values.iter().any(|value| {
        let text = normalize_token(&value.to_string());
        tokens.iter().any(|token| text.contains(token))
    })
}

fn instruction_review_priority_disposition(
    priority_id: &str,
    disposition: &str,
    evidence: Vec<String>,
    next_routes: Vec<&str>,
    release_impact: &str,
) -> Value {
    instruction_priority_disposition(
        "instruction-review-priority",
        priority_id,
        disposition,
        evidence,
        next_routes,
        release_impact,
    )
}

fn instruction_validation_priority_disposition(
    priority_id: &str,
    disposition: &str,
    evidence: Vec<String>,
    next_routes: Vec<&str>,
    release_impact: &str,
) -> Value {
    instruction_priority_disposition(
        "instruction-validation-priority",
        priority_id,
        disposition,
        evidence,
        next_routes,
        release_impact,
    )
}

fn instruction_priority_disposition(
    observation_prefix: &str,
    priority_id: &str,
    disposition: &str,
    evidence: Vec<String>,
    next_routes: Vec<&str>,
    release_impact: &str,
) -> Value {
    json!({
        "priorityId": priority_id,
        "disposition": disposition,
        "evidence": evidence,
        "nextRoutes": next_routes,
        "releaseImpact": release_impact,
        "learningObservation": format!("{observation_prefix}:{priority_id}:{}", normalize_token(disposition))
    })
}

fn instruction_review_priority_dispositions(
    request_success: bool,
    release_blocked: bool,
    blocking_finding_count: usize,
    human_intervention_boundary_count: usize,
    human_approval_draft_count: usize,
    findings: &[Value],
    failure_boundaries: &[Value],
    improvement_drafts: &[Value],
    warnings: &[String],
) -> Vec<Value> {
    let split_or_interface_review = values_contain_review_tokens(
        failure_boundaries,
        &[
            "split",
            "combine",
            "interface",
            "join",
            "assembly",
            "decomposition",
        ],
    ) || values_contain_review_tokens(
        improvement_drafts,
        &[
            "split",
            "combine",
            "interface",
            "join",
            "assembly",
            "decomposition",
        ],
    );
    let non_gcode_evidence_review = values_contain_review_tokens(
        findings,
        &[
            "job-sheet",
            "setup-sheet",
            "operator",
            "slicer",
            "postprocess",
            "prose",
            "text",
        ],
    ) || values_contain_review_tokens(
        failure_boundaries,
        &[
            "job-sheet",
            "setup-sheet",
            "operator",
            "slicer",
            "postprocess",
            "prose",
            "text",
        ],
    );
    let warning_count = warnings.len();

    vec![
        instruction_review_priority_disposition(
            "machine-failure-boundary-first",
            if blocking_finding_count > 0 || !failure_boundaries.is_empty() {
                "blocked"
            } else if request_success && !release_blocked {
                "closed"
            } else {
                "needs-review"
            },
            vec![
                format!("blockingFindingCount:{blocking_finding_count}"),
                format!("failureBoundaryCount:{}", failure_boundaries.len()),
            ],
            vec![
                "POST /fabrication/instructions/validate",
                "POST /fabrication/simulation/run",
                "POST /fabrication/release/result",
            ],
            if blocking_finding_count > 0 || !failure_boundaries.is_empty() {
                "machineReady remains blocked by machine-failure review priority"
            } else {
                "machine-failure review priority has no open blocker in this result"
            },
        ),
        instruction_review_priority_disposition(
            "human-intervention-required",
            if human_intervention_boundary_count > 0 || human_approval_draft_count > 0 {
                "blocked"
            } else if request_success && !release_blocked {
                "closed"
            } else {
                "needs-review"
            },
            vec![
                format!("humanInterventionBoundaryCount:{human_intervention_boundary_count}"),
                format!("humanApprovalDraftCount:{human_approval_draft_count}"),
            ],
            vec![
                "POST /fabrication/interventions/result",
                "POST /fabrication/execution/plan",
                "POST /fabrication/release/result",
            ],
            if human_intervention_boundary_count > 0 || human_approval_draft_count > 0 {
                "machineReady remains blocked until operator or automation signoff is retained"
            } else {
                "human-intervention review priority has no open blocker in this result"
            },
        ),
        instruction_review_priority_disposition(
            "split-combine-or-interface-review",
            if split_or_interface_review {
                "blocked"
            } else if request_success && !release_blocked {
                "closed"
            } else {
                "not-observed"
            },
            vec![format!("splitOrInterfaceEvidence:{split_or_interface_review}")],
            vec![
                "POST /fabrication/decomposition/plan",
                "POST /fabrication/interfaces/result",
                "POST /fabrication/assembly/plan",
                "POST /fabrication/release/result",
            ],
            if split_or_interface_review {
                "machineReady remains blocked until split/combine or interface evidence is retained"
            } else {
                "no split/combine or interface priority evidence was reported by this review"
            },
        ),
        instruction_review_priority_disposition(
            "non-gcode-job-sheet-evidence",
            if non_gcode_evidence_review && release_blocked {
                "partially-reviewed"
            } else if non_gcode_evidence_review {
                "closed"
            } else {
                "not-observed"
            },
            vec![
                format!("nonGcodeEvidence:{non_gcode_evidence_review}"),
                format!("warningCount:{warning_count}"),
            ],
            vec![
                "POST /fabrication/instructions/import/review",
                "POST /fabrication/instructions/improve",
                "POST /fabrication/release/result",
            ],
            if non_gcode_evidence_review && release_blocked {
                "text or controller-external evidence still needs retained scope, owner, or release proof"
            } else {
                "no open non-G-code evidence blocker was reported by this review"
            },
        ),
        instruction_review_priority_disposition(
            "learning-feedback-after-disposition",
            "ready-to-submit",
            vec![
                format!("releaseBlocked:{release_blocked}"),
                format!("reviewSuccess:{request_success}"),
            ],
            vec![
                "POST /fabrication/learning/outcomes",
                "GET /fabrication/learning/replay/catalog",
                "GET /fabrication/learning/features/catalog",
            ],
            "review disposition is ready for advisory learning, but learning cannot promote machine-ready release without retained validation and release evidence",
        ),
    ]
}

fn instruction_review_result_review_response(
    request: InstructionReviewResultReviewRequest,
) -> Result<Value, String> {
    let request_id = request_id(request.request_id.as_ref(), "instruction-review-result");
    let generated_at_ms = now_ms();
    let review_result_job_id =
        safe_job_id("instruction-review-result", &request_id, generated_at_ms);
    let plan_request_id = validate_optional_label(request.plan_request_id, "planRequestId")?;
    let job_id = validate_optional_label(request.job_id, "jobId")?;
    let worker_id = validate_label(&request.worker_id, "workerId")?;
    let reviewer = validate_optional_text(request.reviewer, "reviewer", MAX_LABEL_LEN)?;
    let reviewer_version =
        validate_optional_text(request.reviewer_version, "reviewerVersion", MAX_LABEL_LEN)?;
    let findings = validate_instruction_review_result_findings(request.findings)?;
    let failure_boundaries =
        validate_instruction_review_result_boundaries(request.failure_boundaries)?;
    let improvement_drafts =
        validate_instruction_review_result_improvements(request.improvement_drafts)?;
    let warnings = validate_signal_list(request.warnings, "warnings", MAX_TEXT_LEN)?;
    let blocking_finding_count = findings
        .iter()
        .filter(|finding| review_finding_blocks_machine_ready(finding))
        .count();
    let human_intervention_boundary_count = failure_boundaries
        .iter()
        .filter(|boundary| {
            boundary
                .get("humanInterventionRequired")
                .and_then(Value::as_bool)
                .unwrap_or(false)
        })
        .count();
    let human_approval_draft_count = improvement_drafts
        .iter()
        .filter(|draft| {
            draft
                .get("requiresHumanApproval")
                .and_then(Value::as_bool)
                .unwrap_or(false)
        })
        .count();
    let release_blocked = !request.success
        || !request.machine_ready
        || blocking_finding_count > 0
        || !failure_boundaries.is_empty()
        || human_approval_draft_count > 0;
    let priority_dispositions = instruction_review_priority_dispositions(
        request.success,
        release_blocked,
        blocking_finding_count,
        human_intervention_boundary_count,
        human_approval_draft_count,
        &findings,
        &failure_boundaries,
        &improvement_drafts,
        &warnings,
    );
    let review_status = if !request.success {
        "instruction-review-worker-failed-release-blocked"
    } else if blocking_finding_count > 0 {
        "instruction-review-findings-release-blocked"
    } else if !failure_boundaries.is_empty() {
        "instruction-review-boundaries-resolution-required"
    } else if human_approval_draft_count > 0 {
        "instruction-review-improvement-approval-required"
    } else if request.machine_ready {
        "instruction-review-result-ready-for-release-review"
    } else {
        "instruction-review-result-machine-ready-review-required"
    };
    let mut learning_observations = vec![
        format!("instruction-review-worker:{worker_id}"),
        format!("instruction-review-result:{review_status}"),
    ];
    if let Some(reviewer) = reviewer.as_ref() {
        learning_observations.push(format!(
            "instruction-review-reviewer:{}",
            normalize_token(reviewer)
        ));
    }
    if release_blocked {
        learning_observations.push("instruction-review:release-blocked".to_string());
    }
    if human_intervention_boundary_count > 0 {
        learning_observations.push("instruction-review:human-intervention-required".to_string());
    }
    if human_approval_draft_count > 0 {
        learning_observations
            .push("instruction-review:improvement-human-approval-required".to_string());
    }
    learning_observations.extend(findings.iter().filter_map(|finding| {
        finding
            .get("code")
            .and_then(Value::as_str)
            .map(|code| format!("instruction-review-finding:{}", normalize_token(code)))
    }));
    learning_observations.extend(failure_boundaries.iter().filter_map(|boundary| {
        boundary
            .get("code")
            .and_then(Value::as_str)
            .map(|code| format!("instruction-review-boundary:{}", normalize_token(code)))
    }));
    learning_observations.extend(failure_boundaries.iter().filter_map(|boundary| {
        boundary
            .get("boundaryKind")
            .and_then(Value::as_str)
            .map(|kind| format!("instruction-review-boundary-kind:{}", normalize_token(kind)))
    }));
    learning_observations.extend(failure_boundaries.iter().filter_map(|boundary| {
        boundary
            .get("recommendedAction")
            .and_then(Value::as_str)
            .map(|action| {
                format!(
                    "instruction-review-recommended-action:{}",
                    normalize_token(action)
                )
            })
    }));
    learning_observations.extend(improvement_drafts.iter().filter_map(|draft| {
        draft
            .get("draftKind")
            .and_then(Value::as_str)
            .map(|kind| format!("instruction-review-improvement:{}", normalize_token(kind)))
    }));
    learning_observations.extend(priority_dispositions.iter().filter_map(|disposition| {
        disposition
            .get("learningObservation")
            .and_then(Value::as_str)
            .map(str::to_string)
    }));
    learning_observations.sort();
    learning_observations.dedup();

    Ok(json!({
        "ok": true,
        "service": SERVICE_NAME,
        "schemaVersion": "dd.fabrication.instruction-review-result-review.v1",
        "serviceSchemaVersion": SCHEMA_VERSION,
        "requestId": request_id,
        "reviewResultJobId": review_result_job_id,
        "generatedAtMs": generated_at_ms,
        "routes": [
            "POST /instructions/review/result",
            "POST /fabrication/instructions/review/result"
        ],
        "requestSubject": FABRICATION_INSTRUCTION_REVIEW_REQUESTS_SUBJECT,
        "resultSubject": FABRICATION_INSTRUCTION_REVIEW_RESULTS_SUBJECT,
        "queueGroup": FABRICATION_INSTRUCTION_REVIEW_REQUESTS_QUEUE_GROUP,
        "reviewRoutes": [
            "POST /instructions/analyze",
            "POST /fabrication/instructions/analyze",
            "POST /instructions/validate",
            "POST /fabrication/instructions/validate",
            "POST /instructions/improve",
            "POST /fabrication/instructions/improve"
        ],
        "catalogRoutes": [
            "GET /instructions/languages",
            "GET /fabrication/instructions/languages",
            "GET /boundaries/catalog",
            "GET /fabrication/boundaries/catalog",
            "GET /improvements/catalog",
            "GET /fabrication/improvements/catalog"
        ],
        "reviewStatus": review_status,
        "machineReady": request.machine_ready && !release_blocked,
        "releaseBlocked": release_blocked,
        "findingCount": findings.len(),
        "blockingFindingCount": blocking_finding_count,
        "failureBoundaryCount": failure_boundaries.len(),
        "humanInterventionBoundaryCount": human_intervention_boundary_count,
        "improvementDraftCount": improvement_drafts.len(),
        "humanApprovalDraftCount": human_approval_draft_count,
        "warningCount": warnings.len(),
        "priorityDispositions": priority_dispositions.clone(),
        "instructionReviewResult": {
            "planRequestId": plan_request_id,
            "jobId": job_id,
            "workerId": worker_id,
            "reviewer": reviewer,
            "reviewerVersion": reviewer_version,
            "success": request.success,
            "machineReady": request.machine_ready,
            "findings": findings,
            "failureBoundaries": failure_boundaries,
            "improvementDrafts": improvement_drafts,
            "warnings": warnings,
            "reviewMetadata": request.review_metadata
        },
        "releaseUpdate": {
            "machineReleaseBlocked": release_blocked,
            "requiredBeforeMachineReady": [
                "blocking validation findings folded into validation and machineRelease",
                "machine-failure and human-intervention boundaries resolved or explicitly accepted",
                "improvement drafts reviewed into improvedPrograms and executionPlan",
                "operator or automation signoff attached for split/combine, pause, or manual intervention decisions"
            ],
            "targetSurfaces": [
                "validation.findings",
                "validation.failureBoundaries",
                "boundarySummary",
                "resolutionPlan.steps",
                "interventionMap",
                "instructionIntentMap.reviewPriorities",
                "improvedPrograms",
                "machineRelease.blockers"
            ]
        },
        "learning": {
            "observations": learning_observations,
            "engineTargets": ["MDP", "POMDP", "neural"],
            "outcomeRoute": "POST /fabrication/learning/outcomes",
            "outcomeDraft": {
                "schemaVersion": "dd.fabrication.instruction-review-learning-outcome-draft.v1",
                "sourceKind": "instruction-review-result",
                "sourceJobId": review_result_job_id,
                "sourceRequestId": request_id,
                "success": !release_blocked,
                "rewardHint": if release_blocked { -0.7 } else { 0.55 },
                "reviewer": reviewer,
                "findingHints": findings
                    .iter()
                    .filter_map(|finding| finding.get("code").and_then(Value::as_str))
                    .collect::<Vec<_>>(),
                "boundaryHints": failure_boundaries
                    .iter()
                    .filter_map(|boundary| boundary.get("boundaryKind").and_then(Value::as_str))
                    .collect::<Vec<_>>(),
                "improvementHints": improvement_drafts
                    .iter()
                    .filter_map(|draft| draft.get("draftKind").and_then(Value::as_str))
                    .collect::<Vec<_>>(),
                "recommendedActions": failure_boundaries
                    .iter()
                    .filter_map(|boundary| boundary.get("recommendedAction").and_then(Value::as_str))
                    .collect::<Vec<_>>(),
                "featureHints": [
                    format!("blocking-findings:{blocking_finding_count}"),
                    format!("failure-boundaries:{}", failure_boundaries.len()),
                    format!("human-intervention-boundaries:{human_intervention_boundary_count}"),
                    format!("human-approval-drafts:{human_approval_draft_count}"),
                    format!("priority-dispositions:{}", priority_dispositions.len())
                ],
                "priorityDispositions": priority_dispositions,
                "recommendedSubmitRoute": "POST /fabrication/learning/outcomes"
            }
        },
        "artifactSurfaces": [
            "instruction-review-result",
            "analysis-validation-report",
            "analysis-boundary-summary",
            "analysis-resolution-plan",
            "analysis-improvements",
            "improved-program-*",
            "analysis-mdp-request"
        ],
        "releasePolicy": [
            "instruction review results are worker evidence for imported CNC, printer, slicer, setup-sheet, postprocess, assembly, or operator instruction streams",
            "machine-ready release remains blocked until validation findings, failure boundaries, improvement drafts, simulation or dry-run evidence, controller review, and signoff gates clear",
            "review result observations feed MDP/POMDP/neural learning so future plans can prefer reliable parsers, validators, boundary analyzers, and improvement workers"
        ]
    }))
}

fn instruction_review_result_job_severity(response: &Value) -> String {
    let status = response_str_field(response, "reviewStatus", "");
    let release_blocked = response
        .get("releaseBlocked")
        .and_then(Value::as_bool)
        .unwrap_or(true);
    if status.contains("worker-failed")
        || status.contains("findings-release-blocked")
        || status.contains("boundaries")
    {
        "error".to_string()
    } else if release_blocked {
        "warning".to_string()
    } else {
        "ok".to_string()
    }
}

fn stored_instruction_review_result_job(response: &Value) -> StoredFabricationJob {
    let generated_at_ms = response_u128_field(response, "generatedAtMs");
    let request_id = response_str_field(response, "requestId", "instruction-review-result");
    let job_id = response_str_field(
        response,
        "reviewResultJobId",
        &safe_job_id("instruction-review-result", &request_id, generated_at_ms),
    );
    let review_status = response_str_field(response, "reviewStatus", "instruction-review-result");
    let release_blocked = response
        .get("releaseBlocked")
        .and_then(Value::as_bool)
        .unwrap_or(true);
    let result = response
        .get("instructionReviewResult")
        .cloned()
        .unwrap_or(Value::Null);
    let findings = result.get("findings").cloned().unwrap_or_else(|| json!([]));
    let failure_boundaries = result
        .get("failureBoundaries")
        .cloned()
        .unwrap_or_else(|| json!([]));
    let improvement_drafts = result
        .get("improvementDrafts")
        .cloned()
        .unwrap_or_else(|| json!([]));
    let warnings = result.get("warnings").cloned().unwrap_or_else(|| json!([]));
    let priority_dispositions = response
        .get("priorityDispositions")
        .cloned()
        .unwrap_or_else(|| json!([]));
    let release_update = response
        .get("releaseUpdate")
        .cloned()
        .unwrap_or_else(|| json!({}));
    let learning_observations = response
        .get("learning")
        .and_then(|learning| learning.get("observations"))
        .cloned()
        .unwrap_or_else(|| json!([]));
    let artifacts = vec![
        json_artifact(
            "instruction-review-result".to_string(),
            "instruction-review-result",
            response.clone(),
            generated_at_ms,
        ),
        json_artifact(
            "instruction-review-findings".to_string(),
            "instruction-review-findings",
            findings,
            generated_at_ms,
        ),
        json_artifact(
            "instruction-review-failure-boundaries".to_string(),
            "instruction-review-failure-boundaries",
            failure_boundaries,
            generated_at_ms,
        ),
        json_artifact(
            "instruction-review-improvement-drafts".to_string(),
            "instruction-review-improvement-drafts",
            improvement_drafts,
            generated_at_ms,
        ),
        json_artifact(
            "instruction-review-warnings".to_string(),
            "instruction-review-warnings",
            warnings,
            generated_at_ms,
        ),
        json_artifact(
            "instruction-review-priority-dispositions".to_string(),
            "instruction-review-priority-dispositions",
            priority_dispositions,
            generated_at_ms,
        ),
        json_artifact(
            "instruction-review-release-update".to_string(),
            "instruction-review-release-update",
            release_update,
            generated_at_ms,
        ),
        json_artifact(
            "instruction-review-learning-observations".to_string(),
            "instruction-review-learning-observations",
            learning_observations,
            generated_at_ms,
        ),
    ]
    .into_iter()
    .map(|artifact| (artifact.artifact_id.clone(), artifact))
    .collect::<BTreeMap<_, _>>();
    let artifact_ids = artifacts.keys().cloned().collect::<Vec<_>>();

    StoredFabricationJob {
        record: FabricationJobRecord {
            job_id,
            request_id,
            kind: "instruction-review-result".to_string(),
            status: review_status.clone(),
            ok: !release_blocked,
            severity: instruction_review_result_job_severity(response),
            summary: format!("instruction review result: {review_status}"),
            artifact_count: artifact_ids.len(),
            artifact_ids,
            created_at_ms: generated_at_ms,
            updated_at_ms: generated_at_ms,
        },
        plan: None,
        analysis: None,
        learning: None,
        artifacts,
    }
}

fn store_instruction_review_result_response(state: &AppState, response: &Value) {
    store_job(state, stored_instruction_review_result_job(response));
}

fn validate_instruction_validation_result_findings(
    findings: Option<Vec<InstructionValidationResultFinding>>,
) -> Result<Vec<Value>, String> {
    let findings = findings.unwrap_or_default();
    if findings.len() > MAX_LEARNING_SIGNALS {
        return Err(format!(
            "findings must contain at most {MAX_LEARNING_SIGNALS} entries"
        ));
    }
    let mut seen = BTreeSet::new();
    findings
        .into_iter()
        .enumerate()
        .map(|(index, finding)| {
            let finding_id =
                validate_label(&finding.finding_id, &format!("findings[{index}].findingId"))?;
            if !seen.insert(finding_id.clone()) {
                return Err(format!(
                    "findings must have unique findingId values; duplicate {finding_id}"
                ));
            }
            Ok(json!({
                "findingId": finding_id,
                "severity": validate_label(&finding.severity, &format!("findings[{index}].severity"))?,
                "code": validate_label(&finding.code, &format!("findings[{index}].code"))?,
                "message": validate_text(&finding.message, &format!("findings[{index}].message"), MAX_TEXT_LEN)?,
                "instructionId": validate_optional_label(finding.instruction_id, &format!("findings[{index}].instructionId"))?,
                "scopeId": validate_optional_label(finding.scope_id, &format!("findings[{index}].scopeId"))?,
                "lineRef": validate_optional_text(finding.line_ref, &format!("findings[{index}].lineRef"), MAX_LABEL_LEN)?,
                "releaseBlocker": finding.release_blocker.unwrap_or(false),
                "humanInterventionRequired": finding.human_intervention_required.unwrap_or(false),
                "evidence": validate_signal_list(finding.evidence, &format!("findings[{index}].evidence"), MAX_TEXT_LEN)?
            }))
        })
        .collect()
}

fn validate_instruction_validation_result_boundaries(
    boundaries: Option<Vec<InstructionValidationResultBoundary>>,
) -> Result<Vec<Value>, String> {
    let boundaries = boundaries.unwrap_or_default();
    if boundaries.len() > MAX_LEARNING_SIGNALS {
        return Err(format!(
            "failureBoundaries must contain at most {MAX_LEARNING_SIGNALS} entries"
        ));
    }
    let mut seen = BTreeSet::new();
    boundaries
        .into_iter()
        .enumerate()
        .map(|(index, boundary)| {
            let boundary_id = validate_label(
                &boundary.boundary_id,
                &format!("failureBoundaries[{index}].boundaryId"),
            )?;
            if !seen.insert(boundary_id.clone()) {
                return Err(format!(
                    "failureBoundaries must have unique boundaryId values; duplicate {boundary_id}"
                ));
            }
            Ok(json!({
                "boundaryId": boundary_id,
                "boundaryKind": validate_label(&boundary.boundary_kind, &format!("failureBoundaries[{index}].boundaryKind"))?,
                "code": validate_label(&boundary.code, &format!("failureBoundaries[{index}].code"))?,
                "message": validate_text(&boundary.message, &format!("failureBoundaries[{index}].message"), MAX_TEXT_LEN)?,
                "instructionId": validate_optional_label(boundary.instruction_id, &format!("failureBoundaries[{index}].instructionId"))?,
                "lineRef": validate_optional_text(boundary.line_ref, &format!("failureBoundaries[{index}].lineRef"), MAX_LABEL_LEN)?,
                "releaseBlocker": boundary.release_blocker.unwrap_or(false),
                "humanInterventionRequired": boundary.human_intervention_required.unwrap_or(false),
                "splitRequired": boundary.split_required.unwrap_or(false),
                "combineRequired": boundary.combine_required.unwrap_or(false),
                "recommendedAction": validate_optional_text(
                    boundary.recommended_action,
                    &format!("failureBoundaries[{index}].recommendedAction"),
                    MAX_LABEL_LEN,
                )?,
                "evidence": validate_signal_list(boundary.evidence, &format!("failureBoundaries[{index}].evidence"), MAX_TEXT_LEN)?
            }))
        })
        .collect()
}

