fn instruction_remediation_plan_actions(response: &InstructionAnalysisResponse) -> Vec<Value> {
    let mut actions = Vec::new();
    for step in &response.resolution_plan.steps {
        actions.push(json!({
            "actionId": format!("remediation-step-{}", step.step),
            "source": "resolutionPlan.steps",
            "phase": &step.phase,
            "action": &step.action,
            "targetState": &step.next_state,
            "boundaryKind": &step.boundary_kind,
            "programId": &step.program_id,
            "line": step.line,
            "requiresHumanIntervention": step.requires_human_intervention,
            "requiredEvidence": [
                "updated instruction draft or retained worker result",
                "validation rerun showing the boundary is cleared",
                "simulation, dry-run, controller, setup, quality, and release signoff evidence"
            ],
            "suggestedResolution": &step.suggested_resolution,
            "routeHandoffs": boundary_remediation_route_handoffs(&step.boundary_kind),
            "learningSignals": boundary_remediation_learning_signals(&step.boundary_kind),
            "machineReadyAfterAction": false
        }));
    }
    for blocker in &response.machine_release.blockers {
        actions.push(json!({
            "actionId": format!("release-blocker-{}", normalize_token(&blocker.blocker_id)),
            "source": "machineRelease.blockers",
            "phase": "release-gate",
            "action": &blocker.required_action,
            "targetState": "release-blocker-cleared",
            "boundaryKind": &blocker.blocker_type,
            "programId": &blocker.program_id,
            "line": blocker.line,
            "severity": &blocker.severity,
            "reason": &blocker.reason,
            "requiresHumanIntervention": blocker.severity == "error",
            "requiredEvidence": [
                "retained evidence artifact for blocker disposition",
                "machine-release preview without this blocker",
                "operator or automation signoff when blocker severity is error"
            ],
            "routeHandoffs": boundary_remediation_route_handoffs(&blocker.blocker_type),
            "learningSignals": boundary_remediation_learning_signals(&blocker.blocker_type),
            "machineReadyAfterAction": false
        }));
    }
    for action in &response
        .operator_intervention_plan
        .required_operator_actions
    {
        actions.push(json!({
            "actionId": format!("operator-action-{}", normalize_token(&action.action_id)),
            "source": "operatorInterventionPlan.requiredOperatorActions",
            "phase": "operator-or-automation-gate",
            "action": &action.required_action,
            "targetState": &action.next_state,
            "boundaryKind": &action.boundary_kind,
            "programId": &action.program_id,
            "line": action.line,
            "partId": &action.part_id,
            "requiresHumanIntervention": true,
            "reason": &action.reason,
            "requiredEvidence": &action.required_evidence,
            "routeHandoffs": [
                "GET /fabrication/interventions/catalog",
                "POST /fabrication/execution/plan",
                "POST /fabrication/monitoring/plan",
                "POST /fabrication/release/preview"
            ],
            "learningSignals": [
                format!("remediation-plan:operator:{}", normalize_token(&action.boundary_kind)),
                format!("remediation-plan:operator-action:{}", normalize_token(&action.required_action))
            ],
            "machineReadyAfterAction": false
        }));
    }
    for review in &response.operator_intervention_plan.split_combine_reviews {
        actions.push(json!({
            "actionId": format!("split-combine-review-{}", normalize_token(&review.review_id)),
            "source": "operatorInterventionPlan.splitCombineReviews",
            "phase": "split-combine-interface-gate",
            "action": &review.action,
            "targetState": "split-combine-interface-evidence-retained",
            "boundaryKind": &review.boundary_kind,
            "programId": &review.program_id,
            "line": review.line,
            "partId": &review.part_id,
            "candidateParts": &review.candidate_parts,
            "requiresHumanIntervention": review.requires_human_intervention,
            "requiredEvidence": &review.required_evidence,
            "routeHandoffs": [
                "GET /fabrication/decomposition/catalog",
                "POST /fabrication/decomposition/plan",
                "POST /fabrication/assembly/plan",
                "POST /fabrication/release/preview"
            ],
            "learningSignals": [
                format!("remediation-plan:split-combine:{}", normalize_token(&review.boundary_kind)),
                "remediation-plan:split-combine-interface".to_string()
            ],
            "machineReadyAfterAction": false
        }));
    }
    for program in response
        .improved_programs
        .iter()
        .filter(|program| program.changed)
    {
        actions.push(json!({
            "actionId": format!("improved-program-review-{}", normalize_token(&program.program_id)),
            "source": "improvedPrograms.patchManifest",
            "phase": "instruction-regeneration",
            "action": "review retained patch manifest and rerun validation before release",
            "targetState": "patched-program-validated",
            "boundaryKind": "instruction-improvement-review",
            "programId": &program.program_id,
            "machineKind": &program.machine_kind,
            "language": &program.language,
            "requiresHumanIntervention": !program.machine_ready,
            "requiredEvidence": [
                "patch manifest retained with operation preview",
                "validation rerun for patched program",
                "simulation or dry-run result for patched program"
            ],
            "routeHandoffs": [
                "POST /fabrication/instructions/improve",
                "POST /fabrication/instructions/validate",
                "POST /fabrication/simulation/run",
                "POST /fabrication/release/preview"
            ],
            "learningSignals": [
                format!("remediation-plan:improved-program:{}", normalize_token(&program.program_id)),
                "remediation-plan:instruction-regeneration".to_string()
            ],
            "machineReadyAfterAction": false
        }));
    }
    actions
}

fn instruction_remediation_plan_route_handoffs(
    response: &InstructionAnalysisResponse,
    actions: &[Value],
) -> Vec<String> {
    let mut handoffs = BTreeSet::from([
        "GET /fabrication/remediation/catalog".to_string(),
        "POST /fabrication/instructions/validate".to_string(),
        "POST /fabrication/release/preview".to_string(),
    ]);
    for boundary in &response.validation.failure_boundaries {
        for route in boundary_remediation_route_handoffs(&boundary.kind) {
            handoffs.insert(route.to_string());
        }
    }
    for action in actions {
        if let Some(routes) = action.get("routeHandoffs").and_then(Value::as_array) {
            for route in routes.iter().filter_map(Value::as_str) {
                handoffs.insert(route.to_string());
            }
        }
    }
    handoffs.into_iter().collect()
}

fn instruction_remediation_plan_learning_signals(
    response: &InstructionAnalysisResponse,
) -> Vec<String> {
    let mut signals = BTreeSet::new();
    for boundary in &response.validation.failure_boundaries {
        signals.insert(format!(
            "remediation-plan:{}",
            normalize_token(&boundary.kind)
        ));
        signals.insert(format!(
            "remediation-plan-severity:{}",
            normalize_token(&boundary.severity)
        ));
    }
    for step in &response.resolution_plan.steps {
        signals.insert(format!(
            "remediation-action:{}",
            normalize_token(&step.action)
        ));
    }
    for review in &response.operator_intervention_plan.split_combine_reviews {
        signals.insert(format!(
            "remediation-split-combine:{}",
            normalize_token(&review.boundary_kind)
        ));
    }
    for signal in &response.learning.intervention_signals {
        signals.insert(format!(
            "remediation-intervention-signal:{}",
            normalize_token(&signal.signal_id)
        ));
    }
    signals.into_iter().collect()
}

fn instruction_remediation_plan_response(response: &InstructionAnalysisResponse) -> Value {
    let actions = instruction_remediation_plan_actions(response);
    let route_handoffs = instruction_remediation_plan_route_handoffs(response, &actions);
    let learning_signals = instruction_remediation_plan_learning_signals(response);
    let release_blocked = response.machine_release.machine_release_blocked
        || !response.validation.failure_boundaries.is_empty()
        || !response
            .operator_intervention_plan
            .required_operator_actions
            .is_empty()
        || !response
            .operator_intervention_plan
            .split_combine_reviews
            .is_empty();
    let human_action_count = actions
        .iter()
        .filter(|action| {
            action
                .get("requiresHumanIntervention")
                .and_then(Value::as_bool)
                .unwrap_or(false)
        })
        .count();
    let split_combine_action_count = actions
        .iter()
        .filter(|action| {
            action
                .get("source")
                .and_then(Value::as_str)
                .is_some_and(|source| source.contains("splitCombine"))
        })
        .count();

    json!({
        "ok": response.ok,
        "service": SERVICE_NAME,
        "schemaVersion": "dd.fabrication.boundary-remediation-planning.v1",
        "serviceSchemaVersion": SCHEMA_VERSION,
        "requestId": &response.request_id,
        "jobId": &response.job_id,
        "routes": ["POST /remediation/plan", "POST /fabrication/remediation/plan"],
        "analysisRoutes": ["POST /instructions/analyze", "POST /fabrication/instructions/analyze"],
        "validationRoutes": ["POST /instructions/validate", "POST /fabrication/instructions/validate"],
        "improvementRoutes": ["POST /instructions/improve", "POST /fabrication/instructions/improve"],
        "boundaryReviewRoutes": [
            "POST /instructions/boundaries/review",
            "POST /fabrication/instructions/boundaries/review"
        ],
        "catalogRoutes": [
            "GET /remediation/catalog",
            "GET /fabrication/remediation/catalog",
            "GET /boundaries/catalog",
            "GET /fabrication/boundaries/catalog",
            "GET /interventions/catalog",
            "GET /fabrication/interventions/catalog",
            "GET /decomposition/catalog",
            "GET /fabrication/decomposition/catalog",
            "GET /release/catalog",
            "GET /fabrication/release/catalog"
        ],
        "machineReady": !release_blocked && actions.is_empty(),
        "machineReleaseBlocked": release_blocked,
        "validationSeverity": &response.validation.severity,
        "boundaryCount": response.validation.failure_boundaries.len(),
        "actionCount": actions.len(),
        "humanActionCount": human_action_count,
        "splitCombineActionCount": split_combine_action_count,
        "responseSurfaces": [
            "validation.failureBoundaries",
            "boundarySummary",
            "resolutionPlan.steps",
            "remediationPlan.actions",
            "interventionMap",
            "operatorInterventionPlan",
            "improvedPrograms.patchManifest",
            "machineRelease.blockers",
            "simulation.failureBoundaries",
            "learning.interventionSignals",
            "neuralTrainingCorpus.examples"
        ],
        "artifactSurfaces": [
            "analysis-validation-report",
            "analysis-boundary-summary",
            "analysis-resolution-plan",
            "analysis-intervention-map",
            "analysis-operator-intervention-plan",
            "analysis-machine-release",
            "analysis-improvements",
            "improved-program-*",
            "analysis-mdp-request"
        ],
        "releasePolicy": [
            "remediation plans are review and worker-handoff contracts for generated or imported fabrication instructions, not corrected controller certification",
            "machineReady=false remains mandatory until remediation evidence, validation, simulation or dry-run evidence, controller/postprocessor review, split/combine review, and operator or automation signoff clear",
            "remediation actions and route handoffs are emitted as MDP/POMDP/neural observations so future jobs can regenerate programs, choose alternate machines, split or combine parts, and insert human checkpoints earlier"
        ],
        "remediationPlan": {
            "schemaVersion": "dd.fabrication.boundary-remediation-plan.v1",
            "status": if release_blocked { "remediation-required" } else { "no-remediation-required" },
            "machineReadyAfterPlan": false,
            "actionCount": actions.len(),
            "routeHandoffs": route_handoffs,
            "requiredEvidenceSurfaces": [
                "updated instruction artifact",
                "validation result",
                "simulation or dry-run result",
                "controller/postprocessor review",
                "setup and monitoring evidence",
                "operator or automation signoff",
                "release package preview"
            ],
            "learningSignals": learning_signals,
            "actions": actions
        },
        "validation": &response.validation,
        "boundarySummary": &response.boundary_summary,
        "resolutionPlan": &response.resolution_plan,
        "interventionMap": &response.intervention_map,
        "operatorInterventionPlan": &response.operator_intervention_plan,
        "machineRelease": &response.machine_release,
        "simulation": &response.simulation,
        "improvements": &response.improvements,
        "improvedPrograms": &response.improved_programs,
        "learning": {
            "desInstructionModel": &response.des_instruction_model,
            "engine": &response.learning.engine,
            "enginePolicy": &response.learning.engine_policy,
            "interventionSignals": &response.learning.intervention_signals,
            "neuralTrainingCorpus": &response.learning.neural_training_corpus
        }
    })
}

fn assembly_joint_type(left: &PartPlan, right: &PartPlan) -> &'static str {
    let left_class = machine_class(&left.machine_kind);
    let right_class = machine_class(&right.machine_kind);
    if matches!(left_class, MachineClass::Additive) && matches!(right_class, MachineClass::Lathe)
        || matches!(right_class, MachineClass::Additive)
            && matches!(left_class, MachineClass::Lathe)
    {
        "printed-pocket-turned-insert"
    } else if matches!(left_class, MachineClass::Additive)
        && matches!(right_class, MachineClass::Mill | MachineClass::Router)
        || matches!(right_class, MachineClass::Additive)
            && matches!(left_class, MachineClass::Mill | MachineClass::Router)
    {
        "printed-shell-machined-datum"
    } else if matches!(left_class, MachineClass::SheetCut)
        || matches!(right_class, MachineClass::SheetCut)
    {
        "tabbed-sheet-register"
    } else if left.manufacturing_method != right.manufacturing_method {
        "hybrid-fastened-interface"
    } else {
        "same-process-alignment-interface"
    }
}

fn assembly_fit(left: &PartPlan, right: &PartPlan) -> &'static str {
    let tightest = left.tolerance_mm.min(right.tolerance_mm);
    if tightest <= 0.05 {
        "metrology-controlled-fit"
    } else if tightest <= 0.12 {
        "controlled-clearance-fit"
    } else {
        "bonded-or-fastened-fit"
    }
}

fn assembly_graph(parts: &[PartPlan]) -> AssemblyGraph {
    let nodes = parts
        .iter()
        .map(|part| AssemblyGraphNode {
            part_id: part.id.clone(),
            manufacturing_method: part.manufacturing_method.clone(),
            machine_kind: part.machine_kind.clone(),
            role: part.role.clone(),
        })
        .collect::<Vec<_>>();

    let mut interfaces = Vec::new();
    let mut sequence = Vec::new();
    if let Some(base) = parts.first() {
        for (index, part) in parts.iter().enumerate().skip(1) {
            let joint_type = assembly_joint_type(base, part);
            let fit = assembly_fit(base, part);
            let interface_id = format!(
                "{}-to-{}-{}",
                normalize_token(&base.id),
                normalize_token(&part.id),
                normalize_token(joint_type)
            );
            let inspection_gate = if fit == "metrology-controlled-fit" {
                "first-article-metrology-and-fit-check"
            } else {
                "dry-fit-and-interface-witness-check"
            };
            interfaces.push(AssemblyInterface {
                interface_id: interface_id.clone(),
                from_part_id: base.id.clone(),
                to_part_id: part.id.clone(),
                joint_type: joint_type.to_string(),
                fit: fit.to_string(),
                strategy: format!(
                    "join {} made by {} to {} made by {}",
                    base.id, base.manufacturing_method, part.id, part.manufacturing_method
                ),
                inspection_gate: inspection_gate.to_string(),
                requires_human_intervention: true,
            });
            sequence.push(AssemblySequenceStep {
                step: index as u32,
                action: format!("join-and-verify-{interface_id}"),
                part_ids: vec![base.id.clone(), part.id.clone()],
                gate: inspection_gate.to_string(),
                notes: vec![
                    "verify datums, access path, and tolerance stack before adhesive, press, or fastener lock-in"
                        .to_string(),
                    "record the interface result as an outcome-learning observation".to_string(),
                ],
            });
        }
    }

    AssemblyGraph {
        nodes,
        interfaces,
        sequence,
    }
}

fn process_node_id(step: &ProcessStep) -> String {
    format!(
        "process-step-{}-{}",
        step.step,
        normalize_token(&step.part_id)
    )
}

fn process_graph(
    process_plan: &[ProcessStep],
    generated_programs: &[GeneratedProgram],
    assembly: &AssemblyPlan,
    validation: &ValidationReport,
    resolution_plan: &BoundaryResolutionPlan,
) -> ProcessGraph {
    let program_by_part = generated_programs
        .iter()
        .map(|program| (program.part_id.clone(), program.program_id.clone()))
        .collect::<BTreeMap<_, _>>();
    let node_by_part = process_plan
        .iter()
        .map(|step| (step.part_id.clone(), process_node_id(step)))
        .collect::<BTreeMap<_, _>>();
    let node_by_program = generated_programs
        .iter()
        .filter_map(|program| {
            node_by_part
                .get(&program.part_id)
                .map(|node_id| (program.program_id.clone(), node_id.clone()))
        })
        .collect::<BTreeMap<_, _>>();

    let nodes = process_plan
        .iter()
        .map(|step| ProcessGraphNode {
            node_id: process_node_id(step),
            step: step.step,
            part_id: step.part_id.clone(),
            machine_id: step.machine_id.clone(),
            machine_kind: step.machine_kind.clone(),
            operation: step.operation.clone(),
            program_id: program_by_part.get(&step.part_id).cloned(),
            expected_minutes: step.expected_minutes,
            requires_human_intervention: step.requires_human_intervention,
        })
        .collect::<Vec<_>>();

    let mut dependency_keys = BTreeSet::new();
    let mut dependencies = Vec::new();
    for window in process_plan.windows(2) {
        let from_node_id = process_node_id(&window[0]);
        let to_node_id = process_node_id(&window[1]);
        let key = format!("order|{from_node_id}|{to_node_id}");
        if dependency_keys.insert(key) {
            dependencies.push(ProcessGraphDependency {
                from_node_id,
                to_node_id,
                dependency_type: "process-order".to_string(),
                reason: "preserve generated process-plan sequence before release".to_string(),
            });
        }
    }
    for interface in &assembly.assembly_graph.interfaces {
        let Some(from_node_id) = node_by_part.get(&interface.from_part_id) else {
            continue;
        };
        let Some(to_node_id) = node_by_part.get(&interface.to_part_id) else {
            continue;
        };
        let key = format!("assembly|{from_node_id}|{to_node_id}");
        if dependency_keys.insert(key) {
            dependencies.push(ProcessGraphDependency {
                from_node_id: from_node_id.clone(),
                to_node_id: to_node_id.clone(),
                dependency_type: "assembly-interface".to_string(),
                reason: format!(
                    "join via {} with {} before final release",
                    interface.joint_type, interface.inspection_gate
                ),
            });
        }
    }

    let gates = resolution_plan
        .steps
        .iter()
        .map(|step| ProcessGraphGate {
            gate_id: format!(
                "process-gate-{}-{}",
                step.step,
                normalize_token(&step.boundary_kind)
            ),
            node_id: step
                .program_id
                .as_ref()
                .and_then(|program_id| node_by_program.get(program_id).cloned()),
            gate_type: step.phase.clone(),
            boundary_kind: step.boundary_kind.clone(),
            action: step.action.clone(),
            requires_human_intervention: step.requires_human_intervention,
            next_state: step.next_state.clone(),
        })
        .collect::<Vec<_>>();

    let release_state = if validation.severity == "error" {
        "blocked-until-resolved"
    } else if gates.is_empty() {
        "graph-review-ready"
    } else {
        "gated-before-machine-release"
    };

    ProcessGraph {
        release_state: release_state.to_string(),
        nodes,
        dependencies,
        gates,
    }
}

fn hybrid_candidate_part_ids(candidate: &str, parts: &[PartPlan]) -> Vec<String> {
    let candidate_lower = candidate.to_ascii_lowercase();
    let matching = parts
        .iter()
        .filter(|part| {
            candidate_lower.contains(&part.id.to_ascii_lowercase())
                || candidate_lower.contains(&normalize_token(&part.id))
        })
        .map(|part| part.id.clone())
        .collect::<Vec<_>>();
    if !matching.is_empty() {
        return matching;
    }
    parts
        .iter()
        .take(4)
        .map(|part| part.id.clone())
        .collect::<Vec<_>>()
}

fn boundary_is_split_combine_boundary(boundary: &FailureBoundary) -> bool {
    let combined = format!(
        "{} {} {}",
        boundary.kind, boundary.reason, boundary.suggested_resolution
    )
    .to_ascii_lowercase();
    summary_text_has_any(
        &combined,
        &[
            "assembly",
            "combine",
            "separate",
            "split",
            "multi-part",
            "join",
            "interface",
            "fit",
            "part-off",
            "support",
        ],
    )
}

fn hybrid_boundary_decision_type(boundary: &FailureBoundary) -> String {
    let combined = format!(
        "{} {} {}",
        boundary.kind, boundary.reason, boundary.suggested_resolution
    )
    .to_ascii_lowercase();
    if summary_text_has_any(&combined, &["combine", "merge", "single piece"]) {
        "validation-combine-boundary".to_string()
    } else if summary_text_has_any(&combined, &["split", "separate", "multi-part", "part-off"]) {
        "validation-split-boundary".to_string()
    } else {
        "validation-assembly-boundary".to_string()
    }
}

fn strategy_candidate_is_hybrid_decision(candidate: &StrategyCandidate) -> bool {
    let combined = format!(
        "{} {} {}",
        candidate.strategy_id,
        candidate.methods.join(" "),
        candidate.rationale.join(" ")
    )
    .to_ascii_lowercase();
    summary_text_has_any(
        &combined,
        &[
            "hybrid",
            "assembly",
            "combine",
            "consolidation",
            "split",
            "inspection",
            "multi-part",
        ],
    )
}

fn hybrid_make_plan(
    parts: &[PartPlan],
    process_plan: &[ProcessStep],
    generated_programs: &[GeneratedProgram],
    assembly: &AssemblyPlan,
    process_graph: &ProcessGraph,
    validation: &ValidationReport,
    learning: &LearningPlan,
) -> HybridMakePlan {
    let node_by_part = process_graph
        .nodes
        .iter()
        .map(|node| (node.part_id.clone(), node.clone()))
        .collect::<BTreeMap<_, _>>();
    let program_by_part = generated_programs
        .iter()
        .map(|program| (program.part_id.clone(), program.program_id.clone()))
        .collect::<BTreeMap<_, _>>();
    let split_candidate_text = assembly
        .split_candidates
        .iter()
        .map(|candidate| candidate.to_ascii_lowercase())
        .collect::<Vec<_>>();
    let interface_part_ids = assembly
        .assembly_graph
        .interfaces
        .iter()
        .flat_map(|interface| [interface.from_part_id.clone(), interface.to_part_id.clone()])
        .collect::<BTreeSet<_>>();

    let part_routes = parts
        .iter()
        .map(|part| {
            let node = node_by_part.get(&part.id);
            let route_type = if parts.len() == 1 {
                "single-piece-route"
            } else if interface_part_ids.contains(&part.id) {
                "hybrid-assembly-route"
            } else if split_candidate_text
                .iter()
                .any(|candidate| candidate.contains(&part.id.to_ascii_lowercase()))
            {
                "split-inspection-route"
            } else {
                "independent-part-route"
            };
            let operation = node
                .map(|node| node.operation.as_str())
                .or_else(|| {
                    process_plan
                        .iter()
                        .find(|step| step.part_id == part.id)
                        .map(|step| step.operation.as_str())
                })
                .unwrap_or("planned operation");
            HybridPartRoute {
                part_id: part.id.clone(),
                role: part.role.clone(),
                manufacturing_method: part.manufacturing_method.clone(),
                machine_kind: part.machine_kind.clone(),
                process_node_id: node.map(|node| node.node_id.clone()),
                program_id: program_by_part.get(&part.id).cloned(),
                route_type: route_type.to_string(),
                rationale: format!(
                    "route {} through {} on {} for {}; preserve as a separate learnable make unit until split/combine gates pass",
                    part.id, part.manufacturing_method, part.machine_kind, operation
                ),
            }
        })
        .collect::<Vec<_>>();

    let join_operations = assembly
        .assembly_graph
        .interfaces
        .iter()
        .map(|interface| {
            let sequence_step = assembly.assembly_graph.sequence.iter().find(|step| {
                step.part_ids.contains(&interface.from_part_id)
                    && step.part_ids.contains(&interface.to_part_id)
            });
            let learning_observation = format!(
                "hybrid-join:{}:{}:{}:{}",
                normalize_token(&interface.interface_id),
                normalize_token(&interface.joint_type),
                normalize_token(&interface.fit),
                normalize_token(&interface.inspection_gate)
            );
            HybridJoinOperation {
                join_id: format!("hybrid-join-{}", normalize_token(&interface.interface_id)),
                interface_id: interface.interface_id.clone(),
                from_part_id: interface.from_part_id.clone(),
                to_part_id: interface.to_part_id.clone(),
                joint_type: interface.joint_type.clone(),
                fit: interface.fit.clone(),
                inspection_gate: interface.inspection_gate.clone(),
                requires_human_intervention: interface.requires_human_intervention,
                sequence_step: sequence_step.map(|step| step.step),
                learning_observation,
            }
        })
        .collect::<Vec<_>>();

    let mut split_combine_decisions = Vec::new();
    for (index, candidate) in assembly.combine_candidates.iter().enumerate() {
        let part_ids = hybrid_candidate_part_ids(candidate, parts);
        let learning_observation = format!(
            "hybrid-decision:combine:{}:{}",
            index + 1,
            normalize_token(candidate)
        );
        split_combine_decisions.push(HybridSplitCombineDecision {
            decision_id: format!("hybrid-combine-candidate-{}", index + 1),
            decision_type: "combine-candidate".to_string(),
            part_ids,
            reason: candidate.clone(),
            action: "review-combine-before-cad-cam-freeze".to_string(),
            source: "assembly-plan".to_string(),
            learning_observation,
            requires_human_review: true,
        });
    }
    for (index, candidate) in assembly.split_candidates.iter().enumerate() {
        let part_ids = hybrid_candidate_part_ids(candidate, parts);
        let learning_observation = format!(
            "hybrid-decision:split:{}:{}",
            index + 1,
            normalize_token(candidate)
        );
        split_combine_decisions.push(HybridSplitCombineDecision {
            decision_id: format!("hybrid-split-candidate-{}", index + 1),
            decision_type: "split-candidate".to_string(),
            part_ids,
            reason: candidate.clone(),
            action: "preserve-separate-piece-before-cad-cam-freeze".to_string(),
            source: "assembly-plan".to_string(),
            learning_observation,
            requires_human_review: true,
        });
    }
    for (index, boundary) in validation
        .failure_boundaries
        .iter()
        .filter(|boundary| boundary_is_split_combine_boundary(boundary))
        .enumerate()
    {
        let decision_type = hybrid_boundary_decision_type(boundary);
        let line_suffix = boundary
            .line
            .map(|line| format!("-line-{line}"))
            .unwrap_or_default();
        let reason = format!("{} boundary: {}", boundary.kind, boundary.reason.trim());
        let learning_observation = format!(
            "hybrid-boundary:{}:{}:{}",
            normalize_token(&decision_type),
            normalize_token(&boundary.kind),
            normalize_token(&boundary.suggested_resolution)
        );
        split_combine_decisions.push(HybridSplitCombineDecision {
            decision_id: format!(
                "hybrid-boundary-{}-{}{}",
                index + 1,
                normalize_token(&boundary.kind),
                line_suffix
            ),
            decision_type,
            part_ids: hybrid_candidate_part_ids(&reason, parts),
            reason,
            action: boundary.suggested_resolution.clone(),
            source: "validation-boundary".to_string(),
            learning_observation,
            requires_human_review: boundary.requires_human_intervention
                || boundary.severity == "error",
        });
    }
    for candidate in learning
        .strategy_candidates
        .iter()
        .filter(|candidate| strategy_candidate_is_hybrid_decision(candidate))
        .take(4)
    {
        let learning_observation = format!(
            "hybrid-strategy-candidate:{}:score-{:.3}",
            normalize_token(&candidate.strategy_id),
            candidate.score
        );
        split_combine_decisions.push(HybridSplitCombineDecision {
            decision_id: format!(
                "hybrid-strategy-candidate-{}",
                normalize_token(&candidate.strategy_id)
            ),
            decision_type: "learning-strategy-candidate".to_string(),
            part_ids: parts.iter().take(4).map(|part| part.id.clone()).collect(),
            reason: candidate.rationale.join("; "),
            action: format!(
                "consider learned strategy {} before CAD/CAM freeze",
                candidate.strategy_id
            ),
            source: "learning-plan".to_string(),
            learning_observation,
            requires_human_review: candidate.human_intervention_steps > 0
                || candidate.boundary_count > 0,
        });
    }

    let mut learning_observations = part_routes
        .iter()
        .map(|route| {
            format!(
                "hybrid-route:{}:{}:{}",
                normalize_token(&route.part_id),
                normalize_token(&route.manufacturing_method),
                normalize_token(&route.route_type)
            )
        })
        .collect::<Vec<_>>();
    learning_observations.extend(
        join_operations
            .iter()
            .map(|operation| operation.learning_observation.clone()),
    );
    learning_observations.extend(
        split_combine_decisions
            .iter()
            .map(|decision| decision.learning_observation.clone()),
    );

    let split_count = split_combine_decisions
        .iter()
        .filter(|decision| decision.decision_type.contains("split"))
        .count();
    let combine_count = split_combine_decisions
        .iter()
        .filter(|decision| decision.decision_type.contains("combine"))
        .count();
    let review_required = join_operations
        .iter()
        .any(|operation| operation.requires_human_intervention)
        || split_combine_decisions
            .iter()
            .any(|decision| decision.requires_human_review)
        || !process_graph.gates.is_empty();
    let status = if validation.severity == "error" {
        "hybrid-make-blocked"
    } else if parts.len() <= 1 {
        "single-route-draft"
    } else if review_required {
        "hybrid-make-review-required"
    } else {
        "hybrid-make-draft-ready"
    };

    HybridMakePlan {
        schema_version: "dd.fabrication.hybrid-make-plan.v1",
        status: status.to_string(),
        selected_strategy: assembly.strategy.clone(),
        route_count: part_routes.len(),
        join_count: join_operations.len(),
        split_count,
        combine_count,
        part_routes,
        join_operations,
        split_combine_decisions,
        learning_observations,
        notes: vec![
            "Hybrid make routes are draft decomposition decisions for CAD, CAM, slicer, and assembly workers".to_string(),
            "Split/combine decisions stay review-gated until tolerance stack, fixture access, and join inspection evidence are attached".to_string(),
            "Learning observations are compact signals for MDP/POMDP/neural workers to compare future make-or-split outcomes".to_string(),
        ],
    }
}

fn decomposition_route_contract_id(part_id: &str) -> String {
    format!("decomposition-route-{}", normalize_token(part_id))
}

fn decomposition_machine_evidence(machine_kind: &str) -> Vec<String> {
    match machine_class(machine_kind) {
        MachineClass::Additive => vec![
            "slicer profile, orientation, support, and material lot for the separated printable body"
                .to_string(),
            "part ID, build plate position, and postprocess traceability before recomposition"
                .to_string(),
        ],
        MachineClass::Mill | MachineClass::Router => vec![
            "stock, fixture, work offset, tool list, and datum transfer evidence for the split route"
                .to_string(),
            "CAM regeneration and dry-run evidence after the decomposition boundary is accepted"
                .to_string(),
        ],
        MachineClass::Lathe => vec![
            "stock support, chuck/subspindle or tailstock plan, datum pickup, and part-off evidence"
                .to_string(),
            "turned insert or cylindrical interface metrology before assembly lock-in".to_string(),
        ],
        MachineClass::SheetCut => vec![
            "sheet nesting, kerf compensation, tab/slug retention, and deburr traceability"
                .to_string(),
            "flatness and edge-condition inspection before recomposition".to_string(),
        ],
        MachineClass::Other if is_assembly_cell_kind(machine_kind) => vec![
            "kit trace, gripper, robot path, fixture simulation, and interlock evidence".to_string(),
            "join recipe, torque/press/cure result, and final assembly metrology".to_string(),
        ],
        MachineClass::Other => vec![
            "special-process traveler, operator qualification, and first-article evidence".to_string(),
            "route-specific release signoff before recomposition".to_string(),
        ],
    }
}

fn decomposition_target_kind_from_action(action: &str) -> &'static str {
    let normalized = action.to_ascii_lowercase();
    if normalized.contains("split") || normalized.contains("separate") {
        "split-boundary-decomposition"
    } else if normalized.contains("combine")
        || normalized.contains("join")
        || normalized.contains("assembl")
    {
        "combine-boundary-recomposition"
    } else {
        "hybrid-route-decomposition-review"
    }
}

fn decomposition_target_kind_from_hybrid(decision: &HybridSplitCombineDecision) -> &'static str {
    let normalized = format!("{} {}", decision.decision_type, decision.action).to_ascii_lowercase();
    if normalized.contains("split") || normalized.contains("separate") {
        "split-candidate-decomposition"
    } else if normalized.contains("combine")
        || normalized.contains("join")
        || normalized.contains("assembl")
    {
        "combine-candidate-recomposition"
    } else {
        "learned-hybrid-decomposition-review"
    }
}

fn decomposition_target_required_evidence(
    target_kind: &str,
    boundary_kind: Option<&str>,
    route_machine_kinds: &[String],
    interface_ids: &[String],
) -> Vec<String> {
    let mut evidence = vec![
        "source geometry/body partition with units, revision, and tolerance stack evidence"
            .to_string(),
        "explicit datum or witness feature that survives split, machine work, and recomposition"
            .to_string(),
    ];
    if target_kind.contains("split") {
        evidence.push(
            "child-part CAD/mesh/CAM regeneration plus proof each child route fits the selected machine envelope"
                .to_string(),
        );
        evidence.push(
            "recombination interface, fastener/bond/press-fit strategy, and dry-fit inspection gate"
                .to_string(),
        );
    } else if target_kind.contains("combine") || target_kind.contains("recomposition") {
        evidence.push(
            "dry-fit metrology, mating-surface condition, join recipe, clamp/torque/cure plan, and final inspection"
                .to_string(),
        );
    } else {
        evidence.push(
            "route comparison showing why this body should remain one piece or become multiple pieces"
                .to_string(),
        );
    }
    if let Some(boundary_kind) = boundary_kind {
        evidence.push(format!(
            "boundary-specific clearance, automation, or operator evidence for {boundary_kind}"
        ));
    }
    for machine_kind in route_machine_kinds {
        evidence.extend(decomposition_machine_evidence(machine_kind));
    }
    for interface_id in interface_ids {
        evidence.push(format!(
            "interface {interface_id} fit, datum transfer, and release-check evidence"
        ));
    }
    evidence.sort();
    evidence.dedup();
    evidence
}

fn decomposition_boundary_kind_from_hybrid(
    decision: &HybridSplitCombineDecision,
) -> Option<String> {
    if decision.source != "validation-boundary" {
        return None;
    }
    decision
        .reason
        .split_once(" boundary:")
        .map(|(kind, _)| kind.to_string())
}

fn decomposition_interfaces_for_parts(
    part_ids: &[String],
    interfaces: &BTreeMap<String, DecompositionInterface>,
) -> Vec<String> {
    let part_set = part_ids.iter().collect::<BTreeSet<_>>();
    interfaces
        .values()
        .filter(|interface| {
            part_set.contains(&interface.from_part_id) || part_set.contains(&interface.to_part_id)
        })
        .map(|interface| interface.interface_id.clone())
        .collect()
}

fn decomposition_release_blockers_for_program(
    program_id: Option<&String>,
    machine_release: &MachineReleaseReport,
) -> Vec<String> {
    machine_release
        .blockers
        .iter()
        .filter(|blocker| blocker.program_id.as_ref() == program_id || blocker.program_id.is_none())
        .map(|blocker| {
            format!(
                "{}:{} -> {}",
                blocker.blocker_type, blocker.reason, blocker.required_action
            )
        })
        .collect()
}

fn decomposition_release_blockers_for_parts(
    part_ids: &[String],
    route_by_part: &BTreeMap<String, &HybridPartRoute>,
    machine_release: &MachineReleaseReport,
) -> Vec<String> {
    let mut blockers = part_ids
        .iter()
        .flat_map(|part_id| {
            let program_id = route_by_part
                .get(part_id)
                .and_then(|route| route.program_id.as_ref());
            decomposition_release_blockers_for_program(program_id, machine_release)
        })
        .collect::<Vec<_>>();
    blockers.sort();
    blockers.dedup();
    blockers
}

fn decomposition_plan(
    parts: &[PartPlan],
    process_graph: &ProcessGraph,
    hybrid_make_plan: &HybridMakePlan,
    intervention_map: &BoundaryInterventionMap,
    machine_release: &MachineReleaseReport,
) -> DecompositionPlan {
    let route_by_part = hybrid_make_plan
        .part_routes
        .iter()
        .map(|route| (route.part_id.clone(), route))
        .collect::<BTreeMap<_, _>>();
    let mut interfaces = BTreeMap::<String, DecompositionInterface>::new();
    for decision in &intervention_map.split_combine_decisions {
        let interface = &decision.interface_plan;
        interfaces
            .entry(interface.interface_id.clone())
            .or_insert_with(|| DecompositionInterface {
                interface_id: interface.interface_id.clone(),
                from_part_id: interface.from_part_id.clone(),
                to_part_id: interface.to_part_id.clone(),
                joint_type: interface.joint_type.clone(),
                fit: interface.fit.clone(),
                inspection_gate: interface.inspection_gate.clone(),
                source: "intervention-map".to_string(),
                requires_human_intervention: decision.requires_human_intervention,
                learning_observation: format!(
                    "decomposition-interface:{}:{}:{}",
                    normalize_token(&interface.interface_id),
                    normalize_token(&interface.fit),
                    normalize_token(&interface.inspection_gate)
                ),
            });
    }
    for join in &hybrid_make_plan.join_operations {
        interfaces
            .entry(join.interface_id.clone())
            .or_insert_with(|| DecompositionInterface {
                interface_id: join.interface_id.clone(),
                from_part_id: join.from_part_id.clone(),
                to_part_id: join.to_part_id.clone(),
                joint_type: join.joint_type.clone(),
                fit: join.fit.clone(),
                inspection_gate: join.inspection_gate.clone(),
                source: "hybrid-make-plan".to_string(),
                requires_human_intervention: join.requires_human_intervention,
                learning_observation: format!(
                    "decomposition-interface:{}:{}:{}",
                    normalize_token(&join.interface_id),
                    normalize_token(&join.fit),
                    normalize_token(&join.inspection_gate)
                ),
            });
    }

    let mut targets = Vec::new();
    let mut release_gates = Vec::new();
    for decision in &intervention_map.split_combine_decisions {
        let target_kind = decomposition_target_kind_from_action(&decision.action);
        let replacement_part_ids = if decision.candidate_parts.is_empty() {
            decision.part_id.iter().cloned().collect::<Vec<_>>()
        } else {
            decision.candidate_parts.clone()
        };
        let route_contract_ids = replacement_part_ids
            .iter()
            .map(|part_id| decomposition_route_contract_id(part_id))
            .collect::<Vec<_>>();
        let interface_ids = vec![decision.interface_plan.interface_id.clone()];
        let route_machine_kinds = replacement_part_ids
            .iter()
            .filter_map(|part_id| {
                route_by_part
                    .get(part_id)
                    .map(|route| route.machine_kind.clone())
            })
            .collect::<Vec<_>>();
        let release_blockers = decomposition_release_blockers_for_program(
            decision.program_id.as_ref(),
            machine_release,
        );
        let required_evidence = decomposition_target_required_evidence(
            target_kind,
            Some(decision.boundary_kind.as_str()),
            &route_machine_kinds,
            &interface_ids,
        );
        let target_id = format!(
            "decomposition-target-{}",
            normalize_token(&decision.decision_id)
        );
        let learning_observation = format!(
            "decomposition-target:{}:{}:{}",
            normalize_token(target_kind),
            normalize_token(&decision.boundary_kind),
            normalize_token(&decision.action)
        );
        let requires_human_review =
            decision.requires_human_intervention || !release_blockers.is_empty();
        release_gates.push(DecompositionReleaseGate {
            gate_id: format!("decomposition-gate-{}", normalize_token(&target_id)),
            gate_type: target_kind.to_string(),
            source: "intervention-map".to_string(),
            boundary_kind: Some(decision.boundary_kind.clone()),
            interface_id: interface_ids.first().cloned(),
            required_before: "cad-cam-freeze".to_string(),
            required_evidence: required_evidence.clone(),
            release_blocker: requires_human_review,
            next_state: "assembly-required".to_string(),
        });
        targets.push(DecompositionTarget {
            target_id,
            target_kind: target_kind.to_string(),
            source: "intervention-map".to_string(),
            source_part_id: decision.part_id.clone(),
            boundary_kind: Some(decision.boundary_kind.clone()),
            program_id: decision.program_id.clone(),
            line: decision.line,
            recommended_action: decision.action.clone(),
            reason: decision.rationale.clone(),
            replacement_part_ids,
            route_contract_ids,
            interface_ids,
            required_evidence,
            release_blockers,
            requires_human_review,
            learning_observation,
        });
    }

    let mut target_ids = targets
        .iter()
        .map(|target| target.target_id.clone())
        .collect::<BTreeSet<_>>();
    for decision in &hybrid_make_plan.split_combine_decisions {
        let target_id = format!(
            "decomposition-target-{}",
            normalize_token(&decision.decision_id)
        );
        if !target_ids.insert(target_id.clone()) {
            continue;
        }
        let target_kind = decomposition_target_kind_from_hybrid(decision);
        let replacement_part_ids = decision.part_ids.clone();
        let route_contract_ids = replacement_part_ids
            .iter()
            .map(|part_id| decomposition_route_contract_id(part_id))
            .collect::<Vec<_>>();
        let interface_ids = decomposition_interfaces_for_parts(&replacement_part_ids, &interfaces);
        let route_machine_kinds = replacement_part_ids
            .iter()
            .filter_map(|part_id| {
                route_by_part
                    .get(part_id)
                    .map(|route| route.machine_kind.clone())
            })
            .collect::<Vec<_>>();
        let boundary_kind = decomposition_boundary_kind_from_hybrid(decision);
        let mut release_blockers = decomposition_release_blockers_for_parts(
            &replacement_part_ids,
            &route_by_part,
            machine_release,
        );
        if decision.requires_human_review && release_blockers.is_empty() {
            release_blockers
                .push("split/combine decision still requires human review evidence".to_string());
        }
        let required_evidence = decomposition_target_required_evidence(
            target_kind,
            boundary_kind.as_deref(),
            &route_machine_kinds,
            &interface_ids,
        );
        let requires_human_review = decision.requires_human_review || !release_blockers.is_empty();
        release_gates.push(DecompositionReleaseGate {
            gate_id: format!("decomposition-gate-{}", normalize_token(&target_id)),
            gate_type: target_kind.to_string(),
            source: decision.source.clone(),
            boundary_kind: boundary_kind.clone(),
            interface_id: interface_ids.first().cloned(),
            required_before: "cad-cam-freeze".to_string(),
            required_evidence: required_evidence.clone(),
            release_blocker: requires_human_review,
            next_state: if target_kind.contains("split") || target_kind.contains("combine") {
                "assembly-required".to_string()
            } else {
                "inspection-required".to_string()
            },
        });
        targets.push(DecompositionTarget {
            target_id,
            target_kind: target_kind.to_string(),
            source: decision.source.clone(),
            source_part_id: replacement_part_ids.first().cloned(),
            boundary_kind,
            program_id: None,
            line: None,
            recommended_action: decision.action.clone(),
            reason: decision.reason.clone(),
            replacement_part_ids,
            route_contract_ids,
            interface_ids,
            required_evidence,
            release_blockers,
            requires_human_review,
            learning_observation: format!(
                "decomposition-target:{}:{}:{}",
                normalize_token(target_kind),
                normalize_token(&decision.source),
                normalize_token(&decision.decision_type)
            ),
        });
    }

    let interface_values = interfaces.values().cloned().collect::<Vec<_>>();
    for interface in &interface_values {
        release_gates.push(DecompositionReleaseGate {
            gate_id: format!(
                "decomposition-interface-gate-{}",
                normalize_token(&interface.interface_id)
            ),
            gate_type: "recomposition-interface-fit-check".to_string(),
            source: interface.source.clone(),
            boundary_kind: None,
            interface_id: Some(interface.interface_id.clone()),
            required_before: "assembly-lock-in".to_string(),
            required_evidence: vec![
                format!("{} inspection gate result", interface.inspection_gate),
                format!("{} fit evidence between {} and {}", interface.fit, interface.from_part_id, interface.to_part_id),
                "operator or automation cell signoff before adhesive, press, torque, or cure lock-in"
                    .to_string(),
            ],
            release_blocker: interface.requires_human_intervention,
            next_state: "assembly-required".to_string(),
        });
    }

    let route_contracts = hybrid_make_plan
        .part_routes
        .iter()
        .map(|route| {
            let must_remain_separate_until = targets
                .iter()
                .filter(|target| target.replacement_part_ids.contains(&route.part_id))
                .map(|target| target.target_id.clone())
                .chain(
                    process_graph
                        .gates
                        .iter()
                        .filter(|gate| gate.requires_human_intervention)
                        .filter_map(|gate| {
                            route.process_node_id.as_ref().and_then(|node_id| {
                                if gate.node_id.as_ref() == Some(node_id) {
                                    Some(gate.gate_id.clone())
                                } else {
                                    None
                                }
                            })
                        }),
                )
                .collect::<BTreeSet<_>>()
                .into_iter()
                .collect::<Vec<_>>();
            let recomposition_after = interface_values
                .iter()
                .filter(|interface| {
                    interface.from_part_id == route.part_id || interface.to_part_id == route.part_id
                })
                .map(|interface| interface.interface_id.clone())
                .collect::<Vec<_>>();
            let mut required_evidence = vec![
                "part ID traceability from design source through machine program and inspection result"
                    .to_string(),
                "route output checksum or controller/program revision captured before recomposition"
                    .to_string(),
            ];
            required_evidence.extend(decomposition_machine_evidence(&route.machine_kind));
            required_evidence.sort();
            required_evidence.dedup();
            DecompositionRouteContract {
                contract_id: decomposition_route_contract_id(&route.part_id),
                part_id: route.part_id.clone(),
                route_type: route.route_type.clone(),
                manufacturing_method: route.manufacturing_method.clone(),
                machine_kind: route.machine_kind.clone(),
                process_node_id: route.process_node_id.clone(),
                program_id: route.program_id.clone(),
                must_remain_separate_until,
                recomposition_after,
                required_evidence,
                learning_observation: format!(
                    "decomposition-route:{}:{}:{}",
                    normalize_token(&route.part_id),
                    normalize_token(&route.route_type),
                    normalize_token(&route.machine_kind)
                ),
            }
        })
        .collect::<Vec<_>>();

    let release_blocked = machine_release.machine_release_blocked
        || targets
            .iter()
            .any(|target| !target.release_blockers.is_empty())
        || release_gates.iter().any(|gate| gate.release_blocker);
    let human_review_required = release_blocked
        || targets.iter().any(|target| target.requires_human_review)
        || interface_values
            .iter()
            .any(|interface| interface.requires_human_intervention);
    let status = if release_blocked {
        "decomposition-release-blocked"
    } else if targets.is_empty() && interface_values.is_empty() {
        "single-body-decomposition-not-required"
    } else if human_review_required {
        "decomposition-review-required"
    } else {
        "decomposition-plan-ready"
    };

    let mut learning_observations = BTreeSet::new();
    for target in &targets {
        learning_observations.insert(target.learning_observation.clone());
    }
    for contract in &route_contracts {
        learning_observations.insert(contract.learning_observation.clone());
    }
    for interface in &interface_values {
        learning_observations.insert(interface.learning_observation.clone());
    }
    for gate in &release_gates {
        learning_observations.insert(format!(
            "decomposition-release-gate:{}:{}",
            normalize_token(&gate.gate_type),
            if gate.release_blocker {
                "blocked"
            } else {
                "ready"
            }
        ));
    }
    if learning_observations.is_empty() {
        learning_observations.insert("decomposition:no-split-combine-needed".to_string());
    }

    DecompositionPlan {
        schema_version: "dd.fabrication.decomposition-plan.v1",
        status: status.to_string(),
        release_blocked,
        human_review_required,
        part_count: parts.len(),
        decomposition_target_count: targets.len(),
        recomposition_interface_count: interface_values.len(),
        route_contract_count: route_contracts.len(),
        targets,
        route_contracts,
        recomposition_interfaces: interface_values,
        release_gates,
        learning_observations: learning_observations.into_iter().collect(),
        notes: vec![
            "Decomposition plan is the explicit split, route, recomposition, and release-evidence contract for CAD/CAM, slicer, robot, operator, and learning workers".to_string(),
            "Targets stay blocked until child geometry, per-route machine code, interface metrology, and recomposition evidence prove the job can complete without hidden human intervention".to_string(),
            "Learning observations let MDP/POMDP/neural workers compare single-piece, split-route, and recomposed outcomes across future fabrication jobs".to_string(),
        ],
    }
}

fn decomposition_plan_learning_actions(plan: &DecompositionPlan) -> Vec<String> {
    let mut actions = Vec::new();
    for target in &plan.targets {
        let target_token = normalize_token(&target.target_id);
        if target.target_kind.contains("split") {
            actions.push(
                if target.requires_human_review || !target.release_blockers.is_empty() {
                    format!("resolve-split-decomposition-{target_token}")
                } else {
                    format!("verify-split-decomposition-{target_token}")
                },
            );
        } else if target.target_kind.contains("combine")
            || target.target_kind.contains("recomposition")
        {
            actions.push(
                if target.requires_human_review || !target.release_blockers.is_empty() {
                    format!("resolve-combine-recomposition-{target_token}")
                } else {
                    format!("verify-combine-recomposition-{target_token}")
                },
            );
        } else {
            actions.push(format!("verify-decomposition-target-{target_token}"));
        }
    }
    actions.extend(plan.recomposition_interfaces.iter().map(|interface| {
        format!(
            "verify-recomposition-interface-{}",
            normalize_token(&interface.interface_id)
        )
    }));
    actions.extend(plan.release_gates.iter().map(|gate| {
        if gate.release_blocker {
            format!(
                "clear-decomposition-gate-{}",
                normalize_token(&gate.gate_id)
            )
        } else {
            format!(
                "verify-decomposition-gate-{}",
                normalize_token(&gate.gate_id)
            )
        }
    }));
    actions.sort();
    actions.dedup();
    actions
}

fn release_package_design_export_ids(
    part_id: Option<&str>,
    program_id: Option<&str>,
    design_exports: &DesignExportBundle,
) -> Vec<String> {
    let mut ids = BTreeSet::new();
    for export in &design_exports.part_exports {
        if part_id.is_some_and(|part| export.part_id == part)
            || program_id.is_some_and(|program| export.program_id.as_deref() == Some(program))
        {
            ids.insert(export.export_id.clone());
        }
    }
    ids.into_iter().collect()
}

fn release_package_fixture_setup_ids(
    part_id: Option<&str>,
    program_id: Option<&str>,
    fixture_plan: &FixturePlan,
) -> Vec<String> {
    let mut ids = BTreeSet::new();
    for setup in &fixture_plan.setups {
        if part_id.is_some_and(|part| setup.part_id == part)
            || program_id.is_some_and(|program| setup.program_id.as_deref() == Some(program))
        {
            ids.insert(setup.setup_id.clone());
        }
    }
    ids.into_iter().collect()
}

fn release_package_monitoring_point_ids(
    part_id: Option<&str>,
    program_id: Option<&str>,
    monitoring_plan: &MonitoringPlan,
) -> Vec<String> {
    let mut ids = BTreeSet::new();
    for point in &monitoring_plan.monitor_points {
        if part_id.is_some_and(|part| point.part_id == part)
            || program_id.is_some_and(|program| point.program_id.as_deref() == Some(program))
        {
            ids.insert(point.monitor_id.clone());
        }
    }
    ids.into_iter().collect()
}

fn release_package_quality_inspection_ids(
    part_id: Option<&str>,
    program_id: Option<&str>,
    quality_plan: &QualityPlan,
) -> Vec<String> {
    let mut ids = BTreeSet::new();
    for point in &quality_plan.inspection_points {
        if part_id.is_some_and(|part| point.part_id == part)
            || program_id.is_some_and(|program| point.program_id.as_deref() == Some(program))
        {
            ids.insert(point.inspection_id.clone());
        }
    }
    ids.into_iter().collect()
}

fn release_package_decomposition_target_ids(
    part_id: Option<&str>,
    program_id: Option<&str>,
    decomposition_plan: &DecompositionPlan,
) -> Vec<String> {
    let mut ids = BTreeSet::new();
    for target in &decomposition_plan.targets {
        if part_id.is_some_and(|part| {
            target.source_part_id.as_deref() == Some(part)
                || target
                    .replacement_part_ids
                    .iter()
                    .any(|replacement| replacement == part)
        }) || program_id.is_some_and(|program| target.program_id.as_deref() == Some(program))
        {
            ids.insert(target.target_id.clone());
        }
    }
    ids.into_iter().collect()
}

fn release_package_interface_control_ids(
    part_id: Option<&str>,
    interface_control_plan: &InterfaceControlPlan,
) -> Vec<String> {
    let mut ids = BTreeSet::new();
    for control in &interface_control_plan.controls {
        if part_id.is_some_and(|part| control.from_part_id == part || control.to_part_id == part) {
            ids.insert(control.control_id.clone());
        }
    }
    ids.into_iter().collect()
}

fn release_package_controller_target_ids(
    program_id: Option<&str>,
    controller_plan: &ControllerPlan,
) -> Vec<String> {
    let mut ids = BTreeSet::new();
    for target in &controller_plan.compatibility_targets {
        if program_id.is_some_and(|program| target.program_id == program) {
            ids.insert(target.target_id.clone());
        }
    }
    ids.into_iter().collect()
}

fn release_package_process_node_id(
    program_id: Option<&str>,
    part_id: Option<&str>,
    process_graph: &ProcessGraph,
) -> Option<String> {
    process_graph
        .nodes
        .iter()
        .find(|node| {
            program_id.is_some_and(|program| node.program_id.as_deref() == Some(program))
                || part_id.is_some_and(|part| node.part_id == part)
        })
        .map(|node| node.node_id.clone())
}

fn release_package_required_artifacts(
    program_id: Option<&str>,
    instruction_program_ids: &[String],
    design_export_ids: &[String],
    fixture_setup_ids: &[String],
    monitoring_point_ids: &[String],
    quality_inspection_ids: &[String],
    decomposition_target_ids: &[String],
    interface_control_ids: &[String],
    controller_target_ids: &[String],
) -> Vec<String> {
    let mut artifacts = BTreeSet::new();
    artifacts.insert("machine-release".to_string());
    artifacts.insert("manufacturing-handoff".to_string());
    artifacts.insert("design-package".to_string());
    artifacts.insert("design-export-bundle".to_string());
    if let Some(program_id) = program_id {
        artifacts.insert(artifact_id("program", program_id));
    }
    if !instruction_program_ids.is_empty() {
        artifacts.insert("instruction-programs".to_string());
    }
    if !design_export_ids.is_empty() {
        artifacts.extend(design_export_ids.iter().cloned());
    }
    if !fixture_setup_ids.is_empty() {
        artifacts.insert("fixture-plan".to_string());
    }
    if !monitoring_point_ids.is_empty() {
        artifacts.insert("monitoring-plan".to_string());
    }
    if !quality_inspection_ids.is_empty() {
        artifacts.insert("quality-plan".to_string());
    }
    if !decomposition_target_ids.is_empty() {
        artifacts.insert("decomposition-plan".to_string());
    }
    if !interface_control_ids.is_empty() {
        artifacts.insert("interface-control-plan".to_string());
    }
    if !controller_target_ids.is_empty() {
        artifacts.insert("controller-plan".to_string());
        artifacts.insert("postprocess-plan".to_string());
    }
    artifacts.into_iter().collect()
}

fn release_package_instruction_program_ids(
    program_id: &str,
    analyzed_programs: &[AnalyzedProgram],
) -> Vec<String> {
    analyzed_programs
        .iter()
        .filter(|program| program.program_id == program_id)
        .map(|program| program.program_id.clone())
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect()
}

fn release_package_blockers(
    part_id: Option<&str>,
    program_id: Option<&str>,
    design_exports: &DesignExportBundle,
    fixture_plan: &FixturePlan,
    monitoring_plan: &MonitoringPlan,
    decomposition_plan: &DecompositionPlan,
    interface_control_plan: &InterfaceControlPlan,
    controller_plan: &ControllerPlan,
    machine_release: &MachineReleaseReport,
) -> Vec<String> {
    let mut blockers = BTreeSet::new();
    for blocker in &machine_release.blockers {
        if program_id.is_some_and(|program| blocker.program_id.as_deref() == Some(program)) {
            blockers.insert(format!(
                "machine-release:{}:{}",
                blocker.blocker_type, blocker.reason
            ));
        }
    }
    for export in &design_exports.part_exports {
        if part_id.is_some_and(|part| export.part_id == part)
            || program_id.is_some_and(|program| export.program_id.as_deref() == Some(program))
        {
            blockers.extend(
                export
                    .blockers
                    .iter()
                    .map(|blocker| format!("design-export:{}:{blocker}", export.export_id)),
            );
        }
    }
    for setup in &fixture_plan.setups {
        if part_id.is_some_and(|part| setup.part_id == part)
            || program_id.is_some_and(|program| setup.program_id.as_deref() == Some(program))
        {
            blockers.extend(
                setup
                    .release_blockers
                    .iter()
                    .map(|blocker| format!("fixture:{}:{blocker}", setup.setup_id)),
            );
        }
    }
    for point in &monitoring_plan.monitor_points {
        if part_id.is_some_and(|part| point.part_id == part)
            || program_id.is_some_and(|program| point.program_id.as_deref() == Some(program))
        {
            blockers.extend(
                point
                    .release_blockers
                    .iter()
                    .map(|blocker| format!("monitoring:{}:{blocker}", point.monitor_id)),
            );
        }
    }
    for target in &decomposition_plan.targets {
        if part_id.is_some_and(|part| {
            target.source_part_id.as_deref() == Some(part)
                || target
                    .replacement_part_ids
                    .iter()
                    .any(|replacement| replacement == part)
        }) || program_id.is_some_and(|program| target.program_id.as_deref() == Some(program))
        {
            blockers.extend(
                target
                    .release_blockers
                    .iter()
                    .map(|blocker| format!("decomposition:{}:{blocker}", target.target_id)),
            );
        }
    }
    for control in &interface_control_plan.controls {
        if part_id.is_some_and(|part| control.from_part_id == part || control.to_part_id == part) {
            blockers.extend(
                control
                    .release_blockers
                    .iter()
                    .map(|blocker| format!("interface:{}:{blocker}", control.control_id)),
            );
        }
    }
    for target in &controller_plan.compatibility_targets {
        if program_id.is_some_and(|program| target.program_id == program) {
            blockers.extend(
                target
                    .release_blockers
                    .iter()
                    .map(|blocker| format!("controller:{}:{blocker}", target.target_id)),
            );
        }
    }
    if blockers.is_empty() && machine_release.machine_release_blocked {
        blockers.insert(format!(
            "machine-release-blocked:{}",
            machine_release.status
        ));
    }
    blockers.into_iter().collect()
}

fn release_package_state(release_blockers: &[String], machine_ready: bool) -> String {
    if !release_blockers.is_empty() {
        "release-blocked".to_string()
    } else if machine_ready {
        "machine-ready".to_string()
    } else {
        "release-review-ready".to_string()
    }
}

fn release_package_gates_for_package(package: &ReleasePackage) -> Vec<ReleasePackageGate> {
    let package_token = normalize_token(&package.package_id);
    let blocked = !package.release_blockers.is_empty();
    let review_status = if blocked { "blocked" } else { "pending-review" };
    let mut gates = vec![
        ReleasePackageGate {
            gate_id: format!("release-package-gate-{package_token}-design"),
            package_id: Some(package.package_id.clone()),
            gate_type: "design-export-review".to_string(),
            status: review_status.to_string(),
            required_before: "machine-code-or-operator-traveler-release".to_string(),
            evidence: if package.design_export_ids.is_empty() {
                "design package and parametric-design artifact retained for review".to_string()
            } else {
                format!(
                    "review generated design exports: {}",
                    package.design_export_ids.join(", ")
                )
            },
            release_blocker: blocked,
        },
        ReleasePackageGate {
            gate_id: format!("release-package-gate-{package_token}-setup-quality-monitoring"),
            package_id: Some(package.package_id.clone()),
            gate_type: "setup-quality-monitoring-evidence".to_string(),
            status: review_status.to_string(),
            required_before: "unattended-or-machine-ready-run".to_string(),
            evidence: format!(
                "fixture setups={}, quality inspections={}, monitoring points={}",
                package.fixture_setup_ids.len(),
                package.quality_inspection_ids.len(),
                package.monitoring_point_ids.len()
            ),
            release_blocker: blocked,
        },
        ReleasePackageGate {
            gate_id: format!("release-package-gate-{package_token}-machine-release"),
            package_id: Some(package.package_id.clone()),
            gate_type: "machine-release-signoff".to_string(),
            status: package.release_state.clone(),
            required_before: "machine-ready-release".to_string(),
            evidence: if package.release_blockers.is_empty() {
                "no package-specific blockers retained; operator/controller signoff still required for draft artifacts"
                    .to_string()
            } else {
                package.release_blockers.join(" | ")
            },
            release_blocker: blocked,
        },
    ];
    if !package.controller_target_ids.is_empty() {
        gates.push(ReleasePackageGate {
            gate_id: format!("release-package-gate-{package_token}-controller"),
            package_id: Some(package.package_id.clone()),
            gate_type: "controller-postprocess-compatibility".to_string(),
            status: review_status.to_string(),
            required_before: "controller-load-or-dry-run".to_string(),
            evidence: format!(
                "controller compatibility targets: {}",
                package.controller_target_ids.join(", ")
            ),
            release_blocker: blocked,
        });
    }
    if !package.decomposition_target_ids.is_empty() || !package.interface_control_ids.is_empty() {
        gates.push(ReleasePackageGate {
            gate_id: format!("release-package-gate-{package_token}-split-combine"),
            package_id: Some(package.package_id.clone()),
            gate_type: "split-combine-interface-release".to_string(),
            status: review_status.to_string(),
            required_before: "child-route-or-recomposition-release".to_string(),
            evidence: format!(
                "decomposition targets={}, interface controls={}",
                package.decomposition_target_ids.len(),
                package.interface_control_ids.len()
            ),
            release_blocker: blocked,
        });
    }
    gates
}

fn release_package_for_program(
    program: &GeneratedProgram,
    analyzed_programs: &[AnalyzedProgram],
    design_exports: &DesignExportBundle,
    process_graph: &ProcessGraph,
    quality_plan: &QualityPlan,
    fixture_plan: &FixturePlan,
    monitoring_plan: &MonitoringPlan,
    interface_control_plan: &InterfaceControlPlan,
    decomposition_plan: &DecompositionPlan,
    controller_plan: &ControllerPlan,
    machine_release: &MachineReleaseReport,
) -> ReleasePackage {
    let part_id = Some(program.part_id.as_str());
    let program_id = Some(program.program_id.as_str());
    let design_export_ids = release_package_design_export_ids(part_id, program_id, design_exports);
    let fixture_setup_ids = release_package_fixture_setup_ids(part_id, program_id, fixture_plan);
    let monitoring_point_ids =
        release_package_monitoring_point_ids(part_id, program_id, monitoring_plan);
    let quality_inspection_ids =
        release_package_quality_inspection_ids(part_id, program_id, quality_plan);
    let decomposition_target_ids =
        release_package_decomposition_target_ids(part_id, program_id, decomposition_plan);
    let interface_control_ids =
        release_package_interface_control_ids(part_id, interface_control_plan);
    let controller_target_ids = release_package_controller_target_ids(program_id, controller_plan);
    let instruction_program_ids =
        release_package_instruction_program_ids(&program.program_id, analyzed_programs);
    let release_blockers = release_package_blockers(
        part_id,
        program_id,
        design_exports,
        fixture_plan,
        monitoring_plan,
        decomposition_plan,
        interface_control_plan,
        controller_plan,
        machine_release,
    );
    let machine_ready = program.machine_ready
        && release_blockers.is_empty()
        && !machine_release.machine_release_blocked;
    let release_state = release_package_state(&release_blockers, machine_ready);
    let required_artifacts = release_package_required_artifacts(
        program_id,
        &instruction_program_ids,
        &design_export_ids,
        &fixture_setup_ids,
        &monitoring_point_ids,
        &quality_inspection_ids,
        &decomposition_target_ids,
        &interface_control_ids,
        &controller_target_ids,
    );
    let package_id = artifact_id("release-package", &program.program_id);
    ReleasePackage {
        learning_observation: format!("release-package:{}:{release_state}", package_id),
        package_id,
        package_kind: "machine-program-release".to_string(),
        part_id: Some(program.part_id.clone()),
        program_id: Some(program.program_id.clone()),
        instruction_program_ids,
        machine_id: Some(program.machine_id.clone()),
        machine_kind: Some(program.machine_kind.clone()),
        process_node_id: release_package_process_node_id(program_id, part_id, process_graph),
        controller_target_ids,
        design_export_ids,
        fixture_setup_ids,
        monitoring_point_ids,
        quality_inspection_ids,
        decomposition_target_ids,
        interface_control_ids,
        required_artifacts,
        release_blockers,
        release_state,
        machine_ready,
        requires_human_review: !machine_ready,
    }
}

fn assembly_release_package(
    design_exports: &DesignExportBundle,
    quality_plan: &QualityPlan,
    fixture_plan: &FixturePlan,
    monitoring_plan: &MonitoringPlan,
    interface_control_plan: &InterfaceControlPlan,
    decomposition_plan: &DecompositionPlan,
    machine_release: &MachineReleaseReport,
) -> Option<ReleasePackage> {
    if design_exports.assembly_exports.is_empty()
        && interface_control_plan.controls.is_empty()
        && decomposition_plan.recomposition_interfaces.is_empty()
    {
        return None;
    }
    let mut part_ids = BTreeSet::new();
    for control in &interface_control_plan.controls {
        part_ids.insert(control.from_part_id.clone());
        part_ids.insert(control.to_part_id.clone());
    }
    for interface in &decomposition_plan.recomposition_interfaces {
        part_ids.insert(interface.from_part_id.clone());
        part_ids.insert(interface.to_part_id.clone());
    }

    let design_export_ids = design_exports
        .assembly_exports
        .iter()
        .map(|export| export.export_id.clone())
        .collect::<Vec<_>>();
    let fixture_setup_ids = fixture_plan
        .setups
        .iter()
        .filter(|setup| part_ids.contains(&setup.part_id))
        .map(|setup| setup.setup_id.clone())
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let monitoring_point_ids = monitoring_plan
        .monitor_points
        .iter()
        .filter(|point| part_ids.contains(&point.part_id))
        .map(|point| point.monitor_id.clone())
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let quality_inspection_ids = quality_plan
        .inspection_points
        .iter()
        .filter(|point| part_ids.contains(&point.part_id))
        .map(|point| point.inspection_id.clone())
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let decomposition_target_ids = decomposition_plan
        .targets
        .iter()
        .filter(|target| {
            target.target_kind.contains("combine")
                || target.target_kind.contains("recomposition")
                || target
                    .source_part_id
                    .as_ref()
                    .is_some_and(|part| part_ids.contains(part))
                || target
                    .replacement_part_ids
                    .iter()
                    .any(|part| part_ids.contains(part))
        })
        .map(|target| target.target_id.clone())
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let interface_control_ids = interface_control_plan
        .controls
        .iter()
        .map(|control| control.control_id.clone())
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let mut release_blockers = BTreeSet::new();
    for export in &design_exports.assembly_exports {
        release_blockers.extend(
            export
                .blockers
                .iter()
                .map(|blocker| format!("assembly-design-export:{}:{blocker}", export.export_id)),
        );
    }
    for control in &interface_control_plan.controls {
        release_blockers.extend(
            control
                .release_blockers
                .iter()
                .map(|blocker| format!("interface:{}:{blocker}", control.control_id)),
        );
    }
    for target in &decomposition_plan.targets {
        release_blockers.extend(
            target
                .release_blockers
                .iter()
                .map(|blocker| format!("decomposition:{}:{blocker}", target.target_id)),
        );
    }
    if release_blockers.is_empty() && machine_release.machine_release_blocked {
        release_blockers.insert(format!(
            "machine-release-blocked:{}",
            machine_release.status
        ));
    }
    let release_blockers = release_blockers.into_iter().collect::<Vec<_>>();
    let machine_ready = release_blockers.is_empty() && !machine_release.machine_release_blocked;
    let release_state = release_package_state(&release_blockers, machine_ready);
    let mut required_artifacts = BTreeSet::from([
        "assembly-plan".to_string(),
        "design-package".to_string(),
        "design-export-bundle".to_string(),
        "interface-control-plan".to_string(),
        "decomposition-plan".to_string(),
        "machine-release".to_string(),
    ]);
    required_artifacts.extend(design_export_ids.iter().cloned());
    if !fixture_setup_ids.is_empty() {
        required_artifacts.insert("fixture-plan".to_string());
    }
    if !monitoring_point_ids.is_empty() {
        required_artifacts.insert("monitoring-plan".to_string());
    }
    if !quality_inspection_ids.is_empty() {
        required_artifacts.insert("quality-plan".to_string());
    }
    let package_id = "release-package-assembly-recomposition".to_string();
    Some(ReleasePackage {
        learning_observation: format!("release-package:{}:{release_state}", package_id),
        package_id,
        package_kind: "assembly-recomposition-release".to_string(),
        part_id: None,
        program_id: None,
        instruction_program_ids: Vec::new(),
        machine_id: None,
        machine_kind: Some("assembly-or-manual-cell".to_string()),
        process_node_id: None,
        controller_target_ids: Vec::new(),
        design_export_ids,
        fixture_setup_ids,
        monitoring_point_ids,
        quality_inspection_ids,
        decomposition_target_ids,
        interface_control_ids,
        required_artifacts: required_artifacts.into_iter().collect(),
        release_blockers,
        release_state,
        machine_ready,
        requires_human_review: true,
    })
}

fn instruction_program_release_blockers(
    program: &AnalyzedProgram,
    machine_release: &MachineReleaseReport,
) -> Vec<String> {
    let mut blockers = BTreeSet::new();
    for blocker in &machine_release.blockers {
        if blocker.program_id.as_deref() == Some(program.program_id.as_str()) {
            blockers.insert(format!(
                "machine-release:{}:{}",
                blocker.blocker_type, blocker.reason
            ));
        }
    }
    if !program.has_units_mode {
        blockers.insert("instruction-analysis:missing-units-mode".to_string());
    }
    if !program.has_positioning_mode {
        blockers.insert("instruction-analysis:missing-positioning-mode".to_string());
    }
    if !program.has_homing_or_fixture_reference {
        blockers.insert("instruction-analysis:missing-homing-or-fixture-reference".to_string());
    }
    if !program.has_program_end {
        blockers.insert("instruction-analysis:missing-program-end".to_string());
    }
    blockers.into_iter().collect()
}

fn release_package_for_imported_instruction_program(
    program: &AnalyzedProgram,
    machine_release: &MachineReleaseReport,
) -> ReleasePackage {
    let instruction_program_ids = vec![program.program_id.clone()];
    let release_blockers = instruction_program_release_blockers(program, machine_release);
    let machine_ready = false;
    let release_state = release_package_state(&release_blockers, machine_ready);
    let required_artifacts = BTreeSet::from([
        "instruction-programs".to_string(),
        "machine-release".to_string(),
        "simulation-report".to_string(),
        "validation-report".to_string(),
    ])
    .into_iter()
    .collect();
    let package_id = artifact_id("release-package-imported-instruction", &program.program_id);
    ReleasePackage {
        learning_observation: format!("release-package:{}:{release_state}", package_id),
        package_id,
        package_kind: "imported-instruction-release".to_string(),
        part_id: None,
        program_id: Some(program.program_id.clone()),
        instruction_program_ids,
        machine_id: None,
        machine_kind: Some(program.machine_kind.clone()),
        process_node_id: None,
        controller_target_ids: Vec::new(),
        design_export_ids: Vec::new(),
        fixture_setup_ids: Vec::new(),
        monitoring_point_ids: Vec::new(),
        quality_inspection_ids: Vec::new(),
        decomposition_target_ids: Vec::new(),
        interface_control_ids: Vec::new(),
        required_artifacts,
        release_blockers,
        release_state,
        machine_ready,
        requires_human_review: true,
    }
}

fn release_package_plan(
    generated_programs: &[GeneratedProgram],
    analyzed_programs: &[AnalyzedProgram],
    design_exports: &DesignExportBundle,
    process_graph: &ProcessGraph,
    quality_plan: &QualityPlan,
    fixture_plan: &FixturePlan,
    monitoring_plan: &MonitoringPlan,
    interface_control_plan: &InterfaceControlPlan,
    decomposition_plan: &DecompositionPlan,
    controller_plan: &ControllerPlan,
    machine_release: &MachineReleaseReport,
) -> ReleasePackagePlan {
    let mut packages = generated_programs
        .iter()
        .map(|program| {
            release_package_for_program(
                program,
                analyzed_programs,
                design_exports,
                process_graph,
                quality_plan,
                fixture_plan,
                monitoring_plan,
                interface_control_plan,
                decomposition_plan,
                controller_plan,
                machine_release,
            )
        })
        .collect::<Vec<_>>();
    let generated_program_ids = generated_programs
        .iter()
        .map(|program| program.program_id.as_str())
        .collect::<BTreeSet<_>>();
    packages.extend(
        analyzed_programs
            .iter()
            .filter(|program| !generated_program_ids.contains(program.program_id.as_str()))
            .map(|program| {
                release_package_for_imported_instruction_program(program, machine_release)
            }),
    );
    if let Some(assembly_package) = assembly_release_package(
        design_exports,
        quality_plan,
        fixture_plan,
        monitoring_plan,
        interface_control_plan,
        decomposition_plan,
        machine_release,
    ) {
        packages.push(assembly_package);
    }

    let release_gates = packages
        .iter()
        .flat_map(release_package_gates_for_package)
        .collect::<Vec<_>>();
    let ready_package_count = packages
        .iter()
        .filter(|package| package.release_blockers.is_empty())
        .count();
    let blocked_package_count = packages.len().saturating_sub(ready_package_count);
    let machine_release_blocked =
        machine_release.machine_release_blocked || blocked_package_count > 0;
    let status = if machine_release_blocked {
        "release-package-blocked"
    } else if packages.iter().all(|package| package.machine_ready) {
        "machine-ready"
    } else {
        "release-package-review-ready"
    };
    let mut required_artifacts = BTreeSet::from(["release-package-plan".to_string()]);
    for package in &packages {
        required_artifacts.extend(package.required_artifacts.iter().cloned());
    }
    let mut learning_observations = BTreeSet::new();
    learning_observations.insert(format!("release-package-status:{status}"));
    learning_observations.insert(format!("release-package-count:{}", packages.len()));
    learning_observations.extend(
        packages
            .iter()
            .map(|package| package.learning_observation.clone()),
    );
    if blocked_package_count > 0 {
        learning_observations.insert(format!("release-package-blocked:{blocked_package_count}"));
    }

    ReleasePackagePlan {
        schema_version: "dd.fabrication.release-package-plan.v1",
        status: status.to_string(),
        machine_release_blocked,
        package_count: packages.len(),
        ready_package_count,
        blocked_package_count,
        packages,
        release_gates,
        required_artifacts: required_artifacts.into_iter().collect(),
        learning_observations: learning_observations.into_iter().collect(),
        notes: vec![
            "Release packages bundle each generated or imported instruction program, machine program, or assembly handoff with instruction-program analysis, design exports, controller targets, setup, quality, monitoring, split/combine, and blocker evidence needed by downstream review workers".to_string(),
            "Packages are draft release packets; machine-ready status remains false until controller/postprocessor checks, simulation or dry-run evidence, profile evidence, and operator or automation signoff clear all gates".to_string(),
            "Learning observations let MDP/POMDP/neural workers compare which package evidence cleared or blocked print, mill, lathe, sheet-cut, EDM, and assembly routes".to_string(),
        ],
    }
}

fn release_package_plan_learning_actions(plan: &ReleasePackagePlan) -> Vec<String> {
    let mut actions = Vec::new();
    for package in &plan.packages {
        let package_token = normalize_token(&package.package_id);
        if package.release_blockers.is_empty() {
            actions.push(format!("verify-release-package-{package_token}"));
        } else {
            actions.push(format!("clear-release-package-{package_token}"));
        }
    }
    actions.extend(plan.release_gates.iter().map(|gate| {
        let gate_token = normalize_token(&gate.gate_id);
        if gate.release_blocker {
            format!("clear-release-package-gate-{gate_token}")
        } else {
            format!("verify-release-package-gate-{gate_token}")
        }
    }));
    actions.sort();
    actions.dedup();
    actions
}

fn stock_strategy_for_part(part: &PartPlan) -> String {
    match machine_class(&part.machine_kind) {
        MachineClass::Additive if is_resin_printer_kind(&part.machine_kind) => {
            "resin build envelope with reviewed orientation, drain paths, supports, wash, and cure allowances"
                .to_string()
        }
        MachineClass::Additive if is_powder_bed_printer_kind(&part.machine_kind) => {
            "powder-bed nesting envelope with thermal spacing, cooldown allowance, and depowder access"
                .to_string()
        }
        MachineClass::Additive if is_sheet_lamination_printer_kind(&part.machine_kind) => {
            "sheet or foil stack with lot/thickness evidence, registration allowance, trim/cut path, bond/consolidation coupon, and delamination inspection margin"
                .to_string()
        }
        MachineClass::Additive => {
            "filament build envelope with material profile, support strategy, and bed adhesion margin"
                .to_string()
        }
        MachineClass::Mill if is_rotary_index_mill_kind(&part.machine_kind) => {
            "squared or turned stock in a rotary/indexer fixture with A-axis centerline, clearance, and re-probe allowance"
                .to_string()
        }
        MachineClass::Mill if is_horizontal_mill_kind(&part.machine_kind) => {
            "squared stock on tombstone or side-milling fixture with arbor and cutter-width clearance"
                .to_string()
        }
        MachineClass::Mill => {
            "squared stock with roughing allowance, finish allowance, and probed work offset"
                .to_string()
        }
        MachineClass::Lathe => {
            "round bar or turned blank with chuck/grip allowance and cutoff stock".to_string()
        }
        MachineClass::Router => {
            "sheet or panel stock on spoilboard with tabs, hold-down margin, and dust extraction"
                .to_string()
        }
        MachineClass::SheetCut => {
            "sheet stock with kerf coupon, lead-ins, retained tabs, and part-catch allowance".to_string()
        }
        MachineClass::Other if is_hot_wire_foam_cutter_kind(&part.machine_kind) => {
            "foam blank or core stock with density, thickness, template/CNC profile, bow clearance, support, and fume/fire-watch allowance"
                .to_string()
        }
        MachineClass::Other => {
            "operator-defined stock and material certificate before special-process programming"
                .to_string()
        }
    }
}

fn material_feedstock_kind(part: &PartPlan) -> &'static str {
    match machine_class(&part.machine_kind) {
        MachineClass::Additive if is_resin_printer_kind(&part.machine_kind) => "photopolymer-resin",
        MachineClass::Additive if is_metal_pbf_printer_kind(&part.machine_kind) => {
            "qualified-metal-powder-lot"
        }
        MachineClass::Additive if is_multi_material_fdm_printer_kind(&part.machine_kind) => {
            "multi-filament-spool-set"
        }
        MachineClass::Additive if is_paste_extrusion_printer_kind(&part.machine_kind) => {
            "paste-or-clay-feedstock"
        }
        MachineClass::Additive if is_robotic_additive_printer_kind(&part.machine_kind) => {
            "robotic-additive-feedstock"
        }
        MachineClass::Additive if is_sheet_lamination_printer_kind(&part.machine_kind) => {
            "sheet-lamination-stock"
        }
        MachineClass::Additive if is_powder_bed_printer_kind(&part.machine_kind) => {
            "polymer-powder-lot"
        }
        MachineClass::Additive if is_composite_fiber_printer_kind(&part.machine_kind) => {
            "matrix-material-and-fiber-spool"
        }
        MachineClass::Additive if wants_directed_energy_deposition(&part.machine_kind) => {
            "wire-or-powder-feedstock"
        }
        MachineClass::Additive if is_material_jetting_printer_kind(&part.machine_kind) => {
            "material-and-support-cartridges"
        }
        MachineClass::Additive if is_pellet_fgf_printer_kind(&part.machine_kind) => {
            "pellet-feedstock"
        }
        MachineClass::Additive => "filament-spool",
        MachineClass::Lathe => "round-bar-or-tube-stock",
        MachineClass::Mill | MachineClass::Router => "block-plate-or-sheet-blank",
        MachineClass::SheetCut => "sheet-plate-or-panel",
        MachineClass::Other if is_molding_casting_kind(&part.machine_kind) => {
            "resin-silicone-urethane-or-mold-material-kit"
        }
        MachineClass::Other if is_pcb_fabrication_kind(&part.machine_kind) => {
            "copper-clad-pcb-laminate-and-finish-chemistry"
        }
        MachineClass::Other if is_pcb_assembly_kind(&part.machine_kind) => {
            "pcb-panel-solder-paste-and-component-kit"
        }
        MachineClass::Other if is_fixture_tooling_kind(&part.machine_kind) => {
            "fixture-plate-soft-jaw-hardware-and-workholding-kit"
        }
        MachineClass::Other if is_adaptive_compensation_kind(&part.machine_kind) => {
            "measurement-artifact-probe-offset-and-rollback-kit"
        }
        MachineClass::Other if is_insert_installation_kind(&part.machine_kind) => {
            "threaded-insert-hardware-hole-prep-and-torque-test-kit"
        }
        MachineClass::Other if is_adhesive_bonding_kind(&part.machine_kind) => {
            "adhesive-substrate-prep-fixture-cure-and-coupon-kit"
        }
        MachineClass::Other if is_plastic_joining_kind(&part.machine_kind) => {
            "polymer-joint-fixture-weld-stake-solvent-and-proof-kit"
        }
        MachineClass::Other if is_fastener_installation_kind(&part.machine_kind) => {
            "fastener-hardware-threadlocker-torque-tool-and-witness-mark-kit"
        }
        MachineClass::Other if is_rivet_installation_kind(&part.machine_kind) => {
            "rivet-clinch-stake-tooling-hole-stack-and-inspection-kit"
        }
        MachineClass::Other if is_seal_installation_kind(&part.machine_kind) => {
            "gasket-oring-sealant-groove-cleaning-and-leak-test-kit"
        }
        MachineClass::Other if is_bearing_installation_kind(&part.machine_kind) => {
            "bearing-bushing-shaft-press-thermal-fit-and-runout-kit"
        }
        MachineClass::Other if is_dynamic_balancing_kind(&part.machine_kind) => {
            "rotor-fixture-arbor-trial-weight-correction-and-vibration-kit"
        }
        MachineClass::Other if is_part_marking_kind(&part.machine_kind) => {
            "marked-part-artwork-serial-and-fixture-kit"
        }
        MachineClass::Other if is_packaging_labeling_kind(&part.machine_kind) => {
            "label-stock-carton-dunnage-and-ship-doc-kit"
        }
        MachineClass::Other if is_composite_layup_kind(&part.machine_kind) => {
            "fiber-resin-prepreg-core-kit"
        }
        MachineClass::Other if is_hot_wire_foam_cutter_kind(&part.machine_kind) => {
            "foam-blank-or-core-stock"
        }
        MachineClass::Other if is_gear_cutting_kind(&part.machine_kind) => {
            "round-blank-or-gear-stock"
        }
        MachineClass::Other => "operator-declared-material-kit",
    }
}

fn material_requirement_unit(part: &PartPlan) -> &'static str {
    match machine_class(&part.machine_kind) {
        MachineClass::Additive if is_resin_printer_kind(&part.machine_kind) => "ml",
        MachineClass::Additive
            if is_powder_bed_printer_kind(&part.machine_kind)
                || is_metal_pbf_printer_kind(&part.machine_kind) =>
        {
            "cm3"
        }
        MachineClass::Additive if is_sheet_lamination_printer_kind(&part.machine_kind) => "sheets",
        MachineClass::Additive => "g",
        MachineClass::Lathe => "mm blank length",
        MachineClass::Mill | MachineClass::Router | MachineClass::SheetCut => "blank",
        MachineClass::Other => "kit",
    }
}

fn material_estimated_quantity(part: &PartPlan, quantity: u32) -> f64 {
    let base_quantity = match machine_class(&part.machine_kind) {
        MachineClass::Additive if is_resin_printer_kind(&part.machine_kind) => 35.0,
        MachineClass::Additive if is_metal_pbf_printer_kind(&part.machine_kind) => 55.0,
        MachineClass::Additive if is_powder_bed_printer_kind(&part.machine_kind) => 45.0,
        MachineClass::Additive if is_composite_fiber_printer_kind(&part.machine_kind) => 90.0,
        MachineClass::Additive if wants_directed_energy_deposition(&part.machine_kind) => 180.0,
        MachineClass::Additive if is_material_jetting_printer_kind(&part.machine_kind) => 40.0,
        MachineClass::Additive if is_multi_material_fdm_printer_kind(&part.machine_kind) => 140.0,
        MachineClass::Additive if is_paste_extrusion_printer_kind(&part.machine_kind) => 600.0,
        MachineClass::Additive if is_robotic_additive_printer_kind(&part.machine_kind) => 900.0,
        MachineClass::Additive if is_sheet_lamination_printer_kind(&part.machine_kind) => 35.0,
        MachineClass::Additive if is_pellet_fgf_printer_kind(&part.machine_kind) => 450.0,
        MachineClass::Additive => 85.0,
        MachineClass::Lathe => 120.0,
        MachineClass::Mill
        | MachineClass::Router
        | MachineClass::SheetCut
        | MachineClass::Other => 1.0,
    };
    rounded_score(base_quantity * quantity.max(1) as f64)
}

fn material_scrap_allowance_pct(part: &PartPlan) -> f64 {
    let allowance = match machine_class(&part.machine_kind) {
        MachineClass::Additive if is_metal_pbf_printer_kind(&part.machine_kind) => 35.0,
        MachineClass::Additive if is_powder_bed_printer_kind(&part.machine_kind) => 25.0,
        MachineClass::Additive if is_resin_printer_kind(&part.machine_kind) => 20.0,
        MachineClass::Additive if wants_directed_energy_deposition(&part.machine_kind) => 30.0,
        MachineClass::Additive if is_multi_material_fdm_printer_kind(&part.machine_kind) => 22.0,
        MachineClass::Additive if is_paste_extrusion_printer_kind(&part.machine_kind) => 25.0,
        MachineClass::Additive if is_robotic_additive_printer_kind(&part.machine_kind) => 28.0,
        MachineClass::Additive if is_sheet_lamination_printer_kind(&part.machine_kind) => 18.0,
        MachineClass::Additive => 15.0,
        MachineClass::Lathe => 20.0,
        MachineClass::Mill | MachineClass::Router => 18.0,
        MachineClass::SheetCut => 12.0,
        MachineClass::Other => 10.0,
    };
    rounded_score(allowance)
}

fn material_conditioning(part: &PartPlan) -> Vec<String> {
    let mut conditioning = match machine_class(&part.machine_kind) {
        MachineClass::Additive if is_resin_printer_kind(&part.machine_kind) => vec![
            "mix resin and verify batch age before fill".to_string(),
            "confirm vat film, drain orientation, wash, and cure compatibility".to_string(),
        ],
        MachineClass::Additive if is_metal_pbf_printer_kind(&part.machine_kind) => vec![
            "verify metal powder lot, sieve state, refresh ratio, and inert handling log"
                .to_string(),
            "reserve cooldown, depowder, and powder recovery controls".to_string(),
        ],
        MachineClass::Additive if is_powder_bed_printer_kind(&part.machine_kind) => vec![
            "verify powder lot, refresh ratio, humidity, and thermal pack spacing".to_string(),
            "reserve cooldown and depowder handling before release".to_string(),
        ],
        MachineClass::Additive if is_composite_fiber_printer_kind(&part.machine_kind) => vec![
            "load matrix material and verify continuous-fiber spool path".to_string(),
            "confirm fiber cutoff, compaction, and cure/post-cure expectations".to_string(),
        ],
        MachineClass::Additive if wants_directed_energy_deposition(&part.machine_kind) => vec![
            "verify wire or powder feed path, shielding gas, and deposition head calibration"
                .to_string(),
            "confirm preheat, interpass, and thermal inspection plan".to_string(),
        ],
        MachineClass::Additive if is_material_jetting_printer_kind(&part.machine_kind) => vec![
            "verify model and support cartridge levels plus purge/wipe station state".to_string(),
            "confirm UV lamp exposure and support-removal compatibility".to_string(),
        ],
        MachineClass::Additive if is_multi_material_fdm_printer_kind(&part.machine_kind) => vec![
            "dry or condition each filament spool and verify slot/material/color map".to_string(),
            "confirm AMS/MMU/IDEX/toolchanger state, purge tower or wipe tower, prime volume, runout sensors, and resume G92 evidence"
                .to_string(),
        ],
        MachineClass::Additive if is_paste_extrusion_printer_kind(&part.machine_kind) => vec![
            "condition paste or clay batch, deair, and verify rheology/slump before loading"
                .to_string(),
            "confirm nozzle, syringe/ram or auger pressure, bead coupon, drying, shrinkage, and green-part support plan"
                .to_string(),
        ],
        MachineClass::Additive if is_pellet_fgf_printer_kind(&part.machine_kind) => vec![
            "dry pellet feedstock to material profile and verify hopper refill capacity"
                .to_string(),
            "confirm screw purge, bead thermal window, and trim allowance".to_string(),
        ],
        MachineClass::Additive if is_robotic_additive_printer_kind(&part.machine_kind) => vec![
            "verify robotic additive feedstock lot, drying or mix state, and nozzle/extruder purge before loading"
                .to_string(),
            "reserve robot frame/TCP proof, dry-run collision simulation, interlock check, bead coupon, cooldown or cure plan, and dimensional-scan evidence"
                .to_string(),
        ],
        MachineClass::Additive if is_sheet_lamination_printer_kind(&part.machine_kind) => vec![
            "verify sheet or foil stock lot, thickness/gauge, grain or fiber direction, stack order, adhesive lot or ultrasonic energy profile, storage, surface prep, and cleaning before loading"
                .to_string(),
            "reserve layer registration, fiducial/datum proof, hold-down, cut/trim path, bond or ultrasonic consolidation coupon, delamination inspection, and dimensional release evidence"
                .to_string(),
        ],
        MachineClass::Additive => vec![
            "dry or condition filament to material profile".to_string(),
            "verify spool mass, diameter profile, nozzle compatibility, and runout handling"
                .to_string(),
        ],
        MachineClass::Lathe => vec![
            "cut blank with chuck/grip and cutoff allowance".to_string(),
            "verify bar straightness, OD, stick-out, and support requirements".to_string(),
        ],
        MachineClass::Mill => vec![
            "saw or square stock with roughing and finish allowance".to_string(),
            "verify stock thickness, datum access, and workholding clamp clearance".to_string(),
        ],
        MachineClass::Router => vec![
            "verify sheet flatness, spoilboard state, tab margin, and hold-down compatibility"
                .to_string(),
            "stage dust extraction and chip evacuation for the material".to_string(),
        ],
        MachineClass::SheetCut => vec![
            "verify sheet thickness, flatness, kerf coupon area, retained tabs, and part catch"
                .to_string(),
            "stage process support such as gas, abrasive, fume extraction, water table, or slats"
                .to_string(),
        ],
        MachineClass::Other => vec![
            "operator-defined material handling, conditioning, and safety evidence".to_string(),
        ],
    };
    let material_token = normalize_token(&part.material.name);
    if summary_text_has_any(
        &material_token,
        &[
            "nylon",
            "pa",
            "petg",
            "abs",
            "asa",
            "pc",
            "polycarbonate",
            "tpu",
        ],
    ) && !conditioning
        .iter()
        .any(|item| normalize_token(item).contains("dry"))
    {
        conditioning.push("dry hygroscopic polymer feedstock before release".to_string());
    }
    conditioning.sort();
    conditioning.dedup();
    conditioning
}

fn material_required_evidence(part: &PartPlan) -> Vec<String> {
    let mut evidence = vec![
        "material lot, certificate, or operator-declared equivalent".to_string(),
        "available quantity covers planned quantity plus scrap allowance".to_string(),
        "material is compatible with selected machine, process, and safety controls".to_string(),
    ];
    match machine_class(&part.machine_kind) {
        MachineClass::Additive => {
            evidence.push("printer material profile, temperature/exposure settings, and feedstock level/runout evidence".to_string());
            evidence.push(
                "support, adhesion, purge/prime, or build-media readiness evidence".to_string(),
            );
            if is_sheet_lamination_printer_kind(&part.machine_kind) {
                evidence.push("sheet or foil lot, thickness/gauge, stack order, adhesive or ultrasonic energy profile, and storage evidence".to_string());
                evidence.push("layer registration, fiducials, cut/trim path, bond/consolidation coupon, delamination inspection, and dimensional-release evidence".to_string());
            }
        }
        MachineClass::Mill | MachineClass::Router => {
            evidence.push(
                "blank or sheet size with roughing allowance and verified datum access".to_string(),
            );
            evidence.push(
                "workholding, clamp clearance, and chip/dust evacuation evidence".to_string(),
            );
        }
        MachineClass::Lathe => {
            evidence.push(
                "bar/blank diameter, length, stick-out, grip allowance, and support evidence"
                    .to_string(),
            );
            evidence.push("tool, cutoff, catcher/subspindle/tailstock, or part-support evidence when applicable".to_string());
        }
        MachineClass::SheetCut => {
            evidence.push(
                "sheet thickness, cut-chart/kerf coupon, and retained-tab evidence".to_string(),
            );
            evidence.push(
                "process support media, fume/fire controls, and part-catch evidence".to_string(),
            );
        }
        MachineClass::Other => {
            evidence.push(
                "operator material handling and process-specific release signoff".to_string(),
            );
        }
    }
    evidence.sort();
    evidence.dedup();
    evidence
}

fn boundary_is_material_related(boundary: &FailureBoundary) -> bool {
    let combined = format!(
        "{} {} {}",
        boundary.kind, boundary.reason, boundary.suggested_resolution
    );
    summary_text_has_any(
        &combined,
        &[
            "abrasive",
            "bar",
            "bed",
            "blank",
            "certificate",
            "coolant",
            "datum",
            "feedstock",
            "filament",
            "fixture",
            "gas",
            "heat",
            "kerf",
            "lot",
            "material",
            "nozzle",
            "pellet",
            "powder",
            "resin",
            "sheet",
            "slat",
            "stock",
            "support",
            "temperature",
            "waterjet",
            "workholding",
        ],
    )
}

fn material_boundary_applies(boundary: &FailureBoundary, part: &PartPlan) -> bool {
    if !boundary_is_material_related(boundary) {
        return false;
    }
    let combined = normalize_token(&format!(
        "{} {} {} {}",
        boundary.kind,
        boundary.reason,
        boundary.suggested_resolution,
        boundary.program_id.as_deref().unwrap_or_default()
    ));
    [
        part.id.as_str(),
        part.role.as_str(),
        part.machine_kind.as_str(),
        part.manufacturing_method.as_str(),
        part.material.name.as_str(),
    ]
    .iter()
    .any(|value| combined.contains(&normalize_token(value)))
        || boundary.program_id.is_none()
}

fn material_plan(
    material: &MaterialSpec,
    stock: Option<&StockSpec>,
    quantity: u32,
    parts: &[PartPlan],
    validation: &ValidationReport,
    machine_release: &MachineReleaseReport,
) -> MaterialPlan {
    let material_boundary_count = validation
        .failure_boundaries
        .iter()
        .filter(|boundary| boundary_is_material_related(boundary))
        .count();
    let machine_release_material_blockers = machine_release
        .blockers
        .iter()
        .filter(|blocker| {
            summary_text_has_any(
                &format!(
                    "{} {} {}",
                    blocker.blocker_type, blocker.reason, blocker.required_action
                ),
                &[
                    "material",
                    "stock",
                    "feedstock",
                    "workholding",
                    "fixture",
                    "support",
                    "temperature",
                    "gas",
                    "abrasive",
                    "coolant",
                    "fume",
                ],
            )
        })
        .count();

    let route_requirements = parts
        .iter()
        .map(|part| {
            let mut release_blockers = validation
                .failure_boundaries
                .iter()
                .filter(|boundary| material_boundary_applies(boundary, part))
                .map(|boundary| {
                    format!(
                        "{}: {} -> {}",
                        boundary.kind, boundary.reason, boundary.suggested_resolution
                    )
                })
                .collect::<Vec<_>>();
            if stock.is_none()
                && matches!(
                    machine_class(&part.machine_kind),
                    MachineClass::Mill
                        | MachineClass::Lathe
                        | MachineClass::Router
                        | MachineClass::SheetCut
                )
            {
                release_blockers.push(
                    "declared stock dimensions/form required before subtractive or sheet-cutting machine release"
                        .to_string(),
                );
            }
            if machine_release.machine_release_blocked && machine_release_material_blockers > 0 {
                release_blockers.push(
                    "machine-release blockers include material, support-media, fixture, or process-state evidence"
                        .to_string(),
                );
            }
            release_blockers.sort();
            release_blockers.dedup();

            let feedstock_kind = material_feedstock_kind(part).to_string();
            let learning_observation = format!(
                "material-route:{}:{}:{}",
                normalize_token(&part.id),
                normalize_token(&feedstock_kind),
                normalize_token(&part.machine_kind)
            );

            MaterialRouteRequirement {
                requirement_id: format!("material-{}", normalize_token(&part.id)),
                part_id: part.id.clone(),
                machine_kind: part.machine_kind.clone(),
                manufacturing_method: part.manufacturing_method.clone(),
                feedstock_kind,
                stock_form: stock
                    .map(|stock| stock.form.clone())
                    .unwrap_or_else(|| stock_strategy_for_part(part)),
                estimated_quantity: material_estimated_quantity(part, quantity),
                unit: material_requirement_unit(part).to_string(),
                scrap_allowance_pct: material_scrap_allowance_pct(part),
                conditioning: material_conditioning(part),
                required_evidence: material_required_evidence(part),
                release_blockers,
                learning_observation,
            }
        })
        .collect::<Vec<_>>();

    let mut release_gates = vec![
        "material/stock lot and compatibility evidence reviewed".to_string(),
        "quantity and scrap allowance reserved before dispatch".to_string(),
        "conditioning and support-media readiness captured before machine release".to_string(),
    ];
    if material_boundary_count > 0 {
        release_gates.push(
            "material-related failure boundaries resolved or accepted by reviewer".to_string(),
        );
    }
    if machine_release_material_blockers > 0 {
        release_gates
            .push("machine-release material blockers cleared before ready state".to_string());
    }
    release_gates.sort();
    release_gates.dedup();

    let mut learning_observations = route_requirements
        .iter()
        .map(|requirement| requirement.learning_observation.clone())
        .collect::<Vec<_>>();
    if material_boundary_count > 0 {
        learning_observations.push(format!(
            "material-boundary-count:{}",
            material_boundary_count
        ));
    }
    learning_observations.sort();
    learning_observations.dedup();

    let release_blocked = route_requirements
        .iter()
        .any(|requirement| !requirement.release_blockers.is_empty());
    let status = if release_blocked {
        "material-blocked"
    } else if material_boundary_count > 0 || machine_release_material_blockers > 0 {
        "material-review-required"
    } else {
        "material-planned"
    };

    MaterialPlan {
        schema_version: "dd.fabrication.material-plan.v1",
        status: status.to_string(),
        review_required: true,
        material: material.clone(),
        declared_stock: stock.cloned(),
        route_requirements,
        release_gates,
        learning_observations,
        notes: vec![
            "Material quantities are advisory planning estimates until CAD mass properties, nesting, slicer, or CAM stock models are finalized".to_string(),
            "Machine-ready release still requires human-reviewed material, stock, feedstock, and support-media evidence".to_string(),
        ],
    }
}

fn datum_scheme_for_part(part: &PartPlan) -> Vec<String> {
    match machine_class(&part.machine_kind) {
        MachineClass::Additive => vec![
            "build-plate-z".to_string(),
            "front-left-origin".to_string(),
            "first-layer-witness".to_string(),
        ],
        MachineClass::Mill if is_rotary_index_mill_kind(&part.machine_kind) => vec![
            "G54 rotary centerline".to_string(),
            "A-axis zero/index stop".to_string(),
            "re-probed indexed face datum".to_string(),
        ],
        MachineClass::Mill if is_horizontal_mill_kind(&part.machine_kind) => vec![
            "G54 tombstone or fixture origin".to_string(),
            "machined side-face datum".to_string(),
            "keyway centerline".to_string(),
        ],
        MachineClass::Mill => vec![
            "G54 stock corner or probe origin".to_string(),
            "machined datum face".to_string(),
            "critical feature centerline".to_string(),
        ],
        MachineClass::Lathe => vec![
            "spindle centerline".to_string(),
            "faced Z0 datum".to_string(),
            "measured finish diameter".to_string(),
        ],
        MachineClass::Router | MachineClass::SheetCut => vec![
            "sheet lower-left origin".to_string(),
            "material top surface".to_string(),
            "kerf/test coupon datum".to_string(),
        ],
        MachineClass::Other => vec![
            "operator-declared primary datum".to_string(),
            "operator-declared inspection datum".to_string(),
        ],
    }
}

fn fixture_strategy_for_part(part: &PartPlan) -> String {
    match machine_class(&part.machine_kind) {
        MachineClass::Additive if is_resin_printer_kind(&part.machine_kind) => {
            "build plate leveling, resin vat inspection, support touchpoint review, and wash/cure fixtures"
                .to_string()
        }
        MachineClass::Additive if is_paste_extrusion_printer_kind(&part.machine_kind) => {
            "paste/clay build board, green-part support fixture, drying tray, and shrinkage witness review"
                .to_string()
        }
        MachineClass::Additive if is_powder_bed_printer_kind(&part.machine_kind) => {
            "powder-bed nesting, thermal pack spacing, cooldown containment, and depowder fixtures"
                .to_string()
        }
        MachineClass::Additive => {
            "slicer-generated supports with brim/raft decision and first-layer verification".to_string()
        }
        MachineClass::Mill if is_rotary_index_mill_kind(&part.machine_kind) => {
            "rotary table or indexer fixture with brake/clamp verification, cable sweep, clearance dry-run, and re-probe stops"
                .to_string()
        }
        MachineClass::Mill if is_horizontal_mill_kind(&part.machine_kind) => {
            "side-milling fixture or tombstone with arbor guard, index stop, and chip evacuation"
                .to_string()
        }
        MachineClass::Mill => {
            "vise or soft jaws with parallels, clamps clear of toolpath, and probe-verified offset"
                .to_string()
        }
        MachineClass::Lathe => {
            "chuck, collet, or soft jaws with stick-out and tool-clearance verification".to_string()
        }
        MachineClass::Router => {
            "vacuum, clamps, tabs, or screws clear of cutter path on sacrificial spoilboard".to_string()
        }
        MachineClass::SheetCut => {
            "slats, honeycomb, or water table support with fire/fume controls and retained tabs"
                .to_string()
        }
        MachineClass::Other => "operator-defined fixture and dry-run approval".to_string(),
    }
}

fn part_release_blockers(
    part: &PartPlan,
    program: Option<&GeneratedProgram>,
    validation: &ValidationReport,
) -> Vec<String> {
    let mut blockers = validation
        .failure_boundaries
        .iter()
        .filter(|boundary| {
            boundary.program_id.as_ref().is_some_and(|program_id| {
                program.is_some_and(|program| program.program_id == *program_id)
            }) || boundary.reason.contains(&part.id)
                || boundary.reason.contains(&part.role)
        })
        .map(|boundary| {
            format!(
                "{}: {} -> {}",
                boundary.kind, boundary.reason, boundary.suggested_resolution
            )
        })
        .collect::<Vec<_>>();
    if blockers.is_empty() {
        blockers.push(
            "draft handoff remains blocked from machine release until CAD/CAM, simulation, and human review are complete"
                .to_string(),
        );
    }
    blockers
}

fn inspection_gates_for_part(
    part: &PartPlan,
    step: Option<&ProcessStep>,
    validation: &ValidationReport,
) -> Vec<String> {
    let mut gates = Vec::new();
    if part.tolerance_mm <= 0.05 {
        gates.push("first-article metrology against datum scheme".to_string());
    }
    if !part.interfaces.is_empty() {
        gates.push("dry-fit and interface inspection before final assembly".to_string());
    }
    if step.is_some_and(|step| step.requires_human_intervention) {
        gates.push("operator checkpoint before machine release".to_string());
    }
    for boundary in &validation.failure_boundaries {
        if boundary.kind.contains("inspection")
            && (boundary.reason.contains(&part.id) || boundary.reason.contains(&part.role))
        {
            gates.push(boundary.suggested_resolution.clone());
        }
    }
    if gates.is_empty() {
        gates.push(
            "review generated draft against final CAD/CAM before machine-ready release".to_string(),
        );
    }
    gates.sort();
    gates.dedup();
    gates
}

fn quality_stage_for_part(part: &PartPlan) -> &'static str {
    match machine_class(&part.machine_kind) {
        MachineClass::Additive if is_resin_printer_kind(&part.machine_kind) => {
            "post-wash-cure-first-article"
        }
        MachineClass::Additive if is_paste_extrusion_printer_kind(&part.machine_kind) => {
            "post-drying-green-part-first-article"
        }
        MachineClass::Additive if is_powder_bed_printer_kind(&part.machine_kind) => {
            "post-cooldown-depowder-first-article"
        }
        MachineClass::Additive => "post-print-first-article",
        MachineClass::Mill | MachineClass::Lathe => "in-process-and-first-article",
        MachineClass::Router | MachineClass::SheetCut => "first-article-and-edge-finish",
        MachineClass::Other => "operator-defined-quality-review",
    }
}

fn quality_method_for_part(part: &PartPlan) -> String {
    match machine_class(&part.machine_kind) {
        MachineClass::Additive if is_resin_printer_kind(&part.machine_kind) => {
            "dimensional first article, support-touchpoint review, wash/cure log, and resin batch trace".to_string()
        }
        MachineClass::Additive if is_paste_extrusion_printer_kind(&part.machine_kind) => {
            "dimensional first article, bead coupon, rheology/slump record, drying/shrinkage log, green-strength review, and firing or cure handoff".to_string()
        }
        MachineClass::Additive if is_powder_bed_printer_kind(&part.machine_kind) => {
            "dimensional first article, depowder completeness, warp review, surface finish, and powder lot trace".to_string()
        }
        MachineClass::Additive => {
            "dimensional first article, first-layer witness, support removal, surface finish, and adhesion review".to_string()
        }
        MachineClass::Mill if is_rotary_index_mill_kind(&part.machine_kind) => {
            "A-axis index verification, clamp/brake witness, re-probed face datum check, CMM or probe stack-up inspection, and burr review".to_string()
        }
        MachineClass::Mill if is_horizontal_mill_kind(&part.machine_kind) => {
            "fixture-index verification, side-slot gauge, CMM or probe datum check, burr review, and tool-wear note".to_string()
        }
        MachineClass::Mill => {
            "probed datum check, CMM or caliper critical-feature inspection, tool-wear note, and burr review".to_string()
        }
        MachineClass::Lathe => {
            "OD/ID micrometer, bore gauge, thread gauge, runout indicator, and surface-finish comparator".to_string()
        }
        MachineClass::Router => {
            "profile gauge, caliper pocket check, tab cleanup review, and spoilboard witness inspection".to_string()
        }
        MachineClass::SheetCut => {
            "kerf coupon, pierce quality, edge/profile gauge, heat-affected-zone review, and fume/fire log".to_string()
        }
        MachineClass::Other => {
            "operator-defined inspection checklist with recorded acceptance evidence".to_string()
        }
    }
}

