fn how_it_works_response() -> Value {
    json!({
        "schemaVersion": "dd.fabrication.how-it-works.v1",
        "routes": ["GET /how-it-works", "GET /fabrication/how-it-works"],
        "purpose": "machine-readable overview of the fabrication server intake-to-release workflow",
        "audiences": ["operators", "integration authors", "CAD/CAM workers", "slicer workers", "learning workers"],
        "startHereWorkflow": [
            {
                "step": "discover",
                "summary": "Inspect capabilities, machines, materials, templates, schemas, and API docs before selecting a worker lane.",
                "primaryRoutes": [
                    "GET /fabrication/capabilities",
                    "GET /fabrication/machines/catalog",
                    "GET /fabrication/materials/catalog",
                    "GET /fabrication/templates/catalog",
                    "GET /api/docs"
                ],
                "evidenceGoal": "choose the right printer, mill, lathe, cutter, material, and request template before submitting work"
            },
            {
                "step": "import-or-generate",
                "summary": "Submit source geometry, slicer/CAM/controller inputs, or a design-generation request and keep every output as draft evidence.",
                "primaryRoutes": [
                    "GET /fabrication/design/import/catalog",
                    "GET /fabrication/design/generation/catalog",
                    "GET /fabrication/instructions/languages",
                    "GET /fabrication/machine-code/catalog",
                    "POST /fabrication/design/generate"
                ],
                "evidenceGoal": "retain source provenance, generated design exports, instruction language, and controller/postprocessor targets"
            },
            {
                "step": "validate-and-improve",
                "summary": "Analyze imported or generated instructions, find release blockers, and create reviewable remediation or improvement drafts.",
                "primaryRoutes": [
                    "GET /fabrication/instructions/validation/catalog",
                    "GET /fabrication/boundaries/catalog",
                    "GET /fabrication/remediation/catalog",
                    "GET /fabrication/improvements/catalog",
                    "POST /fabrication/instructions/validate"
                ],
                "evidenceGoal": "surface machine-failure, human-intervention, split/combine, simulation, and quality blockers before release"
            },
            {
                "step": "split-combine-release",
                "summary": "Decide whether to decompose, assemble, or release the retained package after setup, simulation, quality, and signoff evidence clears.",
                "primaryRoutes": [
                    "GET /fabrication/decomposition/catalog",
                    "GET /fabrication/assembly/catalog",
                    "GET /fabrication/release/catalog",
                    "GET /fabrication/artifacts/catalog",
                    "POST /fabrication/release/preview"
                ],
                "evidenceGoal": "prove interfaces, joins, release gates, retained artifacts, and machineReady blockers before downstream approval"
            },
            {
                "step": "learn-from-results",
                "summary": "Feed completed, failed, remediated, or blocked outcomes back into DES/MDP/POMDP/neural policy memory.",
                "primaryRoutes": [
                    "GET /fabrication/learning/engines/catalog",
                    "GET /fabrication/learning/rewards/catalog",
                    "GET /fabrication/learning/replay/catalog",
                    "GET /fabrication/learning/outcomes",
                    "POST /fabrication/learning/outcomes"
                ],
                "evidenceGoal": "keep learned preferences advisory until replay, simulation, retained evidence, and release blockers clear"
            }
        ],
        "flow": [
            {
                "step": "discover",
                "summary": "Find supported machines, CAD/model/slicer formats, instruction languages, templates, capabilities, and schemas.",
                "routes": [
                    "GET /fabrication/capabilities",
                    "GET /fabrication/formats/catalog",
                    "GET /fabrication/instructions/languages",
                    "GET /fabrication/templates/catalog",
                    "GET /fabrication/schema"
                ],
                "releaseGate": "discovery data is advisory and does not certify machine readiness"
            },
            {
                "step": "intake",
                "summary": "Attach fabrication intent, CAD or mesh sources, slicer/CAM/controller programs, text job sheets, machine profiles, materials, and evidence.",
                "routes": [
                    "POST /fabrication/design/import/review",
                    "POST /fabrication/instructions/import/review",
                    "POST /fabrication/plan"
                ],
                "releaseGate": "native CAD, ambiguous formats, imported programs, and text instructions stay blocked until translator, controller, setup, and source-system evidence is retained"
            },
            {
                "step": "generate",
                "summary": "Draft design packages, machine-code or printer instructions, toolpaths, setup sheets, schedules, decomposition plans, and assembly/interface plans.",
                "routes": [
                    "POST /fabrication/design/generate",
                    "POST /fabrication/machine-code/generate",
                    "POST /fabrication/instructions/generate",
                    "POST /fabrication/decomposition/plan",
                    "POST /fabrication/assembly/plan",
                    "POST /fabrication/schedule/plan"
                ],
                "releaseGate": "generated outputs are deterministic draft evidence, not certified controller, slicer, CAD, or fixture output"
            },
            {
                "step": "validate",
                "summary": "Analyze imported or generated instructions for machine-failure, human-intervention, automation, split/combine, simulation, quality, and postprocess boundaries.",
                "routes": [
                    "POST /fabrication/instructions/analyze",
                    "POST /fabrication/instructions/validate",
                    "POST /fabrication/instructions/improve",
                    "POST /fabrication/simulation/run",
                    "GET /fabrication/boundaries/catalog"
                ],
                "releaseGate": "machineReady remains false while failure boundaries, human intervention, simulation, setup, controller, postprocess, or split/combine blockers remain unresolved"
            },
            {
                "step": "release",
                "summary": "Assemble retained artifacts, release probes, quality evidence, operator or automation signoff, and bundle manifests for review.",
                "routes": [
                    "POST /fabrication/release/preview",
                    "GET /fabrication/release/catalog",
                    "GET /fabrication/jobs",
                    "GET /fabrication/jobs/:job_id/release-bundle"
                ],
                "releaseGate": "release previews are compact review packets and do not by themselves approve a real machine run"
            },
            {
                "step": "learn",
                "summary": "Record outcomes, rewards, remediation decisions, replay evidence, and policy snapshots so future MDP/POMDP/DES/neural recommendations can improve.",
                "routes": [
                    "POST /fabrication/learning/outcomes",
                    "GET /fabrication/learning/outcomes",
                    "GET /fabrication/learning/replay/catalog",
                    "GET /fabrication/learning/optimizers/catalog",
                    "GET /fabrication/learning/policy"
                ],
                "releaseGate": "learned preferences remain advisory until replay, simulation, retained evidence, and release blockers clear"
            }
        ],
        "machineFamilies": [
            "3D printers and slicer-driven additive systems",
            "vertical mills, horizontal mills, routers, five-axis, mill-turn, Swiss, and lathe systems",
            "laser, waterjet, plasma, wire EDM, sinker EDM, grinding, inspection, postprocess, and assembly cells",
            "hybrid split/combine routes that join printed, milled, turned, cut, inspected, or postprocessed parts"
        ],
        "releaseGateMatrix": [
            {
                "gateId": "source-provenance",
                "label": "Source provenance",
                "proves": "CAD, mesh, CAM, slicer, controller, macro, and text job-sheet origins are identified before interpretation.",
                "blocks": ["translator release", "controller review", "machine-ready release"],
                "evidenceRoutes": ["POST /fabrication/design/import/review", "POST /fabrication/instructions/import/review"]
            },
            {
                "gateId": "machine-envelope",
                "label": "Machine envelope",
                "proves": "machine axes, fixtures, work offsets, tool length, stock, supports, and controller modal state fit the selected route.",
                "blocks": ["toolpath release", "machine-code release", "unattended run release"],
                "evidenceRoutes": ["POST /fabrication/machines/select", "POST /fabrication/toolpaths/result", "GET /fabrication/machines/catalog"]
            },
            {
                "gateId": "process-readiness",
                "label": "Process readiness",
                "proves": "thermal, extrusion, spindle, feed, coolant, dust, gas, abrasive, resin, powder, or filament state is ready for the operation.",
                "blocks": ["printer instruction release", "subtractive cutting release", "sheet-cutting release"],
                "evidenceRoutes": ["POST /fabrication/instructions/validate", "POST /fabrication/materials/result", "POST /fabrication/utilities/result"]
            },
            {
                "gateId": "simulation-evidence",
                "label": "Simulation evidence",
                "proves": "dry-run, collision, reach, support, quality, postprocess, and release-bundle reviews cleared known blockers.",
                "blocks": ["release preview", "machine-ready release", "learning promotion"],
                "evidenceRoutes": ["POST /fabrication/simulation/run", "POST /fabrication/quality/result", "POST /fabrication/release/preview"]
            },
            {
                "gateId": "human-or-automation-handoff",
                "label": "Human or automation handoff",
                "proves": "operator interventions, automation handoffs, split/combine joins, restart steps, and signoffs are retained.",
                "blocks": ["restart release", "split/combine release", "machine-ready release"],
                "evidenceRoutes": ["POST /fabrication/interventions/result", "POST /fabrication/assembly/result", "GET /fabrication/jobs/:job_id/release-bundle"]
            },
            {
                "gateId": "learning-disposition",
                "label": "Learning disposition",
                "proves": "MDP/POMDP/DES/neural recommendations are tied to retained outcomes and remain advisory until promotion evidence clears.",
                "blocks": ["policy promotion", "learned-route preference release", "unattended repeat-run release"],
                "evidenceRoutes": ["POST /fabrication/learning/outcomes", "GET /fabrication/learning/replay/catalog", "GET /fabrication/learning/policy"]
            }
        ],
        "learningContract": {
            "preferredPrimitiveSource": "remote/submodules/discrete-event-system.rs des_engine",
            "methods": ["MDP", "POMDP", "DES", "neural policy evidence", "reward replay"],
            "promotionRule": "policy recommendations cannot promote to machine-ready release without retained evidence and cleared blockers"
        },
        "priorityDispositionContract": {
            "responseSurface": "priorityDispositions",
            "appliesTo": [
                "worker result review routes",
                "machine-code, simulation, remediation, interface, release, and learning handoffs",
                "human-intervention and split/combine boundary closure"
            ],
            "dispositions": ["blocked", "needs-review", "closed", "pending-blocker-resolution", "ready-for-learning"],
            "learningObservationShape": "<family>:<priority>:<disposition>",
            "releaseRule": "blocked and pending-blocker-resolution priority dispositions keep machineReady false until retained evidence clears the matching release gate"
        },
        "operatorObservability": {
            "dashboard": "/grafana/fabrication",
            "grafanaUid": "dd-fabrication-planner",
            "signals": [
                "request intake",
                "release blockers",
                "NATS fanout",
                "learning feedback",
                "artifact ledgers",
                "runtime capacity"
            ],
            "releaseRule": "operators should inspect dashboard signals and retained release evidence before trusting generated or imported machine work"
        },
        "humanPage": "/fabrication/landing",
        "docs": "/api/docs"
    })
}

async fn how_it_works_http() -> impl IntoResponse {
    Json(how_it_works_response())
}

async fn landing_page() -> axum::response::Html<&'static str> {
    axum::response::Html(
        r#"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>DD Fabrication Server</title>
  <style>
    :root {
      color-scheme: light;
      --ink: #1f2933;
      --muted: #52606d;
      --line: #d9e2ec;
      --panel: #f8fafc;
      --accent: #0f766e;
      --accent-2: #b7791f;
      --bg: #ffffff;
    }
    * { box-sizing: border-box; }
    body {
      margin: 0;
      font-family: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--ink);
      background: var(--bg);
      line-height: 1.55;
    }
    main {
      width: min(1120px, calc(100% - 32px));
      margin: 0 auto;
      padding: 40px 0 56px;
    }
    header {
      border-bottom: 1px solid var(--line);
      padding-bottom: 28px;
      margin-bottom: 28px;
    }
    h1 {
      margin: 0 0 12px;
      font-size: clamp(2rem, 5vw, 4.25rem);
      line-height: 1;
      letter-spacing: 0;
    }
    h2 {
      margin: 0 0 10px;
      font-size: 1.1rem;
      letter-spacing: 0;
    }
    p {
      margin: 0;
      color: var(--muted);
      max-width: 78ch;
    }
    a { color: var(--accent); font-weight: 700; }
    .lede {
      font-size: 1.14rem;
      color: var(--ink);
    }
    .grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
      gap: 14px;
      margin: 26px 0;
    }
    section {
      padding: 18px;
      border: 1px solid var(--line);
      border-radius: 8px;
      background: var(--panel);
      min-height: 100%;
    }
    .flow {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
      gap: 10px;
      margin-top: 18px;
    }
    .step {
      border-left: 4px solid var(--accent);
      padding: 10px 12px;
      background: #ffffff;
      min-height: 86px;
    }
    .step strong, code {
      color: var(--ink);
    }
    code {
      background: #edf2f7;
      border: 1px solid var(--line);
      border-radius: 6px;
      padding: 1px 5px;
      font-size: 0.92em;
    }
    .note {
      margin-top: 22px;
      padding: 14px 16px;
      border-left: 4px solid var(--accent-2);
      background: #fffaf0;
    }
    .gate-list {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
      gap: 10px;
      margin-top: 16px;
      padding: 0;
      list-style: none;
    }
    .gate-list li {
      background: #ffffff;
      border: 1px solid var(--line);
      border-radius: 8px;
      padding: 10px 12px;
    }
    .starter-list {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
      gap: 10px;
      margin: 16px 0 0;
      padding: 0;
      list-style: none;
    }
    .starter-list li {
      background: #ffffff;
      border: 1px solid var(--line);
      border-radius: 8px;
      padding: 12px;
    }
  </style>
</head>
<body>
  <main>
    <header>
      <h1>DD Fabrication Server</h1>
      <p class="lede">A Rust planning and review service for 3D printing, CNC mills and routers, lathes, sheet cutters, EDM, postprocess cells, and hybrid split/combine manufacturing.</p>
    </header>

    <div class="grid">
      <section>
        <h2>What It Takes In</h2>
        <p>Submit fabrication intents, native CAD, mesh/model/slicer sources, machine profiles, existing G-code, CAM intermediate files such as APT/CLDATA, controller programs, or text job sheets.</p>
      </section>
      <section>
        <h2>What It Builds</h2>
        <p>The server creates draft design packages, export bundles, process plans, machine schedules, generated instructions, machine-code reviews, release packages, and job artifacts.</p>
      </section>
      <section>
        <h2>How It Learns</h2>
        <p>Outcomes feed bounded MDP, POMDP, DES, reward, and neural-policy evidence using the local <code>des_engine</code> crate. Learned preferences stay advisory until release gates clear.</p>
      </section>
      <section>
        <h2>How It Stays Safe</h2>
        <p>Machine-ready release is blocked until validation, simulation or dry-run review, controller/postprocessor checks, setup evidence, quality evidence, and operator or automation signoff are attached.</p>
      </section>
    </div>

    <section>
      <h2>How It Works</h2>
      <p>The service turns a submitted fabrication goal into evidence-backed choices: it imports or generates geometry, chooses candidate machines and materials, decomposes or combines parts when a single process is risky, generates or reviews instructions, simulates and validates release blockers, then records outcomes so later jobs can learn from the route.</p>
      <div class="flow">
        <div class="step"><strong>1. Discover</strong><br>Use <code>/fabrication/capabilities</code>, <code>/fabrication/intake/catalog</code>, <code>/fabrication/templates/catalog</code>, schema, and examples.</div>
        <div class="step"><strong>2. Intake</strong><br>Provide design inputs, instructions, machines, materials, and review evidence.</div>
        <div class="step"><strong>3. Plan</strong><br>Generate route, split/combine, setup, toolpath, schedule, and release-package drafts.</div>
        <div class="step"><strong>4. Validate</strong><br>Analyze imported or generated instructions for machine-failure, human-intervention, and release blockers.</div>
        <div class="step"><strong>5. Learn</strong><br>Post outcomes and worker result reviews so future jobs can prefer safer strategies.</div>
        <div class="step"><strong>6. Inspect</strong><br>Fetch retained jobs, artifacts, and release bundles before downstream release review.</div>
      </div>
    </section>

    <section>
      <h2>Start Here</h2>
      <p>Most integrations follow the same evidence path: discover what the service supports, submit source geometry or instructions, ask for a draft plan or review, attach validation results, then feed the outcome back into learning.</p>
      <ul class="starter-list">
        <li><strong>1. Discover</strong><br><a href="/fabrication/capabilities">Capabilities</a>, <a href="/fabrication/machines/catalog">machines</a>, <a href="/fabrication/materials/catalog">materials</a>, and <a href="/fabrication/templates/catalog">request templates</a>.</li>
        <li><strong>2. Import Or Generate</strong><br><a href="/fabrication/design/import/catalog">Design import</a>, <a href="/fabrication/design/generation/catalog">design generation</a>, <a href="/fabrication/instructions/languages">instruction languages</a>, and <a href="/fabrication/machine-code/catalog">machine-code generation</a>.</li>
        <li><strong>3. Validate And Improve</strong><br><a href="/fabrication/instructions/validation/catalog">Validation</a>, <a href="/fabrication/boundaries/catalog">failure boundaries</a>, <a href="/fabrication/remediation/catalog">remediation</a>, and <a href="/fabrication/improvements/catalog">instruction improvement</a>.</li>
        <li><strong>4. Split, Combine, Or Release</strong><br><a href="/fabrication/decomposition/catalog">Decomposition</a>, <a href="/fabrication/assembly/catalog">assembly</a>, <a href="/fabrication/release/catalog">release readiness</a>, and <a href="/fabrication/artifacts/catalog">retained artifacts</a>.</li>
        <li><strong>5. Learn From Results</strong><br><a href="/fabrication/learning/engines/catalog">DES/MDP/POMDP engines</a>, <a href="/fabrication/learning/rewards/catalog">reward terms</a>, <a href="/fabrication/learning/replay/catalog">replay gates</a>, <a href="/fabrication/learning/scenarios/catalog">training scenarios</a>, and <a href="/fabrication/learning/outcomes">outcome memory</a>.</li>
        <li><strong>6. Operate</strong><br><a href="/grafana/fabrication">Fabrication Planner Grafana dashboard</a> shows request intake, release blockers, NATS fanout, learning feedback, artifact ledgers, and runtime capacity before operators trust generated work.</li>
      </ul>
    </section>

    <section>
      <h2>Design And Toolchain Intake</h2>
      <p>Native and cloud CAD intake includes PTC Creo / Pro/ENGINEER, SOLIDWORKS, Autodesk Fusion, Siemens NX, CATIA, Onshape, FreeCAD, OpenSCAD, Blender, and ZBrush, plus neutral and print handoffs such as STEP, Parasolid, STL, 3MF, OBJ, AMF, and slicer projects from PrusaSlicer, OrcaSlicer, Cura, and Bambu Studio. Ambiguous extensions such as <code>.prt</code> and <code>.asm</code> require source-system or translator evidence before downstream release.</p>
    </section>

    <section>
      <h2>Release Gates</h2>
      <p>Generated designs, toolpaths, slicer plans, G-code, controller programs, and job-sheet interpretations stay advisory until the release packet proves each critical gate.</p>
      <ul class="gate-list">
        <li><strong>Source provenance</strong><br>CAD, mesh, CAM, controller, macro, and text instruction origin is identified.</li>
        <li><strong>Machine envelope</strong><br>Axes, fixtures, work offsets, tools, support media, and controller modes are verified.</li>
        <li><strong>Process readiness</strong><br>Thermal, spindle, feed, coolant, dust, gas, abrasive, resin, powder, or filament state is ready.</li>
        <li><strong>Simulation evidence</strong><br>Dry-run, collision, reach, support, quality, and postprocess reviews clear blockers.</li>
        <li><strong>Human or automation handoff</strong><br>Required operator interventions, split/combine joins, and restart steps are signed off.</li>
        <li><strong>Learning disposition</strong><br>MDP/POMDP/DES/neural recommendations remain advisory until retained outcomes support promotion.</li>
      </ul>
    </section>

    <section>
      <h2>Priority Dispositions</h2>
      <p>Worker result routes publish <code>priorityDispositions</code> so review workers can see which evidence lanes are blocked, need review, are closed, or are ready for learning. Blocked and <code>pending-blocker-resolution</code> dispositions keep <code>machineReady</code> false until the matching release gate has retained evidence.</p>
    </section>

    <p class="note">Start with <a href="/docs/api">API docs</a>, <a href="/fabrication/capabilities">capabilities</a>, <a href="/fabrication/intake/catalog">intake guide</a>, <a href="/fabrication/templates/catalog">request templates</a>, <a href="/fabrication/schema">schema</a>, or <a href="/fabrication/examples">examples</a>. This service produces planning and evidence packets; machine-ready release stays gated until validation, simulation, controller/postprocessor review, setup, quality, and signoff evidence clear.</p>
  </main>
</body>
</html>"#,
    )
}

fn safety_boundary_classes() -> Vec<&'static str> {
    vec![
        "machine-release-blocker",
        "machine-envelope",
        "human-intervention",
        "split-boundary",
        "combine-or-assembly-boundary",
        "automation-capability-gap",
        "postprocess-gate",
        "inspection-gate",
        "machine-profile-blocker",
        "material-machine-boundary",
    ]
}

fn boundary_catalog_family(boundary_kind: &str) -> &'static str {
    match boundary_kind {
        "machine-release-blocker" | "machine-envelope" | "machine-profile-blocker" => {
            "machine-release"
        }
        "human-intervention" | "automation-capability-gap" => "intervention-readiness",
        "split-boundary" | "combine-or-assembly-boundary" => "split-combine",
        "postprocess-gate" | "inspection-gate" => "quality-release",
        "material-machine-boundary" => "material-route",
        _ => "general-boundary",
    }
}

