fn postprocess_catalog_response() -> Value {
    let target_contracts = postprocess_catalog_target_contracts();
    let artifact_contracts = postprocess_catalog_artifact_contracts();
    let families = unique_sorted(target_contracts.iter().filter_map(|item| {
        item.get("family")
            .and_then(Value::as_str)
            .map(ToOwned::to_owned)
    }));

    json!({
        "ok": true,
        "service": SERVICE_NAME,
        "schemaVersion": "dd.fabrication.postprocess-catalog.v1",
        "serviceSchemaVersion": SCHEMA_VERSION,
        "routes": ["GET /postprocess/catalog", "GET /fabrication/postprocess/catalog"],
        "targetContractCount": target_contracts.len(),
        "artifactContractCount": artifact_contracts.len(),
        "families": families,
        "planningRoutes": ["POST /plan", "POST /fabrication/plan"],
        "resultRoutes": ["POST /postprocess/result", "POST /fabrication/postprocess/result"],
        "instructionAnalysisRoutes": ["POST /instructions/analyze", "POST /fabrication/instructions/analyze"],
        "responseSurfaces": [
            "postprocessPlan.status",
            "postprocessPlan.controllerTargets",
            "postprocessPlan.requiredArtifacts",
            "postprocessPlan.blockers",
            "postprocessPlan.learningObservations",
            "postprocessResult.targets",
            "postprocessResult.gates",
            "postprocessResult.travelerSteps",
            "postprocessResult.signoffs",
            "postprocessResult.artifacts",
            "qualityPlan.releaseGates",
            "materialPlan.conditioning",
            "releasePackagePlan.packages",
            "machineRelease.blockers"
        ],
        "artifactSurfaces": [
            "postprocess-plan",
            "analysis-postprocess-plan",
            "postprocess-result",
            "postprocess-target-results",
            "postprocess-gates",
            "postprocess-traveler-steps",
            "postprocess-signoffs",
            "mdp-request.artifacts.postprocessPlan",
            "mdp-request.artifacts.postprocessResult",
            "controller-output-package",
            "postprocess-traveler"
        ],
        "learningSurfaces": [
            "postprocessPlan.learningObservations",
            "postprocessResult.learning.observations",
            "postprocess-status:*",
            "postprocess-target:*",
            "postprocess-gate:*",
            "postprocess-traveler-step:*",
            "postprocess-signoff:*",
            "postprocess-blocker:*",
            "quality-gate:*",
            "material-conditioning:*"
        ],
        "releasePolicy": [
            "postprocess catalog entries describe finishing, support-removal, controller-output, traveler, and signoff evidence contracts, not certified process completion",
            "machine-ready release remains blocked while postprocess targets, required artifacts, dry-run gates, quality checks, material conditioning, or operator/automation signoff are unresolved",
            "postprocess observations are retained for MDP/POMDP/neural workers so future planning can learn when to add finishing operations, split parts, combine assemblies, or require human intervention"
        ],
        "targetContracts": target_contracts,
        "artifactContracts": artifact_contracts
    })
}

fn postprocess_planning_response(
    response: &FabricationPlanResponse,
    policy: &LearningPolicySnapshot,
) -> Value {
    let postprocess_blocked = response.postprocess_plan.status != "postprocess-ready"
        || response.machine_release.machine_release_blocked
        || response.release_package_plan.blocked_package_count > 0;
    let dry_run_gate_count = response
        .postprocess_plan
        .controller_targets
        .iter()
        .filter(|target| {
            target.requires_dry_run || target.gates.iter().any(|gate| gate.gate_type == "dry-run")
        })
        .count();
    let human_signoff_target_count = response
        .postprocess_plan
        .controller_targets
        .iter()
        .filter(|target| target.requires_human_signoff)
        .count();
    let mut object = Map::new();
    object.insert("ok".to_string(), json!(response.ok));
    object.insert("service".to_string(), json!(SERVICE_NAME));
    object.insert(
        "schemaVersion".to_string(),
        json!("dd.fabrication.postprocess-planning.v1"),
    );
    object.insert("serviceSchemaVersion".to_string(), json!(SCHEMA_VERSION));
    object.insert("requestId".to_string(), json!(&response.request_id));
    object.insert("jobId".to_string(), json!(&response.job_id));
    object.insert(
        "routes".to_string(),
        json!([
            "POST /postprocess/plan",
            "POST /fabrication/postprocess/plan"
        ]),
    );
    object.insert(
        "planningRoutes".to_string(),
        json!(["POST /plan", "POST /fabrication/plan"]),
    );
    object.insert(
        "catalogRoutes".to_string(),
        json!([
            "GET /postprocess/catalog",
            "GET /fabrication/postprocess/catalog",
            "GET /controllers/catalog",
            "GET /fabrication/controllers/catalog",
            "GET /instructions/generation/catalog",
            "GET /fabrication/instructions/generation/catalog",
            "GET /release/catalog",
            "GET /fabrication/release/catalog",
            "GET /artifacts/catalog",
            "GET /fabrication/artifacts/catalog"
        ]),
    );
    object.insert(
        "machineReady".to_string(),
        json!(!response.machine_release.machine_release_blocked && !postprocess_blocked),
    );
    object.insert(
        "machineReleaseBlocked".to_string(),
        json!(response.machine_release.machine_release_blocked || postprocess_blocked),
    );
    object.insert(
        "postprocessStatus".to_string(),
        json!(&response.postprocess_plan.status),
    );
    object.insert(
        "controllerPlanStatus".to_string(),
        json!(&response.controller_plan.status),
    );
    object.insert(
        "releasePackageStatus".to_string(),
        json!(&response.release_package_plan.status),
    );
    object.insert(
        "controllerTargetCount".to_string(),
        json!(response.postprocess_plan.controller_targets.len()),
    );
    object.insert(
        "requiredArtifactCount".to_string(),
        json!(response.postprocess_plan.required_artifacts.len()),
    );
    object.insert("dryRunGateCount".to_string(), json!(dry_run_gate_count));
    object.insert(
        "humanSignoffTargetCount".to_string(),
        json!(human_signoff_target_count),
    );
    object.insert(
        "postprocessBlockerCount".to_string(),
        json!(response.postprocess_plan.blockers.len()),
    );
    object.insert(
        "releaseBlockerCount".to_string(),
        json!(response.machine_release.blockers.len()),
    );
    object.insert(
        "responseSurfaces".to_string(),
        json!([
            "postprocessPlan.status",
            "postprocessPlan.controllerTargets",
            "postprocessPlan.controllerTargets.gates",
            "postprocessPlan.controllerTargets.outputFormat",
            "postprocessPlan.controllerTargets.postprocessor",
            "postprocessPlan.requiredArtifacts",
            "postprocessPlan.blockers",
            "postprocessPlan.learningObservations",
            "postprocessResult.targets",
            "postprocessResult.gates",
            "postprocessResult.travelerSteps",
            "postprocessResult.signoffs",
            "postprocessResult.artifacts",
            "controllerPlan.compatibilityTargets",
            "controllerPlan.releaseGates",
            "releasePackagePlan.requiredArtifacts",
            "machineRelease.blockers",
            "simulation.programs"
        ]),
    );
    object.insert(
        "artifactSurfaces".to_string(),
        json!([
            "postprocess-plan",
            "controller-plan",
            "release-package-plan",
            "simulation-report",
            "machine-release",
            "generated-machine-program",
            "improved-instruction-program",
            "postprocess-result",
            "postprocess-target-results",
            "postprocess-gates",
            "postprocess-traveler-steps",
            "postprocess-signoffs",
            "mdp-request.artifacts.postprocessPlan",
            "mdp-request.artifacts.postprocessResult"
        ]),
    );
    object.insert(
        "learningSurfaces".to_string(),
        json!([
            "postprocessPlan.learningObservations",
            "postprocess-status:*",
            "postprocess-target:*",
            "postprocess-gate:*",
            "postprocess-traveler-step:*",
            "postprocess-signoff:*",
            "postprocess-blocker:*",
            "controller-release:*",
            "learning.releaseProbePlan",
            "neuralTrainingCorpus.examples"
        ]),
    );
    object.insert(
        "postprocessPolicy".to_string(),
        json!([
            "postprocess planning returns draft controller-output, traveler, dry-run, and signoff evidence packages, not certified machine safety approval",
            "machine-ready release remains blocked while controller targets, postprocessors, dry-run gates, required artifacts, release packages, or operator/automation signoff remain unresolved",
            "postprocess observations are stored and published so MDP/POMDP/neural workers can learn when to change postprocessors, add finishing operations, split parts, combine assemblies, or require human intervention"
        ]),
    );
    object.insert(
        "learningPolicySnapshot".to_string(),
        json!({
            "outcomeCount": policy.outcome_count,
            "successes": policy.successes,
            "failures": policy.failures,
            "averageReward": policy.average_reward
        }),
    );
    object.insert(
        "postprocessPlan".to_string(),
        json!(&response.postprocess_plan),
    );
    object.insert(
        "controllerPlan".to_string(),
        json!(&response.controller_plan),
    );
    object.insert(
        "releasePackagePlan".to_string(),
        json!(&response.release_package_plan),
    );
    object.insert(
        "machineRelease".to_string(),
        json!(&response.machine_release),
    );
    object.insert("simulation".to_string(), json!(&response.simulation));
    object.insert(
        "learning".to_string(),
        json!({
            "engine": &response.learning.engine,
            "enginePolicy": &response.learning.engine_policy,
            "releaseProbePlan": &response.learning.release_probe_plan,
            "neuralTrainingCorpus": &response.learning.neural_training_corpus
        }),
    );
    Value::Object(object)
}

fn workflow_planning_stage(
    stage_id: &str,
    title: &str,
    status: &str,
    blocked: bool,
    route_handoffs: Vec<&'static str>,
    result_handoffs: Vec<&'static str>,
    response_surfaces: Vec<&'static str>,
    evidence_surfaces: Vec<&'static str>,
) -> Value {
    json!({
        "stageId": stage_id,
        "title": title,
        "status": status,
        "blocked": blocked,
        "routeHandoffs": route_handoffs,
        "resultHandoffs": result_handoffs,
        "responseSurfaces": response_surfaces,
        "evidenceSurfaces": evidence_surfaces
    })
}

fn workflow_action_queue(workflow_stages: &[Value]) -> Vec<Value> {
    workflow_stages
        .iter()
        .filter(|stage| {
            stage
                .get("blocked")
                .and_then(Value::as_bool)
                .unwrap_or(false)
        })
        .map(|stage| {
            let stage_id = stage.get("stageId").and_then(Value::as_str).unwrap_or("unknown-stage");
            let (action, priority, learning_signal) = match stage_id {
                "design-intake" => (
                    "review-or-convert-design-input",
                    "high",
                    "workflow-action:design-intake",
                ),
                "machine-material-routing" => (
                    "attach-machine-material-schedule-evidence",
                    "high",
                    "workflow-action:machine-material-routing",
                ),
                "split-combine-assembly" => (
                    "resolve-split-combine-interface-control",
                    "high",
                    "workflow-action:split-combine",
                ),
                "instruction-machine-code" => (
                    "generate-or-review-machine-instructions",
                    "critical",
                    "workflow-action:instruction-machine-code",
                ),
                "validation-remediation-simulation" => (
                    "analyze-remediate-and-simulate-before-release",
                    "critical",
                    "workflow-action:validation-remediation-simulation",
                ),
                "setup-quality-postprocess" => (
                    "attach-setup-quality-monitoring-postprocess-evidence",
                    "high",
                    "workflow-action:setup-quality-postprocess",
                ),
                "execution-release-learning" => (
                    "hold-release-and-record-learning-outcome",
                    "critical",
                    "workflow-action:execution-release-learning",
                ),
                _ => ("review-blocked-workflow-stage", "medium", "workflow-action:unknown"),
            };
            json!({
                "stageId": stage_id,
                "title": stage.get("title").cloned().unwrap_or(Value::Null),
                "status": stage.get("status").cloned().unwrap_or(Value::Null),
                "action": action,
                "priority": priority,
                "machineReadyBlocked": true,
                "routeHandoffs": stage.get("routeHandoffs").cloned().unwrap_or_else(|| json!([])),
                "resultHandoffs": stage.get("resultHandoffs").cloned().unwrap_or_else(|| json!([])),
                "responseSurfaces": stage.get("responseSurfaces").cloned().unwrap_or_else(|| json!([])),
                "evidenceSurfaces": stage.get("evidenceSurfaces").cloned().unwrap_or_else(|| json!([])),
                "learningSignal": learning_signal,
                "releasePolicy": "complete this action or attach explicit waiver/review evidence before machine-ready release"
            })
        })
        .collect()
}

fn workflow_catalog_stage(
    stage_id: &'static str,
    title: &'static str,
    route_handoffs: Vec<&'static str>,
    result_handoffs: Vec<&'static str>,
    response_surfaces: Vec<&'static str>,
    evidence_surfaces: Vec<&'static str>,
    release_gates: Vec<&'static str>,
) -> Value {
    json!({
        "stageId": stage_id,
        "title": title,
        "routeHandoffs": route_handoffs,
        "resultHandoffs": result_handoffs,
        "responseSurfaces": response_surfaces,
        "evidenceSurfaces": evidence_surfaces,
        "releaseGates": release_gates
    })
}

