fn material_readiness_checklist() -> Vec<Value> {
    vec![
        json!({
            "checkId": "lot-certificate-and-traceability",
            "appliesTo": ["filament-spool", "photopolymer-resin", "bar-stock", "sheet-plate-or-panel", "qualified-metal-powder-lot", "composite-prepreg-or-fiber-spool"],
            "requiredEvidence": [
                "material lot or batch identity",
                "certificate, datasheet, or operator material acceptance evidence",
                "source-to-job traceability for split, combined, nested, or batched parts",
                "release-package record linking lot evidence to generated or imported instructions"
            ],
            "blocks": ["materialPlan.routeRequirements", "releasePackagePlan.packages", "machineRelease.blockers"],
            "learningSignals": ["material-lot:*", "traceability:*", "certificate-review:*"]
        }),
        json!({
            "checkId": "conditioning-and-shelf-life-state",
            "appliesTo": ["filament-spool", "pellet-feedstock", "photopolymer-resin", "qualified-metal-powder-lot", "composite-prepreg-or-fiber-spool", "adhesive-or-chemical-process-media"],
            "requiredEvidence": [
                "drying, moisture, humidity, wash/cure, inerting, thaw/out-time, or shelf-life state as applicable",
                "conditioning equipment, temperature, time, and operator or sensor proof",
                "contamination, resin-vat, powder-refresh, or desiccant/dry-box review"
            ],
            "blocks": ["materialPlan.routeRequirements.conditioning", "postprocessPlan.requiredArtifacts", "machineRelease.blockers"],
            "learningSignals": ["material-conditioning:*", "moisture-state:*", "shelf-life:*"]
        }),
        json!({
            "checkId": "quantity-scrap-and-runout-capacity",
            "appliesTo": ["long FDM extrusion jobs", "powder-bed builds", "sheet nests", "bar-fed turning", "hybrid split/combine batches"],
            "requiredEvidence": [
                "required quantity, projected scrap, purge, support, tab, coupon, or test-cut allowance",
                "remaining spool weight, resin volume, powder mass, sheet area, bar length, or support-media capacity",
                "runout, refill, batch-change, or operator intervention plan when capacity is marginal"
            ],
            "blocks": ["materialPlan.quantity", "executionPlan.stopPoints", "machineSchedule.dependencyHolds"],
            "learningSignals": ["material-capacity:*", "runout-risk:*", "scrap-allowance:*"]
        }),
        json!({
            "checkId": "machine-material-process-compatibility",
            "appliesTo": ["additive printers", "mills", "routers", "lathes", "sheet cutters", "postprocess cells", "assembly cells"],
            "requiredEvidence": [
                "selected machine profile supports the material family and feedstock or stock form",
                "tooling, nozzle, abrasive, coolant, support-media, or process recipe matches material requirements",
                "simulation, dry-run, coupon, or first-article evidence for the exact material route"
            ],
            "blocks": ["machineSelection.candidates", "toolingPlan.requirements", "validation.failureBoundaries", "boundarySummary"],
            "learningSignals": ["material-machine-boundary:*", "process-recipe:*", "material-route-risk:*"]
        }),
    ]
}

fn material_catalog_response() -> Value {
    let catalog = material_catalog_targets();
    let families = unique_sorted(catalog.iter().filter_map(|item| {
        item.get("family")
            .and_then(Value::as_str)
            .map(ToOwned::to_owned)
    }));
    let machine_kinds = unique_sorted(catalog.iter().flat_map(|item| {
        item.get("compatibleMachineKinds")
            .and_then(Value::as_array)
            .into_iter()
            .flatten()
            .filter_map(Value::as_str)
            .map(ToOwned::to_owned)
    }));
    let feedstock_kinds = unique_sorted(catalog.iter().flat_map(|item| {
        item.get("feedstockKinds")
            .and_then(Value::as_array)
            .into_iter()
            .flatten()
            .filter_map(Value::as_str)
            .map(ToOwned::to_owned)
    }));

    json!({
        "ok": true,
        "service": SERVICE_NAME,
        "schemaVersion": "dd.fabrication.material-catalog.v1",
        "serviceSchemaVersion": SCHEMA_VERSION,
        "routes": ["GET /materials/catalog", "GET /fabrication/materials/catalog"],
        "materialCount": catalog.len(),
        "families": families,
        "familyCounts": material_catalog_family_counts(&catalog),
        "machineKinds": machine_kinds,
        "feedstockKinds": feedstock_kinds,
        "planningRoutes": ["POST /plan", "POST /fabrication/plan"],
        "instructionAnalysisRoutes": ["POST /instructions/analyze", "POST /fabrication/instructions/analyze"],
        "responseSurfaces": [
            "materialPlan.routeRequirements",
            "materialPlan.releaseGates",
            "validation.failureBoundaries",
            "boundarySummary",
            "toolingPlan.releaseBlockers",
            "releasePackagePlan.packages"
        ],
        "materialReadinessChecklist": material_readiness_checklist(),
        "releasePolicy": [
            "catalog materials are default planning compatibility labels, not certified inventory",
            "machine-ready release remains blocked until material lot/certificate or operator evidence, quantity plus scrap proof, machine profile evidence, process conditioning, and simulation or dry-run review are retained",
            "material-machine-boundary signals are emitted for MDP/POMDP/neural workers when material and selected machine evidence do not match"
        ],
        "materials": catalog
    })
}

fn material_planning_response(
    response: &FabricationPlanResponse,
    policy: &LearningPolicySnapshot,
) -> Value {
    let material_plan = &response.material_plan;
    let material_route_blocker_count = material_plan
        .route_requirements
        .iter()
        .map(|requirement| requirement.release_blockers.len())
        .sum::<usize>();
    let conditioning_step_count = material_plan
        .route_requirements
        .iter()
        .map(|requirement| requirement.conditioning.len())
        .sum::<usize>();
    let required_evidence_count = material_plan
        .route_requirements
        .iter()
        .map(|requirement| requirement.required_evidence.len())
        .sum::<usize>();
    let material_blocked = response.machine_release.machine_release_blocked
        || material_plan.status != "material-planned"
        || material_route_blocker_count > 0;
    let mut object = Map::new();
    object.insert("ok".to_string(), json!(response.ok));
    object.insert("service".to_string(), json!(SERVICE_NAME));
    object.insert(
        "schemaVersion".to_string(),
        json!("dd.fabrication.material-planning.v1"),
    );
    object.insert("serviceSchemaVersion".to_string(), json!(SCHEMA_VERSION));
    object.insert("requestId".to_string(), json!(&response.request_id));
    object.insert("jobId".to_string(), json!(&response.job_id));
    object.insert(
        "routes".to_string(),
        json!(["POST /materials/plan", "POST /fabrication/materials/plan"]),
    );
    object.insert(
        "planningRoutes".to_string(),
        json!(["POST /plan", "POST /fabrication/plan"]),
    );
    object.insert(
        "catalogRoutes".to_string(),
        json!([
            "GET /materials/catalog",
            "GET /fabrication/materials/catalog",
            "GET /machines/catalog",
            "GET /fabrication/machines/catalog",
            "GET /setup/catalog",
            "GET /fabrication/setup/catalog",
            "GET /quality/catalog",
            "GET /fabrication/quality/catalog",
            "GET /release/catalog",
            "GET /fabrication/release/catalog"
        ]),
    );
    object.insert(
        "machineReady".to_string(),
        json!(!response.machine_release.machine_release_blocked && !material_blocked),
    );
    object.insert(
        "machineReleaseBlocked".to_string(),
        json!(response.machine_release.machine_release_blocked || material_blocked),
    );
    object.insert("materialStatus".to_string(), json!(&material_plan.status));
    object.insert(
        "materialReviewRequired".to_string(),
        json!(material_plan.review_required),
    );
    object.insert(
        "materialFamily".to_string(),
        json!(&material_plan.material.family),
    );
    object.insert(
        "routeRequirementCount".to_string(),
        json!(material_plan.route_requirements.len()),
    );
    object.insert(
        "materialRouteBlockerCount".to_string(),
        json!(material_route_blocker_count),
    );
    object.insert(
        "conditioningStepCount".to_string(),
        json!(conditioning_step_count),
    );
    object.insert(
        "requiredEvidenceCount".to_string(),
        json!(required_evidence_count),
    );
    object.insert(
        "releaseGateCount".to_string(),
        json!(material_plan.release_gates.len()),
    );
    object.insert(
        "learningObservationCount".to_string(),
        json!(material_plan.learning_observations.len()),
    );
    object.insert(
        "releaseBlockerCount".to_string(),
        json!(response.machine_release.blockers.len()),
    );
    object.insert(
        "responseSurfaces".to_string(),
        json!([
            "materialPlan.status",
            "materialPlan.material",
            "materialPlan.declaredStock",
            "materialPlan.routeRequirements",
            "materialPlan.routeRequirements.feedstockKind",
            "materialPlan.routeRequirements.stockForm",
            "materialPlan.routeRequirements.conditioning",
            "materialPlan.routeRequirements.requiredEvidence",
            "materialPlan.routeRequirements.releaseBlockers",
            "materialPlan.releaseGates",
            "materialPlan.learningObservations",
            "machineSelection.candidates",
            "toolingPlan.requirements.consumables",
            "validation.failureBoundaries",
            "machineRelease.blockers",
            "releasePackagePlan.requiredArtifacts"
        ]),
    );
    object.insert(
        "artifactSurfaces".to_string(),
        json!([
            "material-plan",
            "machine-selection",
            "tooling-plan",
            "quality-plan",
            "release-package-plan",
            "machine-release",
            "simulation-report",
            "mdp-request.artifacts.materialPlan",
            "parametric-design.materialPlan"
        ]),
    );
    object.insert(
        "learningSurfaces".to_string(),
        json!([
            "materialPlan.learningObservations",
            "material-route:*",
            "material-machine-boundary:*",
            "machine-selection:*",
            "support-media:*",
            "conditioning:*",
            "neuralTrainingCorpus.examples",
            "learning.outcomes"
        ]),
    );
    object.insert(
        "materialPolicy".to_string(),
        json!([
            "material planning returns draft feedstock, stock, lot, quantity, scrap, conditioning, and support-media evidence packages, not certified inventory or material acceptance",
            "machine-ready release remains blocked while material lot/certificate, stock form and dimensions, conditioning, process support media, machine profile evidence, simulation, or operator signoff is unresolved",
            "material observations are stored and published so MDP/POMDP/neural workers can learn when to reroute to another machine, split a part, require conditioning, or request human evidence"
        ]),
    );
    object.insert(
        "learningPolicySnapshot".to_string(),
        json!({
            "outcomeCount": policy.outcome_count,
            "successes": policy.successes,
            "failures": policy.failures,
            "averageReward": policy.average_reward
        }),
    );
    object.insert("materialPlan".to_string(), json!(material_plan));
    object.insert(
        "machineSelection".to_string(),
        json!(&response.machine_selection),
    );
    object.insert("toolingPlan".to_string(), json!(&response.tooling_plan));
    object.insert("qualityPlan".to_string(), json!(&response.quality_plan));
    object.insert(
        "releasePackagePlan".to_string(),
        json!(&response.release_package_plan),
    );
    object.insert(
        "machineRelease".to_string(),
        json!(&response.machine_release),
    );
    object.insert("simulation".to_string(), json!(&response.simulation));
    object.insert(
        "learning".to_string(),
        json!({
            "engine": &response.learning.engine,
            "enginePolicy": &response.learning.engine_policy,
            "neuralTrainingCorpus": &response.learning.neural_training_corpus
        }),
    );
    Value::Object(object)
}

fn validate_material_result_lots(
    lots: Option<Vec<MaterialResultLot>>,
) -> Result<Vec<Value>, String> {
    let lots = lots.unwrap_or_default();
    if lots.len() > MAX_LEARNING_SIGNALS {
        return Err(format!(
            "lots must contain at most {MAX_LEARNING_SIGNALS} entries"
        ));
    }
    let mut seen = BTreeSet::new();
    lots.into_iter()
        .enumerate()
        .map(|(index, lot)| {
            let lot_id = validate_label(&lot.lot_id, &format!("lots[{index}].lotId"))?;
            if !seen.insert(lot_id.clone()) {
                return Err(format!(
                    "lots must have unique lotId values; duplicate {lot_id}"
                ));
            }
            let quantity_available = lot
                .quantity_available
                .map(|value| finite_non_negative(value, &format!("lots[{index}].quantityAvailable")))
                .transpose()?;
            let quantity_required = lot
                .quantity_required
                .map(|value| finite_non_negative(value, &format!("lots[{index}].quantityRequired")))
                .transpose()?;
            Ok(json!({
                "lotId": lot_id,
                "materialId": validate_optional_text(lot.material_id, &format!("lots[{index}].materialId"), MAX_LABEL_LEN)?,
                "materialFamily": validate_optional_text(lot.material_family, &format!("lots[{index}].materialFamily"), MAX_LABEL_LEN)?,
                "feedstockKind": validate_optional_label(lot.feedstock_kind, &format!("lots[{index}].feedstockKind"))?,
                "stockForm": validate_optional_label(lot.stock_form, &format!("lots[{index}].stockForm"))?,
                "status": validate_label(&lot.status, &format!("lots[{index}].status"))?,
                "quantityAvailable": quantity_available,
                "quantityRequired": quantity_required,
                "certificatePresent": lot.certificate_present.unwrap_or(false),
                "traceabilityPresent": lot.traceability_present.unwrap_or(false),
                "moistureOk": lot.moisture_ok.unwrap_or(false),
                "shelfLifeOk": lot.shelf_life_ok.unwrap_or(false),
                "contaminationFree": lot.contamination_free.unwrap_or(false),
                "machineReady": lot.machine_ready.unwrap_or(false),
                "requiresHumanIntervention": lot.requires_human_intervention.unwrap_or(false),
                "evidence": validate_signal_list(lot.evidence, &format!("lots[{index}].evidence"), MAX_TEXT_LEN)?
            }))
        })
        .collect()
}

fn validate_material_result_conditioning(
    conditioning: Option<Vec<MaterialResultConditioning>>,
) -> Result<Vec<Value>, String> {
    let conditioning = conditioning.unwrap_or_default();
    if conditioning.len() > MAX_LEARNING_SIGNALS {
        return Err(format!(
            "conditioning must contain at most {MAX_LEARNING_SIGNALS} entries"
        ));
    }
    let mut seen = BTreeSet::new();
    conditioning
        .into_iter()
        .enumerate()
        .map(|(index, step)| {
            let conditioning_id = validate_label(
                &step.conditioning_id,
                &format!("conditioning[{index}].conditioningId"),
            )?;
            if !seen.insert(conditioning_id.clone()) {
                return Err(format!(
                    "conditioning must have unique conditioningId values; duplicate {conditioning_id}"
                ));
            }
            Ok(json!({
                "conditioningId": conditioning_id,
                "conditioningKind": validate_label(&step.conditioning_kind, &format!("conditioning[{index}].conditioningKind"))?,
                "status": validate_label(&step.status, &format!("conditioning[{index}].status"))?,
                "required": step.required.unwrap_or(true),
                "completed": step.completed.unwrap_or(false),
                "withinProcessWindow": step.within_process_window.unwrap_or(false),
                "machineReady": step.machine_ready.unwrap_or(false),
                "requiresHumanIntervention": step.requires_human_intervention.unwrap_or(false),
                "evidence": validate_signal_list(step.evidence, &format!("conditioning[{index}].evidence"), MAX_TEXT_LEN)?
            }))
        })
        .collect()
}

