fn slicer_profile_catalog_response() -> Value {
    let formats = design_format_catalog();
    let slicer_formats: Vec<Value> = formats
        .iter()
        .filter(|format| format.category == "slicer-project")
        .map(|format| {
            json!({
                "normalizedFormat": format.normalized_format,
                "sourceSystem": format.source_system,
                "extensions": format.extensions,
                "aliases": format.aliases,
                "importStrategy": format.import_strategy,
                "preferredNeutralExports": format.preferred_neutral_exports,
                "slicerTargets": format.slicer_targets,
                "note": format.notes
            })
        })
        .collect();
    let entries = slicer_profile_catalog_entries();
    let slicers = unique_sorted(entries.iter().filter_map(|entry| {
        entry
            .get("slicer")
            .and_then(Value::as_str)
            .map(ToOwned::to_owned)
    }));
    let project_formats = unique_sorted(entries.iter().flat_map(|entry| {
        entry
            .get("projectFormats")
            .and_then(Value::as_array)
            .into_iter()
            .flatten()
            .filter_map(Value::as_str)
            .map(ToOwned::to_owned)
    }));

    json!({
        "ok": true,
        "service": SERVICE_NAME,
        "schemaVersion": "dd.fabrication.slicer-profile-catalog.v1",
        "serviceSchemaVersion": SCHEMA_VERSION,
        "routes": ["GET /slicers/catalog", "GET /fabrication/slicers/catalog"],
        "slicerCount": entries.len(),
        "slicers": slicers,
        "projectFormats": project_formats,
        "supportedSlicerProjectFormats": slicer_formats,
        "workerDispatch": {
            "workerLane": "slicer-profile-reviewer",
            "requestSubject": FABRICATION_DESIGN_CONVERSION_REQUESTS_SUBJECT,
            "resultSubject": FABRICATION_DESIGN_CONVERSION_RESULTS_SUBJECT,
            "queueGroup": FABRICATION_DESIGN_CONVERSION_REQUESTS_QUEUE_GROUP
        },
        "generationRoutes": [
            "POST /instructions/generate",
            "POST /fabrication/instructions/generate",
            "POST /machine-code/generate",
            "POST /fabrication/machine-code/generate",
            "POST /toolpaths/plan",
            "POST /fabrication/toolpaths/plan"
        ],
        "reviewRoutes": [
            "POST /design/import/review",
            "POST /fabrication/design/import/review",
            "POST /slicers/result",
            "POST /fabrication/slicers/result",
            "POST /instructions/validate",
            "POST /fabrication/instructions/validate",
            "POST /simulation/run",
            "POST /fabrication/simulation/run"
        ],
        "responseSurfaces": [
            "designInputReview.conversionPlan",
            "generatedPrograms",
            "controllerPlan.compatibilityTargets",
            "materialPlan.routeRequirements",
            "postprocessPlan.controllerTargets",
            "simulation.riskProfile",
            "machineRelease.blockers"
        ],
        "releasePolicy": [
            "slicer catalog entries describe accepted slicer project/profile evidence and generated instruction handoffs, not certified printer-ready G-code",
            "machine-ready release remains blocked until profile provenance, material/nozzle compatibility, support/orientation, first-layer, simulation, and operator or automation signoff evidence clear",
            "slicer profile, support, first-layer, material-map, and kinematic outcomes are retained as MDP/POMDP/neural learning signals so future print jobs can choose safer slicer settings"
        ],
        "slicerProfiles": entries
    })
}

async fn slicer_profile_catalog_http() -> impl IntoResponse {
    Json(slicer_profile_catalog_response())
}

fn slicer_profile_planning_response(
    response: &FabricationPlanResponse,
    policy: &LearningPolicySnapshot,
) -> Value {
    let mut object = match machine_code_generation_response(response, policy) {
        Value::Object(object) => object,
        _ => Map::new(),
    };
    let slicer_profile_entries = slicer_profile_catalog_entries();
    let additive_program_count = response
        .generated_programs
        .iter()
        .filter(|program| {
            let machine_kind = normalize_token(&program.machine_kind);
            let language = normalize_token(&program.language);
            machine_kind.contains("printer")
                || machine_kind.contains("additive")
                || language.contains("gcode")
        })
        .count();
    let support_evidence_gate_count = response
        .postprocess_plan
        .controller_targets
        .iter()
        .flat_map(|target| target.gates.iter())
        .filter(|gate| {
            let gate_type = normalize_token(&gate.gate_type);
            let evidence = normalize_token(&gate.evidence);
            gate_type.contains("support")
                || gate_type.contains("slicer")
                || gate_type.contains("first-layer")
                || evidence.contains("support")
                || evidence.contains("slicer")
                || evidence.contains("first-layer")
                || evidence.contains("material")
        })
        .count();
    let dry_run_gate_count = response
        .postprocess_plan
        .controller_targets
        .iter()
        .filter(|target| {
            target.requires_dry_run || target.gates.iter().any(|gate| gate.gate_type == "dry-run")
        })
        .count();
    let slicer_blocker_count = response.machine_release.blockers.len()
        + response.postprocess_plan.blockers.len()
        + response.controller_plan.release_gates.len()
        + response.simulation.failure_boundaries.len()
        + response.release_package_plan.blocked_package_count;
    let slicer_blocked = response.machine_release.machine_release_blocked
        || response.postprocess_plan.machine_release_blocked
        || response.controller_plan.machine_release_blocked
        || response.simulation.risk_profile.status != "simulation-ready"
        || response.boundary_summary.human_intervention_required > 0
        || slicer_blocker_count > 0;
    let planned_profiles = response
        .generated_programs
        .iter()
        .map(|program| {
            let process_node = response
                .process_graph
                .nodes
                .iter()
                .find(|node| node.program_id.as_deref() == Some(program.program_id.as_str()));
            let controller_target = response
                .controller_plan
                .compatibility_targets
                .iter()
                .find(|target| target.program_id == program.program_id);
            let postprocess_target = response
                .postprocess_plan
                .controller_targets
                .iter()
                .find(|target| target.program_id == program.program_id);
            let simulation_trace = response
                .simulation
                .programs
                .iter()
                .find(|trace| trace.program_id == program.program_id);
            json!({
                "slicerPlanId": format!("slicer-plan-{}", normalize_token(&program.program_id)),
                "programId": &program.program_id,
                "partId": &program.part_id,
                "machineId": &program.machine_id,
                "machineKind": &program.machine_kind,
                "language": &program.language,
                "draft": program.draft,
                "machineReady": program.machine_ready && !slicer_blocked,
                "instructionLineCount": program.instructions.len(),
                "operation": process_node
                    .map(|node| node.operation.clone())
                    .unwrap_or_else(|| "slicer-program-review".to_string()),
                "profileEvidenceRequired": [
                    "printer profile checksum",
                    "filament or resin profile checksum",
                    "support and orientation review",
                    "first-layer or exposure coupon",
                    "simulation and dry-run evidence"
                ],
                "controllerTarget": controller_target,
                "postprocessTarget": postprocess_target,
                "simulationTrace": simulation_trace,
                "safetyNotes": &program.safety_notes
            })
        })
        .collect::<Vec<_>>();

    object.insert(
        "schemaVersion".to_string(),
        json!("dd.fabrication.slicer-profile-planning.v1"),
    );
    object.insert(
        "routes".to_string(),
        json!(["POST /slicers/plan", "POST /fabrication/slicers/plan"]),
    );
    object.insert(
        "catalogRoutes".to_string(),
        json!([
            "GET /slicers/catalog",
            "GET /fabrication/slicers/catalog",
            "GET /printers/catalog",
            "GET /fabrication/printers/catalog",
            "GET /printers/preflight/catalog",
            "GET /fabrication/printers/preflight/catalog",
            "GET /materials/catalog",
            "GET /fabrication/materials/catalog"
        ]),
    );
    object.insert(
        "resultRoutes".to_string(),
        json!([
            "POST /slicers/result",
            "POST /fabrication/slicers/result",
            "POST /machine-code/generate",
            "POST /fabrication/machine-code/generate",
            "POST /simulation/result",
            "POST /fabrication/simulation/result",
            "POST /quality/result",
            "POST /fabrication/quality/result"
        ]),
    );
    object.insert("slicerPlanning".to_string(), json!(planned_profiles));
    object.insert(
        "slicerProfileCatalog".to_string(),
        json!(slicer_profile_entries),
    );
    object.insert(
        "slicerProfileCount".to_string(),
        json!(slicer_profile_entries.len()),
    );
    object.insert(
        "generatedProgramCount".to_string(),
        json!(response.generated_programs.len()),
    );
    object.insert(
        "additiveProgramCount".to_string(),
        json!(additive_program_count),
    );
    object.insert(
        "controllerTargetCount".to_string(),
        json!(response.postprocess_plan.controller_targets.len()),
    );
    object.insert("dryRunGateCount".to_string(), json!(dry_run_gate_count));
    object.insert(
        "supportEvidenceGateCount".to_string(),
        json!(support_evidence_gate_count),
    );
    object.insert(
        "slicerBlockerCount".to_string(),
        json!(slicer_blocker_count),
    );
    object.insert("slicerBlocked".to_string(), json!(slicer_blocked));
    object.insert(
        "machineReady".to_string(),
        json!(!slicer_blocked && !response.machine_release.machine_release_blocked),
    );
    object.insert(
        "responseSurfaces".to_string(),
        json!([
            "slicerPlanning",
            "slicerPlanning.profileEvidenceRequired",
            "slicerProfileCatalog",
            "generatedPrograms.instructions",
            "postprocessPlan.controllerTargets",
            "controllerPlan.compatibilityTargets",
            "simulation.riskProfile",
            "qualityPlan.inspectionPoints",
            "materialPlan.routeRequirements",
            "fixturePlan.setups",
            "machineRelease.blockers",
            "learning.neuralTrainingCorpus"
        ]),
    );
    object.insert(
        "artifactSurfaces".to_string(),
        json!([
            "slicer-plan",
            "slicer-profile-catalog",
            "slicer-project-package",
            "printer-gcode-package",
            "generated-machine-programs",
            "postprocess-plan",
            "simulation-report",
            "quality-plan",
            "release-package-plan",
            "mdp-request.artifacts.slicerPlan"
        ]),
    );
    object.insert(
        "slicerProfilePolicy".to_string(),
        json!([
            "slicer planning returns draft profile, orientation, support, thermal, material, and generated machine-code evidence, not certified print parameters",
            "machine-ready release remains blocked while material conditioning, profile provenance, support or orientation, first-layer, thermal, simulation, machine-code, dry-run, or signoff evidence is unresolved",
            "slicer profile planning outcomes feed MDP/POMDP/neural workers so future jobs can choose safer profiles, split fragile parts, reroute printers, or require human intervention before release"
        ]),
    );
    object.insert(
        "learningPolicySnapshot".to_string(),
        json!({
            "outcomeCount": policy.outcome_count,
            "successes": policy.successes,
            "failures": policy.failures,
            "averageReward": policy.average_reward
        }),
    );
    object.insert(
        "postprocessPlan".to_string(),
        json!(&response.postprocess_plan),
    );
    object.insert(
        "controllerPlan".to_string(),
        json!(&response.controller_plan),
    );
    object.insert("qualityPlan".to_string(), json!(&response.quality_plan));
    object.insert("materialPlan".to_string(), json!(&response.material_plan));
    object.insert("fixturePlan".to_string(), json!(&response.fixture_plan));
    object.insert(
        "machineRelease".to_string(),
        json!(&response.machine_release),
    );
    object.insert("simulation".to_string(), json!(&response.simulation));
    Value::Object(object)
}

fn validate_slicer_profile_result_checks(
    checks: Option<Vec<SlicerProfileResultCheck>>,
    label: &str,
) -> Result<Vec<Value>, String> {
    let checks = checks.unwrap_or_default();
    if checks.len() > MAX_PROGRAMS {
        return Err(format!(
            "{label} must contain at most {MAX_PROGRAMS} entries"
        ));
    }
    checks
        .into_iter()
        .enumerate()
        .map(|(index, check)| {
            let check_id = validate_label(&check.check_id, &format!("{label}[{index}].checkId"))?;
            let check_kind =
                validate_label(&check.check_kind, &format!("{label}[{index}].checkKind"))?;
            let status = validate_label(&check.status, &format!("{label}[{index}].status"))?;
            let evidence = validate_signal_list(
                check.evidence,
                &format!("{label}[{index}].evidence"),
                MAX_TEXT_LEN,
            )?;
            let message = validate_optional_text(
                check.message,
                &format!("{label}[{index}].message"),
                MAX_TEXT_LEN,
            )?;
            Ok(json!({
                "checkId": check_id,
                "checkKind": check_kind,
                "status": status,
                "required": check.required.unwrap_or(true),
                "releaseBlocker": check.release_blocker.unwrap_or(true),
                "requiresHumanIntervention": check.requires_human_intervention.unwrap_or(false),
                "evidence": evidence,
                "message": message
            }))
        })
        .collect()
}

fn validate_slicer_profile_result_preparation(
    preparation: Option<Vec<SlicerProfileResultPreparation>>,
) -> Result<Vec<Value>, String> {
    let preparation = preparation.unwrap_or_default();
    if preparation.len() > MAX_PROGRAMS {
        return Err(format!(
            "printPreparation must contain at most {MAX_PROGRAMS} entries"
        ));
    }
    preparation
        .into_iter()
        .enumerate()
        .map(|(index, step)| {
            let preparation_id = validate_label(
                &step.preparation_id,
                &format!("printPreparation[{index}].preparationId"),
            )?;
            let preparation_kind = validate_label(
                &step.preparation_kind,
                &format!("printPreparation[{index}].preparationKind"),
            )?;
            let status =
                validate_label(&step.status, &format!("printPreparation[{index}].status"))?;
            let evidence = validate_signal_list(
                step.evidence,
                &format!("printPreparation[{index}].evidence"),
                MAX_TEXT_LEN,
            )?;
            let message = validate_optional_text(
                step.message,
                &format!("printPreparation[{index}].message"),
                MAX_TEXT_LEN,
            )?;
            Ok(json!({
                "preparationId": preparation_id,
                "preparationKind": preparation_kind,
                "status": status,
                "reviewed": step.reviewed.unwrap_or(false),
                "releaseBlocker": step.release_blocker.unwrap_or(true),
                "requiresHumanIntervention": step.requires_human_intervention.unwrap_or(false),
                "evidence": evidence,
                "message": message
            }))
        })
        .collect()
}

fn validate_slicer_profile_result_artifacts(
    artifacts: Option<Vec<SlicerProfileResultArtifact>>,
) -> Result<Vec<Value>, String> {
    let artifacts = artifacts.unwrap_or_default();
    if artifacts.len() > MAX_PROGRAMS {
        return Err(format!(
            "artifacts must contain at most {MAX_PROGRAMS} entries"
        ));
    }
    artifacts
        .into_iter()
        .enumerate()
        .map(|(index, artifact)| {
            let artifact_id = validate_label(
                &artifact.artifact_id,
                &format!("artifacts[{index}].artifactId"),
            )?;
            let artifact_kind = validate_label(
                &artifact.artifact_kind,
                &format!("artifacts[{index}].artifactKind"),
            )?;
            let source_ref_id = validate_optional_label(
                artifact.source_ref_id,
                &format!("artifacts[{index}].sourceRefId"),
            )?;
            let uri =
                validate_optional_text(artifact.uri, &format!("artifacts[{index}].uri"), 2048)?;
            let sha256 =
                validate_optional_label(artifact.sha256, &format!("artifacts[{index}].sha256"))?;
            let format =
                validate_optional_label(artifact.format, &format!("artifacts[{index}].format"))?;
            let evidence = validate_signal_list(
                artifact.evidence,
                &format!("artifacts[{index}].evidence"),
                MAX_TEXT_LEN,
            )?;
            Ok(json!({
                "artifactId": artifact_id,
                "artifactKind": artifact_kind,
                "sourceRefId": source_ref_id,
                "uri": uri,
                "sha256": sha256,
                "format": format,
                "evidence": evidence
            }))
        })
        .collect()
}

fn slicer_profile_result_status_blocks_release(status: &str) -> bool {
    let normalized = normalize_token(status);
    normalized.contains("fail")
        || normalized.contains("blocked")
        || normalized.contains("missing")
        || normalized.contains("unverified")
        || normalized.contains("unreviewed")
        || normalized.contains("warning")
        || normalized.contains("error")
}

fn slicer_profile_result_check_blocks_release(check: &Value) -> bool {
    let required = check
        .get("required")
        .and_then(Value::as_bool)
        .unwrap_or(true);
    let release_blocker = check
        .get("releaseBlocker")
        .and_then(Value::as_bool)
        .unwrap_or(true);
    let status = check.get("status").and_then(Value::as_str).unwrap_or("");
    let evidence_missing = check
        .get("evidence")
        .and_then(Value::as_array)
        .is_none_or(Vec::is_empty);
    (required || release_blocker)
        && (slicer_profile_result_status_blocks_release(status) || evidence_missing)
}

fn slicer_profile_result_preparation_blocks_release(step: &Value) -> bool {
    let release_blocker = step
        .get("releaseBlocker")
        .and_then(Value::as_bool)
        .unwrap_or(true);
    let reviewed = step
        .get("reviewed")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let status = step.get("status").and_then(Value::as_str).unwrap_or("");
    let evidence_missing = step
        .get("evidence")
        .and_then(Value::as_array)
        .is_none_or(Vec::is_empty);
    release_blocker
        && (!reviewed || slicer_profile_result_status_blocks_release(status) || evidence_missing)
}

fn slicer_profile_result_artifact_missing_release_evidence(artifact: &Value) -> bool {
    artifact
        .get("uri")
        .and_then(Value::as_str)
        .is_none_or(str::is_empty)
        || artifact
            .get("sha256")
            .and_then(Value::as_str)
            .is_none_or(|sha| sha.len() != 64)
        || artifact
            .get("format")
            .and_then(Value::as_str)
            .is_none_or(str::is_empty)
        || artifact
            .get("evidence")
            .and_then(Value::as_array)
            .is_none_or(Vec::is_empty)
}

fn slicer_profile_result_review_response(
    request: SlicerProfileResultReviewRequest,
) -> Result<Value, String> {
    let request_id = request_id(request.request_id.as_ref(), "slicer-profile-result");
    let generated_at_ms = now_ms();
    let slicer_result_job_id = safe_job_id("slicer-profile-result", &request_id, generated_at_ms);
    let plan_request_id = validate_optional_label(request.plan_request_id, "planRequestId")?;
    let job_id = validate_optional_label(request.job_id, "jobId")?;
    let worker_id = validate_label(&request.worker_id, "workerId")?;
    let slicer = validate_text(&request.slicer, "slicer", MAX_LABEL_LEN)?;
    let slicer_version =
        validate_optional_text(request.slicer_version, "slicerVersion", MAX_LABEL_LEN)?;
    let printer_id = validate_optional_label(request.printer_id, "printerId")?;
    let printer_family =
        validate_optional_text(request.printer_family, "printerFamily", MAX_LABEL_LEN)?;
    let material_id = validate_optional_label(request.material_id, "materialId")?;
    let release_ready = request.release_ready.unwrap_or(false);
    let profile_checks =
        validate_slicer_profile_result_checks(request.profile_checks, "profileChecks")?;
    let print_preparation = validate_slicer_profile_result_preparation(request.print_preparation)?;
    let machine_code_checks =
        validate_slicer_profile_result_checks(request.machine_code_checks, "machineCodeChecks")?;
    let artifacts = validate_slicer_profile_result_artifacts(request.artifacts)?;
    let warnings = validate_signal_list(request.warnings, "warnings", MAX_TEXT_LEN)?;

    let profile_check_blocker_count = profile_checks
        .iter()
        .filter(|check| slicer_profile_result_check_blocks_release(check))
        .count();
    let preparation_blocker_count = print_preparation
        .iter()
        .filter(|step| slicer_profile_result_preparation_blocks_release(step))
        .count();
    let machine_code_check_blocker_count = machine_code_checks
        .iter()
        .filter(|check| slicer_profile_result_check_blocks_release(check))
        .count();
    let missing_artifact_evidence_count = artifacts
        .iter()
        .filter(|artifact| slicer_profile_result_artifact_missing_release_evidence(artifact))
        .count();
    let human_intervention_required =
        profile_checks
            .iter()
            .chain(machine_code_checks.iter())
            .any(|check| {
                check
                    .get("requiresHumanIntervention")
                    .and_then(Value::as_bool)
                    .unwrap_or(false)
            })
            || print_preparation.iter().any(|step| {
                step.get("requiresHumanIntervention")
                    .and_then(Value::as_bool)
                    .unwrap_or(false)
            });
    let artifact_evidence_missing = artifacts.is_empty() || missing_artifact_evidence_count > 0;
    let release_blocked = !request.success
        || !request.machine_ready
        || !release_ready
        || profile_checks.is_empty()
        || print_preparation.is_empty()
        || machine_code_checks.is_empty()
        || profile_check_blocker_count > 0
        || preparation_blocker_count > 0
        || machine_code_check_blocker_count > 0
        || artifact_evidence_missing;
    let review_status = if !request.success {
        "slicer-profile-result-worker-failed-release-blocked"
    } else if profile_checks.is_empty() {
        "slicer-profile-result-profile-checks-required"
    } else if print_preparation.is_empty() {
        "slicer-profile-result-print-preparation-required"
    } else if machine_code_checks.is_empty() {
        "slicer-profile-result-machine-code-checks-required"
    } else if profile_check_blocker_count > 0 {
        "slicer-profile-result-profile-checks-release-blocked"
    } else if preparation_blocker_count > 0 {
        "slicer-profile-result-print-preparation-release-blocked"
    } else if machine_code_check_blocker_count > 0 {
        "slicer-profile-result-machine-code-release-blocked"
    } else if artifact_evidence_missing {
        "slicer-profile-result-artifact-evidence-required"
    } else if !request.machine_ready {
        "slicer-profile-result-machine-ready-review-required"
    } else if !release_ready {
        "slicer-profile-result-release-ready-review-required"
    } else {
        "slicer-profile-result-ready-for-release-review"
    };

    let mut learning_observations = vec![
        format!("slicer-profile-worker:{worker_id}"),
        format!("slicer-profile-result:{review_status}"),
        format!("slicer:{}", normalize_token(&slicer)),
    ];
    if let Some(printer_family) = printer_family.as_ref() {
        learning_observations.push(format!(
            "slicer-printer-family:{}",
            normalize_token(printer_family)
        ));
    }
    if let Some(material_id) = material_id.as_ref() {
        learning_observations.push(format!("slicer-material:{}", normalize_token(material_id)));
    }
    if release_blocked {
        learning_observations.push("slicer-profile:release-blocked".to_string());
    }
    if human_intervention_required {
        learning_observations.push("slicer-profile:human-intervention-required".to_string());
    }
    if artifact_evidence_missing {
        learning_observations.push("slicer-profile:artifact-evidence-missing".to_string());
    }
    learning_observations.extend(profile_checks.iter().filter_map(|check| {
        check
            .get("checkKind")
            .and_then(Value::as_str)
            .map(|kind| format!("slicer-profile-check:{}", normalize_token(kind)))
    }));
    learning_observations.extend(print_preparation.iter().filter_map(|step| {
        step.get("preparationKind")
            .and_then(Value::as_str)
            .map(|kind| format!("slicer-preparation:{}", normalize_token(kind)))
    }));
    learning_observations.extend(machine_code_checks.iter().filter_map(|check| {
        check
            .get("checkKind")
            .and_then(Value::as_str)
            .map(|kind| format!("slicer-machine-code-check:{}", normalize_token(kind)))
    }));
    learning_observations.sort();
    learning_observations.dedup();

    Ok(json!({
        "ok": true,
        "service": SERVICE_NAME,
        "schemaVersion": "dd.fabrication.slicer-profile-result-review.v1",
        "serviceSchemaVersion": SCHEMA_VERSION,
        "requestId": request_id,
        "slicerProfileResultJobId": slicer_result_job_id,
        "generatedAtMs": generated_at_ms,
        "routes": [
            "POST /slicers/result",
            "POST /fabrication/slicers/result"
        ],
        "catalogRoutes": [
            "GET /slicers/catalog",
            "GET /fabrication/slicers/catalog"
        ],
        "generationRoutes": [
            "POST /toolpaths/plan",
            "POST /fabrication/toolpaths/plan",
            "POST /machine-code/generate",
            "POST /fabrication/machine-code/generate",
            "POST /instructions/generate",
            "POST /fabrication/instructions/generate"
        ],
        "reviewRoutes": [
            "POST /toolpaths/result",
            "POST /fabrication/toolpaths/result",
            "POST /instructions/validation/result",
            "POST /fabrication/instructions/validation/result",
            "POST /simulation/result",
            "POST /fabrication/simulation/result"
        ],
        "reviewStatus": review_status,
        "machineReady": request.machine_ready && !release_blocked,
        "releaseReady": release_ready && !release_blocked,
        "releaseBlocked": release_blocked,
        "profileCheckCount": profile_checks.len(),
        "profileCheckBlockerCount": profile_check_blocker_count,
        "printPreparationCount": print_preparation.len(),
        "printPreparationBlockerCount": preparation_blocker_count,
        "machineCodeCheckCount": machine_code_checks.len(),
        "machineCodeCheckBlockerCount": machine_code_check_blocker_count,
        "artifactCount": artifacts.len(),
        "missingArtifactEvidenceCount": missing_artifact_evidence_count,
        "artifactEvidenceMissing": artifact_evidence_missing,
        "humanInterventionRequired": human_intervention_required,
        "warningCount": warnings.len(),
        "slicerProfileResult": {
            "planRequestId": plan_request_id,
            "jobId": job_id,
            "workerId": worker_id,
            "slicer": slicer,
            "slicerVersion": slicer_version,
            "printerId": printer_id,
            "printerFamily": printer_family,
            "materialId": material_id,
            "success": request.success,
            "machineReady": request.machine_ready,
            "releaseReady": release_ready,
            "profileChecks": profile_checks,
            "printPreparation": print_preparation,
            "machineCodeChecks": machine_code_checks,
            "artifacts": artifacts,
            "warnings": warnings,
            "reviewMetadata": request.review_metadata
        },
        "releaseUpdate": {
            "machineReleaseBlocked": release_blocked,
            "requiredBeforeMachineReady": [
                "slicer profile and printer/material preset provenance are retained with checksum evidence",
                "orientation, support, bed adhesion, first-layer, purge, and material-map print preparation gates are reviewed",
                "generated G-code or slicer project output passes controller, firmware, arc, unit, extrusion, and high-speed kinematic checks",
                "slicer profile result artifacts carry URI, checksum, format, and evidence labels before machine-ready release"
            ],
            "targetSurfaces": [
                "slicerPlan.profileEvidence",
                "toolpathPlan",
                "generatedPrograms",
                "instructionValidation",
                "simulation",
                "qualityPlan",
                "machineRelease",
                "learning.outcomes"
            ]
        },
        "learning": {
            "observations": learning_observations,
            "engineTargets": ["MDP", "POMDP", "neural"],
            "outcomeRoute": "POST /fabrication/learning/outcomes",
            "outcomeDraft": {
                "schemaVersion": "dd.fabrication.slicer-profile-learning-outcome-draft.v1",
                "sourceKind": "slicer-profile-result",
                "sourceJobId": slicer_result_job_id,
                "sourceRequestId": request_id,
                "success": !release_blocked,
                "rewardHint": if release_blocked { -0.62 } else { 0.5 },
                "workerId": worker_id,
                "slicer": slicer,
                "slicerVersion": slicer_version,
                "printerId": printer_id,
                "printerFamily": printer_family,
                "materialId": material_id,
                "profileCheckHints": profile_checks
                    .iter()
                    .filter_map(|check| check.get("checkKind").and_then(Value::as_str))
                    .collect::<Vec<_>>(),
                "profileCheckStatusHints": profile_checks
                    .iter()
                    .filter_map(|check| check.get("status").and_then(Value::as_str))
                    .collect::<Vec<_>>(),
                "preparationHints": print_preparation
                    .iter()
                    .filter_map(|step| step.get("preparationKind").and_then(Value::as_str))
                    .collect::<Vec<_>>(),
                "preparationStatusHints": print_preparation
                    .iter()
                    .filter_map(|step| step.get("status").and_then(Value::as_str))
                    .collect::<Vec<_>>(),
                "machineCodeCheckHints": machine_code_checks
                    .iter()
                    .filter_map(|check| check.get("checkKind").and_then(Value::as_str))
                    .collect::<Vec<_>>(),
                "machineCodeStatusHints": machine_code_checks
                    .iter()
                    .filter_map(|check| check.get("status").and_then(Value::as_str))
                    .collect::<Vec<_>>(),
                "artifactHints": artifacts
                    .iter()
                    .filter_map(|artifact| artifact.get("artifactKind").and_then(Value::as_str))
                    .collect::<Vec<_>>(),
                "featureHints": {
                    "releaseBlocked": release_blocked,
                    "profileCheckBlockerCount": profile_check_blocker_count,
                    "printPreparationBlockerCount": preparation_blocker_count,
                    "machineCodeCheckBlockerCount": machine_code_check_blocker_count,
                    "humanInterventionRequired": human_intervention_required,
                    "artifactEvidenceMissing": artifact_evidence_missing,
                    "missingArtifactEvidenceCount": missing_artifact_evidence_count,
                    "machineReady": request.machine_ready,
                    "releaseReady": release_ready
                },
                "recommendedSubmitRoute": "POST /fabrication/learning/outcomes"
            }
        },
        "artifactSurfaces": [
            "slicer-profile-result",
            "slicer-profile-checks",
            "slicer-print-preparation",
            "slicer-machine-code-checks",
            "slicer-profile-artifacts",
            "slicer-profile-learning-observations",
            "slicer-project-package",
            "printer-gcode-package",
            "mdp-request.artifacts.slicerProfileResult"
        ],
        "slicerProfilePolicy": [
            "slicer profile results are retained print-preparation evidence, not certified printer-ready G-code",
            "machine-ready release remains blocked until profile provenance, material/nozzle compatibility, support/orientation, first-layer, generated machine-code checks, artifacts, and human dispositions clear",
            "slicer profile observations feed MDP/POMDP/neural learning so future print jobs can choose safer profile families, split fragile parts, request support review, or require operator intervention before release"
        ]
    }))
}

fn slicer_profile_result_job_severity(response: &Value) -> String {
    let status = response_str_field(response, "reviewStatus", "");
    let release_blocked = response
        .get("releaseBlocked")
        .and_then(Value::as_bool)
        .unwrap_or(true);
    if status.contains("worker-failed")
        || status.contains("release-blocked")
        || status.contains("checks-required")
        || status.contains("preparation-required")
    {
        "error".to_string()
    } else if release_blocked {
        "warning".to_string()
    } else {
        "ok".to_string()
    }
}

fn stored_slicer_profile_result_job(response: &Value) -> StoredFabricationJob {
    let generated_at_ms = response_u128_field(response, "generatedAtMs");
    let request_id = response_str_field(response, "requestId", "slicer-profile-result");
    let job_id = response_str_field(
        response,
        "slicerProfileResultJobId",
        &safe_job_id("slicer-profile-result", &request_id, generated_at_ms),
    );
    let review_status = response_str_field(response, "reviewStatus", "slicer-profile-result");
    let release_blocked = response
        .get("releaseBlocked")
        .and_then(Value::as_bool)
        .unwrap_or(true);
    let result = response
        .get("slicerProfileResult")
        .cloned()
        .unwrap_or(Value::Null);
    let profile_checks = result
        .get("profileChecks")
        .cloned()
        .unwrap_or_else(|| json!([]));
    let print_preparation = result
        .get("printPreparation")
        .cloned()
        .unwrap_or_else(|| json!([]));
    let machine_code_checks = result
        .get("machineCodeChecks")
        .cloned()
        .unwrap_or_else(|| json!([]));
    let slicer_artifacts = result
        .get("artifacts")
        .cloned()
        .unwrap_or_else(|| json!([]));
    let learning_observations = response
        .get("learning")
        .and_then(|learning| learning.get("observations"))
        .cloned()
        .unwrap_or_else(|| json!([]));
    let artifacts = vec![
        json_artifact(
            "slicer-profile-result".to_string(),
            "slicer-profile-result",
            response.clone(),
            generated_at_ms,
        ),
        json_artifact(
            "slicer-profile-checks".to_string(),
            "slicer-profile-checks",
            profile_checks,
            generated_at_ms,
        ),
        json_artifact(
            "slicer-print-preparation".to_string(),
            "slicer-print-preparation",
            print_preparation,
            generated_at_ms,
        ),
        json_artifact(
            "slicer-machine-code-checks".to_string(),
            "slicer-machine-code-checks",
            machine_code_checks,
            generated_at_ms,
        ),
        json_artifact(
            "slicer-profile-artifacts".to_string(),
            "slicer-profile-artifacts",
            slicer_artifacts,
            generated_at_ms,
        ),
        json_artifact(
            "slicer-profile-learning-observations".to_string(),
            "slicer-profile-learning-observations",
            learning_observations,
            generated_at_ms,
        ),
    ]
    .into_iter()
    .map(|artifact| (artifact.artifact_id.clone(), artifact))
    .collect::<BTreeMap<_, _>>();
    let artifact_ids = artifacts.keys().cloned().collect::<Vec<_>>();

    StoredFabricationJob {
        record: FabricationJobRecord {
            job_id,
            request_id,
            kind: "slicer-profile-result".to_string(),
            status: review_status.clone(),
            ok: !release_blocked,
            severity: slicer_profile_result_job_severity(response),
            summary: format!("slicer profile result review: {review_status}"),
            artifact_count: artifact_ids.len(),
            artifact_ids,
            created_at_ms: generated_at_ms,
            updated_at_ms: generated_at_ms,
        },
        plan: None,
        analysis: None,
        learning: None,
        artifacts,
    }
}

fn store_slicer_profile_result_response(state: &AppState, response: &Value) {
    store_job(state, stored_slicer_profile_result_job(response));
}

fn validate_mesh_repair_result_checks(
    checks: Option<Vec<MeshRepairResultCheck>>,
    field_name: &str,
) -> Result<Vec<Value>, String> {
    let checks = checks.unwrap_or_default();
    if checks.len() > MAX_PROGRAMS {
        return Err(format!(
            "{field_name} must contain at most {MAX_PROGRAMS} entries"
        ));
    }
    checks
        .into_iter()
        .enumerate()
        .map(|(index, check)| {
            let check_id =
                validate_label(&check.check_id, &format!("{field_name}[{index}].checkId"))?;
            let repair_domain = validate_label(
                &check.repair_domain,
                &format!("{field_name}[{index}].repairDomain"),
            )?;
            let check_kind = validate_label(
                &check.check_kind,
                &format!("{field_name}[{index}].checkKind"),
            )?;
            let status = validate_label(&check.status, &format!("{field_name}[{index}].status"))?;
            let evidence = validate_signal_list(
                check.evidence,
                &format!("{field_name}.evidence"),
                MAX_TEXT_LEN,
            )?;
            Ok(json!({
                "checkId": check_id,
                "repairDomain": repair_domain,
                "checkKind": check_kind,
                "status": status,
                "passed": check.passed.unwrap_or(false),
                "releaseBlocker": check.release_blocker.unwrap_or(true),
                "requiresHumanIntervention": check.requires_human_intervention.unwrap_or(false),
                "requiresSplitCombine": check.requires_split_combine.unwrap_or(false),
                "evidence": evidence
            }))
        })
        .collect()
}

fn validate_mesh_repair_dimensional_reviews(
    reviews: Option<Vec<MeshRepairDimensionalReview>>,
) -> Result<Vec<Value>, String> {
    let reviews = reviews.unwrap_or_default();
    if reviews.len() > MAX_PROGRAMS {
        return Err(format!(
            "dimensionalReviews must contain at most {MAX_PROGRAMS} entries"
        ));
    }
    reviews
        .into_iter()
        .enumerate()
        .map(|(index, review)| {
            let review_id = validate_label(
                &review.review_id,
                &format!("dimensionalReviews[{index}].reviewId"),
            )?;
            let feature_id =
                validate_optional_label(review.feature_id, "dimensionalReviews.featureId")?;
            let status = validate_label(
                &review.status,
                &format!("dimensionalReviews[{index}].status"),
            )?;
            let max_drift_mm = review
                .max_drift_mm
                .map(|value| finite_non_negative(value, "dimensionalReviews.maxDriftMm"))
                .transpose()?;
            let tolerance_mm = review
                .tolerance_mm
                .map(|value| finite_positive(value, "dimensionalReviews.toleranceMm"))
                .transpose()?;
            let wall_thickness_mm = review
                .wall_thickness_mm
                .map(|value| finite_positive(value, "dimensionalReviews.wallThicknessMm"))
                .transpose()?;
            let evidence =
                validate_signal_list(review.evidence, "dimensionalReviews.evidence", MAX_TEXT_LEN)?;
            Ok(json!({
                "reviewId": review_id,
                "featureId": feature_id,
                "status": status,
                "maxDriftMm": max_drift_mm,
                "toleranceMm": tolerance_mm,
                "wallThicknessMm": wall_thickness_mm,
                "releaseBlocker": review.release_blocker.unwrap_or(true),
                "requiresRedesign": review.requires_redesign.unwrap_or(false),
                "requiresSplitCombine": review.requires_split_combine.unwrap_or(false),
                "evidence": evidence
            }))
        })
        .collect()
}

fn validate_mesh_repair_result_artifacts(
    artifacts: Option<Vec<MeshRepairResultArtifact>>,
) -> Result<Vec<Value>, String> {
    let artifacts = artifacts.unwrap_or_default();
    if artifacts.len() > MAX_PROGRAMS {
        return Err(format!(
            "artifacts must contain at most {MAX_PROGRAMS} entries"
        ));
    }
    artifacts
        .into_iter()
        .enumerate()
        .map(|(index, artifact)| {
            let artifact_id = validate_label(
                &artifact.artifact_id,
                &format!("artifacts[{index}].artifactId"),
            )?;
            let artifact_kind = validate_label(
                &artifact.artifact_kind,
                &format!("artifacts[{index}].artifactKind"),
            )?;
            let source_ref_id =
                validate_optional_label(artifact.source_ref_id, "artifacts.sourceRefId")?;
            let uri = validate_optional_text(artifact.uri, "artifacts.uri", 2048)?;
            let sha256 = validate_optional_label(artifact.sha256, "artifacts.sha256")?;
            let format = validate_optional_label(artifact.format, "artifacts.format")?;
            let evidence =
                validate_signal_list(artifact.evidence, "artifacts.evidence", MAX_TEXT_LEN)?;
            Ok(json!({
                "artifactId": artifact_id,
                "artifactKind": artifact_kind,
                "sourceRefId": source_ref_id,
                "uri": uri,
                "sha256": sha256,
                "format": format,
                "evidence": evidence
            }))
        })
        .collect()
}

fn mesh_repair_result_status_blocks_release(status: &str) -> bool {
    let status = normalize_token(status);
    status.contains("fail")
        || status.contains("blocked")
        || status.contains("missing")
        || status.contains("nonmanifold")
        || status.contains("drift")
        || status.contains("thin")
        || status.contains("required")
}

fn mesh_repair_result_check_blocks_release(check: &Value) -> bool {
    check
        .get("releaseBlocker")
        .and_then(Value::as_bool)
        .unwrap_or(true)
        || !check
            .get("passed")
            .and_then(Value::as_bool)
            .unwrap_or(false)
        || check
            .get("requiresHumanIntervention")
            .and_then(Value::as_bool)
            .unwrap_or(false)
        || check
            .get("requiresSplitCombine")
            .and_then(Value::as_bool)
            .unwrap_or(false)
        || mesh_repair_result_status_blocks_release(
            check.get("status").and_then(Value::as_str).unwrap_or(""),
        )
}

fn mesh_repair_dimensional_review_blocks_release(review: &Value) -> bool {
    review
        .get("releaseBlocker")
        .and_then(Value::as_bool)
        .unwrap_or(true)
        || review
            .get("requiresRedesign")
            .and_then(Value::as_bool)
            .unwrap_or(false)
        || review
            .get("requiresSplitCombine")
            .and_then(Value::as_bool)
            .unwrap_or(false)
        || mesh_repair_result_status_blocks_release(
            review.get("status").and_then(Value::as_str).unwrap_or(""),
        )
        || match (
            review.get("maxDriftMm").and_then(Value::as_f64),
            review.get("toleranceMm").and_then(Value::as_f64),
        ) {
            (Some(drift), Some(tolerance)) => drift > tolerance,
            _ => false,
        }
}

fn mesh_repair_result_artifact_missing_release_evidence(artifact: &Value) -> bool {
    artifact
        .get("uri")
        .and_then(Value::as_str)
        .is_none_or(str::is_empty)
        || artifact
            .get("sha256")
            .and_then(Value::as_str)
            .is_none_or(|sha| sha.len() != 64)
        || artifact
            .get("evidence")
            .and_then(Value::as_array)
            .is_none_or(Vec::is_empty)
}

fn mesh_repair_result_review_response(
    request: MeshRepairResultReviewRequest,
) -> Result<Value, String> {
    let request_id = request_id(request.request_id.as_ref(), "mesh-repair-result");
    let generated_at_ms = now_ms();
    let mesh_repair_result_job_id = safe_job_id("mesh-repair-result", &request_id, generated_at_ms);
    let plan_request_id = validate_optional_label(request.plan_request_id, "planRequestId")?;
    let job_id = validate_optional_label(request.job_id, "jobId")?;
    let worker_id = validate_label(&request.worker_id, "workerId")?;
    let reviewer = validate_optional_label(request.reviewer, "reviewer")?;
    let reviewer_version =
        validate_optional_text(request.reviewer_version, "reviewerVersion", MAX_LABEL_LEN)?;
    let source_design_id = validate_optional_label(request.source_design_id, "sourceDesignId")?;
    let source_format = validate_optional_label(request.source_format, "sourceFormat")?;
    let target_format = validate_optional_label(request.target_format, "targetFormat")?;
    let slicer_ready = request.slicer_ready.unwrap_or(false);
    let topology_checks =
        validate_mesh_repair_result_checks(request.topology_checks, "topologyChecks")?;
    let dimensional_reviews =
        validate_mesh_repair_dimensional_reviews(request.dimensional_reviews)?;
    let orientation_reviews =
        validate_mesh_repair_result_checks(request.orientation_reviews, "orientationReviews")?;
    let artifacts = validate_mesh_repair_result_artifacts(request.artifacts)?;
    let warnings = validate_signal_list(request.warnings, "warnings", MAX_TEXT_LEN)?;

    let topology_blocker_count = topology_checks
        .iter()
        .filter(|check| mesh_repair_result_check_blocks_release(check))
        .count();
    let dimensional_blocker_count = dimensional_reviews
        .iter()
        .filter(|review| mesh_repair_dimensional_review_blocks_release(review))
        .count();
    let orientation_blocker_count = orientation_reviews
        .iter()
        .filter(|check| mesh_repair_result_check_blocks_release(check))
        .count();
    let human_intervention_required = topology_checks.iter().any(|check| {
        check
            .get("requiresHumanIntervention")
            .and_then(Value::as_bool)
            .unwrap_or(false)
    }) || orientation_reviews.iter().any(|check| {
        check
            .get("requiresHumanIntervention")
            .and_then(Value::as_bool)
            .unwrap_or(false)
    });
    let split_combine_required = topology_checks.iter().any(|check| {
        check
            .get("requiresSplitCombine")
            .and_then(Value::as_bool)
            .unwrap_or(false)
    }) || dimensional_reviews.iter().any(|review| {
        review
            .get("requiresSplitCombine")
            .and_then(Value::as_bool)
            .unwrap_or(false)
    }) || orientation_reviews.iter().any(|check| {
        check
            .get("requiresSplitCombine")
            .and_then(Value::as_bool)
            .unwrap_or(false)
    });
    let redesign_required = dimensional_reviews.iter().any(|review| {
        review
            .get("requiresRedesign")
            .and_then(Value::as_bool)
            .unwrap_or(false)
    });
    let drift_over_tolerance = dimensional_reviews.iter().any(|review| {
        match (
            review.get("maxDriftMm").and_then(Value::as_f64),
            review.get("toleranceMm").and_then(Value::as_f64),
        ) {
            (Some(drift), Some(tolerance)) => drift > tolerance,
            _ => false,
        }
    });
    let missing_artifact_evidence_count = artifacts
        .iter()
        .filter(|artifact| mesh_repair_result_artifact_missing_release_evidence(artifact))
        .count();
    let artifact_evidence_missing = artifacts.is_empty() || missing_artifact_evidence_count > 0;
    let release_blocked = !request.success
        || !request.machine_ready
        || !slicer_ready
        || topology_checks.is_empty()
        || topology_blocker_count > 0
        || dimensional_blocker_count > 0
        || orientation_blocker_count > 0
        || artifact_evidence_missing;
    let review_status = if topology_checks.is_empty() {
        "mesh-repair-result-topology-checks-required"
    } else if !request.success {
        "mesh-repair-result-worker-failed-release-blocked"
    } else if topology_blocker_count > 0 {
        "mesh-repair-result-topology-release-blocked"
    } else if dimensional_blocker_count > 0 {
        "mesh-repair-result-dimensions-release-blocked"
    } else if orientation_blocker_count > 0 {
        "mesh-repair-result-orientation-release-blocked"
    } else if artifact_evidence_missing {
        "mesh-repair-result-artifact-evidence-required"
    } else if !request.machine_ready {
        "mesh-repair-result-machine-ready-review-required"
    } else if !slicer_ready {
        "mesh-repair-result-slicer-ready-review-required"
    } else {
        "mesh-repair-result-ready-for-slicing-review"
    };

    let mut learning_observations = vec![
        format!("mesh-repair-worker:{worker_id}"),
        format!("mesh-repair-result:{review_status}"),
    ];
    if release_blocked {
        learning_observations.push("mesh-repair:release-blocked".to_string());
    }
    if human_intervention_required {
        learning_observations.push("mesh-repair:human-intervention-required".to_string());
    }
    if split_combine_required {
        learning_observations.push("mesh-repair:split-combine-required".to_string());
    }
    if redesign_required {
        learning_observations.push("mesh-repair:redesign-required".to_string());
    }
    if drift_over_tolerance {
        learning_observations.push("mesh-repair:dimension-drift-over-tolerance".to_string());
    }
    learning_observations.extend(topology_checks.iter().filter_map(|check| {
        check
            .get("repairDomain")
            .and_then(Value::as_str)
            .map(|domain| format!("mesh-repair-domain:{}", normalize_token(domain)))
    }));
    learning_observations.extend(topology_checks.iter().filter_map(|check| {
        check
            .get("checkKind")
            .and_then(Value::as_str)
            .map(|kind| format!("mesh-repair-check:{}", normalize_token(kind)))
    }));
    learning_observations.extend(orientation_reviews.iter().filter_map(|check| {
        check
            .get("checkKind")
            .and_then(Value::as_str)
            .map(|kind| format!("mesh-repair-orientation:{}", normalize_token(kind)))
    }));
    learning_observations.sort();
    learning_observations.dedup();
    let topology_learning_hints: Vec<Value> = topology_checks
        .iter()
        .map(|check| {
            json!({
                "checkId": check.get("checkId").cloned().unwrap_or(Value::Null),
                "repairDomain": check.get("repairDomain").cloned().unwrap_or(Value::Null),
                "checkKind": check.get("checkKind").cloned().unwrap_or(Value::Null),
                "status": check.get("status").cloned().unwrap_or(Value::Null),
                "passed": check.get("passed").cloned().unwrap_or(Value::Null),
                "releaseBlocker": check.get("releaseBlocker").cloned().unwrap_or(Value::Null),
                "requiresHumanIntervention": check
                    .get("requiresHumanIntervention")
                    .cloned()
                    .unwrap_or(Value::Null),
                "requiresSplitCombine": check
                    .get("requiresSplitCombine")
                    .cloned()
                    .unwrap_or(Value::Null)
            })
        })
        .collect();
    let dimensional_learning_hints: Vec<Value> = dimensional_reviews
        .iter()
        .map(|review| {
            json!({
                "reviewId": review.get("reviewId").cloned().unwrap_or(Value::Null),
                "featureId": review.get("featureId").cloned().unwrap_or(Value::Null),
                "status": review.get("status").cloned().unwrap_or(Value::Null),
                "maxDriftMm": review.get("maxDriftMm").cloned().unwrap_or(Value::Null),
                "toleranceMm": review.get("toleranceMm").cloned().unwrap_or(Value::Null),
                "wallThicknessMm": review.get("wallThicknessMm").cloned().unwrap_or(Value::Null),
                "releaseBlocker": review.get("releaseBlocker").cloned().unwrap_or(Value::Null),
                "requiresRedesign": review
                    .get("requiresRedesign")
                    .cloned()
                    .unwrap_or(Value::Null),
                "requiresSplitCombine": review
                    .get("requiresSplitCombine")
                    .cloned()
                    .unwrap_or(Value::Null)
            })
        })
        .collect();
    let orientation_learning_hints: Vec<Value> = orientation_reviews
        .iter()
        .map(|check| {
            json!({
                "checkId": check.get("checkId").cloned().unwrap_or(Value::Null),
                "repairDomain": check.get("repairDomain").cloned().unwrap_or(Value::Null),
                "checkKind": check.get("checkKind").cloned().unwrap_or(Value::Null),
                "status": check.get("status").cloned().unwrap_or(Value::Null),
                "passed": check.get("passed").cloned().unwrap_or(Value::Null),
                "releaseBlocker": check.get("releaseBlocker").cloned().unwrap_or(Value::Null),
                "requiresHumanIntervention": check
                    .get("requiresHumanIntervention")
                    .cloned()
                    .unwrap_or(Value::Null),
                "requiresSplitCombine": check
                    .get("requiresSplitCombine")
                    .cloned()
                    .unwrap_or(Value::Null)
            })
        })
        .collect();
    let artifact_learning_hints: Vec<Value> = artifacts
        .iter()
        .map(|artifact| {
            json!({
                "artifactId": artifact.get("artifactId").cloned().unwrap_or(Value::Null),
                "artifactKind": artifact.get("artifactKind").cloned().unwrap_or(Value::Null),
                "sourceRefId": artifact.get("sourceRefId").cloned().unwrap_or(Value::Null),
                "format": artifact.get("format").cloned().unwrap_or(Value::Null),
                "hasUri": artifact
                    .get("uri")
                    .and_then(Value::as_str)
                    .is_some_and(|uri| !uri.trim().is_empty()),
                "hasSha256": artifact
                    .get("sha256")
                    .and_then(Value::as_str)
                    .is_some_and(|sha| !sha.trim().is_empty())
            })
        })
        .collect();

    Ok(json!({
        "ok": true,
        "service": SERVICE_NAME,
        "schemaVersion": "dd.fabrication.mesh-repair-result-review.v1",
        "serviceSchemaVersion": SCHEMA_VERSION,
        "requestId": request_id,
        "meshRepairResultJobId": mesh_repair_result_job_id,
        "generatedAtMs": generated_at_ms,
        "routes": ["POST /mesh-repair/result", "POST /fabrication/mesh-repair/result"],
        "catalogRoutes": ["GET /mesh-repair/catalog", "GET /fabrication/mesh-repair/catalog"],
        "reviewStatus": review_status,
        "machineReady": request.machine_ready && !release_blocked,
        "slicerReady": slicer_ready && !release_blocked,
        "releaseBlocked": release_blocked,
        "topologyCheckCount": topology_checks.len(),
        "topologyBlockerCount": topology_blocker_count,
        "dimensionalReviewCount": dimensional_reviews.len(),
        "dimensionalBlockerCount": dimensional_blocker_count,
        "orientationReviewCount": orientation_reviews.len(),
        "orientationBlockerCount": orientation_blocker_count,
        "humanInterventionRequired": human_intervention_required,
        "splitCombineRequired": split_combine_required,
        "redesignRequired": redesign_required,
        "driftOverTolerance": drift_over_tolerance,
        "artifactCount": artifacts.len(),
        "missingArtifactEvidenceCount": missing_artifact_evidence_count,
        "artifactEvidenceMissing": artifact_evidence_missing,
        "warningCount": warnings.len(),
        "meshRepairResult": {
            "planRequestId": plan_request_id,
            "jobId": job_id,
            "workerId": worker_id,
            "reviewer": reviewer,
            "reviewerVersion": reviewer_version,
            "sourceDesignId": source_design_id,
            "sourceFormat": source_format,
            "targetFormat": target_format,
            "success": request.success,
            "machineReady": request.machine_ready,
            "slicerReady": slicer_ready,
            "topologyChecks": topology_checks,
            "dimensionalReviews": dimensional_reviews,
            "orientationReviews": orientation_reviews,
            "artifacts": artifacts,
            "warnings": warnings,
            "reviewMetadata": request.review_metadata
        },
        "releaseUpdate": {
            "machineReleaseBlocked": release_blocked,
            "requiredBeforeMachineReady": [
                "topology repair checks prove watertight manifold geometry, repaired normals, and self-intersection clearance",
                "dimensional drift, wall thickness, scale, unit, and process-capability reviews are inside tolerance or routed to redesign",
                "orientation, support, first-layer, and split/combine decisions are reviewed before slicer or machine-code release",
                "mesh repair result artifacts retain URI, checksum, format, and evidence labels"
            ]
        },
        "learning": {
            "observations": learning_observations,
            "engineTargets": ["MDP", "POMDP", "neural"],
            "outcomeRoute": "POST /fabrication/learning/outcomes",
            "outcomeDraft": {
                "schemaVersion": "dd.fabrication.mesh-repair-learning-outcome-draft.v1",
                "sourceKind": "mesh-repair-result",
                "sourceJobId": mesh_repair_result_job_id,
                "sourceRequestId": request_id,
                "success": !release_blocked,
                "rewardHint": if release_blocked { -0.62 } else { 0.5 },
                "workerId": worker_id,
                "reviewer": reviewer,
                "sourceFormat": source_format,
                "targetFormat": target_format,
                "topologyHints": topology_learning_hints,
                "dimensionalHints": dimensional_learning_hints,
                "orientationHints": orientation_learning_hints,
                "artifactHints": artifact_learning_hints,
                "featureHints": {
                    "releaseBlocked": release_blocked,
                    "topologyBlockerCount": topology_blocker_count,
                    "dimensionalBlockerCount": dimensional_blocker_count,
                    "orientationBlockerCount": orientation_blocker_count,
                    "artifactEvidenceMissing": artifact_evidence_missing,
                    "humanInterventionRequired": human_intervention_required,
                    "splitCombineRequired": split_combine_required,
                    "redesignRequired": redesign_required,
                    "driftOverTolerance": drift_over_tolerance
                },
                "recommendedSubmitRoute": "POST /fabrication/learning/outcomes"
            }
        },
        "artifactSurfaces": [
            "mesh-repair-result",
            "mesh-repair-topology-checks",
            "mesh-repair-dimensional-reviews",
            "mesh-repair-orientation-reviews",
            "mesh-repair-artifacts",
            "mesh-repair-learning-observations",
            "mdp-request.artifacts.meshRepairResult"
        ],
        "meshRepairResultPolicy": [
            "mesh repair results are retained pre-slice geometry repair evidence, not certified printable geometry",
            "machine-ready release remains blocked until topology, dimensional drift, wall thickness, orientation, support, split/combine, and artifact evidence clear",
            "mesh repair observations feed MDP/POMDP/neural learning so future planners can choose repair, redesign, split/combine, support, or human-review paths earlier"
        ]
    }))
}

fn mesh_repair_result_job_severity(response: &Value) -> String {
    let status = response_str_field(response, "reviewStatus", "");
    let release_blocked = response
        .get("releaseBlocked")
        .and_then(Value::as_bool)
        .unwrap_or(true);
    if status.contains("worker-failed")
        || status.contains("topology-release-blocked")
        || status.contains("dimensions-release-blocked")
        || status.contains("orientation-release-blocked")
    {
        "error".to_string()
    } else if release_blocked {
        "warning".to_string()
    } else {
        "ok".to_string()
    }
}

fn stored_mesh_repair_result_job(response: &Value) -> StoredFabricationJob {
    let generated_at_ms = response_u128_field(response, "generatedAtMs");
    let request_id = response_str_field(response, "requestId", "mesh-repair-result");
    let job_id = response_str_field(
        response,
        "meshRepairResultJobId",
        &safe_job_id("mesh-repair-result", &request_id, generated_at_ms),
    );
    let review_status = response_str_field(response, "reviewStatus", "mesh-repair-result");
    let release_blocked = response
        .get("releaseBlocked")
        .and_then(Value::as_bool)
        .unwrap_or(true);
    let result = response
        .get("meshRepairResult")
        .cloned()
        .unwrap_or(Value::Null);
    let topology_checks = result
        .get("topologyChecks")
        .cloned()
        .unwrap_or_else(|| json!([]));
    let dimensional_reviews = result
        .get("dimensionalReviews")
        .cloned()
        .unwrap_or_else(|| json!([]));
    let orientation_reviews = result
        .get("orientationReviews")
        .cloned()
        .unwrap_or_else(|| json!([]));
    let mesh_repair_artifacts = result
        .get("artifacts")
        .cloned()
        .unwrap_or_else(|| json!([]));
    let learning_observations = response
        .get("learning")
        .and_then(|learning| learning.get("observations"))
        .cloned()
        .unwrap_or_else(|| json!([]));
    let artifacts = vec![
        json_artifact(
            "mesh-repair-result".to_string(),
            "mesh-repair-result",
            response.clone(),
            generated_at_ms,
        ),
        json_artifact(
            "mesh-repair-topology-checks".to_string(),
            "mesh-repair-topology-checks",
            topology_checks,
            generated_at_ms,
        ),
        json_artifact(
            "mesh-repair-dimensional-reviews".to_string(),
            "mesh-repair-dimensional-reviews",
            dimensional_reviews,
            generated_at_ms,
        ),
        json_artifact(
            "mesh-repair-orientation-reviews".to_string(),
            "mesh-repair-orientation-reviews",
            orientation_reviews,
            generated_at_ms,
        ),
        json_artifact(
            "mesh-repair-artifacts".to_string(),
            "mesh-repair-artifacts",
            mesh_repair_artifacts,
            generated_at_ms,
        ),
        json_artifact(
            "mesh-repair-learning-observations".to_string(),
            "mesh-repair-learning-observations",
            learning_observations,
            generated_at_ms,
        ),
    ]
    .into_iter()
    .map(|artifact| (artifact.artifact_id.clone(), artifact))
    .collect::<BTreeMap<_, _>>();
    let artifact_ids = artifacts.keys().cloned().collect::<Vec<_>>();

    StoredFabricationJob {
        record: FabricationJobRecord {
            job_id,
            request_id,
            kind: "mesh-repair-result".to_string(),
            status: review_status.clone(),
            ok: !release_blocked,
            severity: mesh_repair_result_job_severity(response),
            summary: format!("mesh repair result review: {review_status}"),
            artifact_count: artifact_ids.len(),
            artifact_ids,
            created_at_ms: generated_at_ms,
            updated_at_ms: generated_at_ms,
        },
        plan: None,
        analysis: None,
        learning: None,
        artifacts,
    }
}

fn store_mesh_repair_result_response(state: &AppState, response: &Value) {
    store_job(state, stored_mesh_repair_result_job(response));
}

