fn learning_outcomes_memory_response(memory: &LearningMemory) -> Value {
    let snapshot = memory.snapshot();
    let outcomes = memory.outcomes.iter().cloned().collect::<Vec<_>>();
    let success_count = outcomes.iter().filter(|outcome| outcome.success).count();
    let failure_count = outcomes.len().saturating_sub(success_count);
    let positive_reward_count = outcomes
        .iter()
        .filter(|outcome| outcome.reward > 0.0)
        .count();
    let negative_reward_count = outcomes
        .iter()
        .filter(|outcome| outcome.reward < 0.0)
        .count();
    let hybrid_outcome_count = outcomes
        .iter()
        .filter(|outcome| {
            outcome.manufacturing_methods.len() > 1
                || outcome.operation_sequence.len() > 1
                || outcome
                    .assembly_strategy
                    .as_deref()
                    .is_some_and(|strategy| {
                        let strategy = strategy.to_ascii_lowercase();
                        strategy.contains("split")
                            || strategy.contains("combine")
                            || strategy.contains("assembly")
                            || strategy.contains("hybrid")
                            || strategy.contains(" plus ")
                    })
        })
        .count();
    let intervention_heavy_count = outcomes
        .iter()
        .filter(|outcome| {
            outcome
                .observations
                .iter()
                .chain(outcome.notes.iter())
                .any(|item| {
                    let item = item.to_ascii_lowercase();
                    item.contains("human-intervention")
                        || item.contains("operator")
                        || item.contains("manual")
                        || item.contains("machine-failure")
                        || item.contains("scrap")
                })
        })
        .count();
    json!({
        "ok": true,
        "schemaVersion": "dd.fabrication.learning-outcome-memory.v1",
        "serviceSchemaVersion": SCHEMA_VERSION,
        "routes": ["GET /learning/outcomes", "GET /fabrication/learning/outcomes"],
        "postRoutes": ["POST /learning/outcomes", "POST /fabrication/learning/outcomes"],
        "outcomeCount": outcomes.len(),
        "maxOutcomes": memory.max_outcomes,
        "bounded": true,
        "qualitySummary": {
            "successCount": success_count,
            "failureCount": failure_count,
            "positiveRewardCount": positive_reward_count,
            "negativeRewardCount": negative_reward_count,
            "hybridOutcomeCount": hybrid_outcome_count,
            "interventionHeavyCount": intervention_heavy_count
        },
        "qualityBuckets": [
            {
                "bucket": "successful-positive-reward",
                "count": outcomes
                    .iter()
                    .filter(|outcome| outcome.success && outcome.reward > 0.0)
                    .count(),
                "policyUse": "eligible to bias open machine, method, operation-sequence, and assembly preferences after repeated samples"
            },
            {
                "bucket": "failed-or-negative-reward",
                "count": outcomes
                    .iter()
                    .filter(|outcome| !outcome.success || outcome.reward < 0.0)
                    .count(),
                "policyUse": "retained as remediation risk and release-probe evidence before future machine-ready release"
            },
            {
                "bucket": "hybrid-split-combine",
                "count": hybrid_outcome_count,
                "policyUse": "feeds learned decomposition, recomposition, and operation ordering for printed, milled, turned, or assembled routes"
            },
            {
                "bucket": "intervention-heavy",
                "count": intervention_heavy_count,
                "policyUse": "feeds POMDP hidden-state evidence for human-intervention, automation-gap, and machine-failure risk"
            }
        ],
        "policyImpactPreview": [
            {
                "surface": "methodCombinationPreferences",
                "input": "successful hybrid split/combine outcomes with positive reward",
                "futureUse": "bias open requests toward proven printed, milled, turned, assembled, or joined route combinations while keeping machine-ready release gated"
            },
            {
                "surface": "machineKindPreferences",
                "input": "repeated successful machine-kind outcomes",
                "futureUse": "rank candidate printers, mills, routers, lathes, sheet cutters, and hybrid cells before validation and simulation"
            },
            {
                "surface": "operationSequencePreferences",
                "input": "positive reward operation order and route sequencing evidence",
                "futureUse": "prefer learned print-then-machine, machine-then-postprocess, split-combine, and assembly ordering when constraints are otherwise open"
            },
            {
                "surface": "splitCombinePreferences",
                "input": "retained split/combine hints, resolution actions, and boundary observations",
                "futureUse": "bias future hybrid decomposition and recomposition candidates while preserving validation, simulation, release-package, and operator signoff gates"
            },
            {
                "surface": "remediationRisks",
                "input": "failed or negative-reward outcomes with machine-failure or human-intervention evidence",
                "futureUse": "raise boundary, simulation, operator, or alternate-machine review before repeating risky code, setup, material, or process choices"
            },
            {
                "surface": "neuralTrainingExamples",
                "input": "retained observations, reward terms, artifacts, and outcome notes",
                "futureUse": "feed bounded neural-policy examples without bypassing controller, setup, quality, or signoff release gates"
            }
        ],
        "policy": snapshot,
        "outcomes": outcomes,
        "releasePolicy": [
            "outcomes are bounded in-process learning evidence used to shape future MDP/POMDP/neural planning previews",
            "learned preferences do not certify machine-ready release; validation, simulation, controller review, and operator or automation signoff remain required"
        ]
    })
}

