        assert!(jt_conversion
            .review_gates
            .contains(&"verify-jt-units-assembly-pmi-brep-or-tessellation".to_string()));
        assert!(jt_conversion
            .review_gates
            .contains(&"regenerate-step-3mf-stl-or-cam-setup-from-jt".to_string()));
