    #[test]
    fn design_import_review_endpoint_reuses_cad_validation_and_redaction() {
        let payload = design_import_review_response(DesignImportReviewRequest {
            request_id: Some("unit-design-import-review".to_string()),
            design_inputs: Some(vec![
                DesignInputFile {
                    id: Some("solidworks-part".to_string()),
                    file_name: Some("mount.SLDPRT".to_string()),
                    source_uri: None,
                    format: Some("SLDPRT".to_string()),
                    source_system: Some("SOLIDWORKS".to_string()),
                    role: Some("source CAD".to_string()),
                    notes: None,
                },
                DesignInputFile {
                    id: Some("ambiguous-prt".to_string()),
                    file_name: Some("bracket.prt".to_string()),
                    source_uri: None,
                    format: Some("part".to_string()),
                    source_system: None,
                    role: Some("source CAD".to_string()),
                    notes: None,
                },
                DesignInputFile {
                    id: Some("private-onshape".to_string()),
                    file_name: None,
                    source_uri: Some(
                        "https://token:secret@cad.onshape.com/documents/demo?apiKey=hidden#tab"
                            .to_string(),
                    ),
                    format: Some("Onshape document".to_string()),
                    source_system: Some("Onshape".to_string()),
                    role: Some("cloud CAD source".to_string()),
                    notes: None,
                },
                DesignInputFile {
                    id: Some("jt-pmi".to_string()),
                    file_name: Some("assembly.jt".to_string()),
                    source_uri: None,
                    format: Some("JT".to_string()),
                    source_system: Some("JT".to_string()),
                    role: Some("lightweight CAD PMI exchange".to_string()),
                    notes: None,
                },
            ]),
        })
        .expect("design import review should be generated");

        assert_eq!(
            payload.get("schemaVersion").and_then(Value::as_str),
            Some("dd.fabrication.design-import-review.v1")
        );
        assert_eq!(
            payload.get("requestId").and_then(Value::as_str),
            Some("unit-design-import-review")
        );
        assert_eq!(
            payload.get("machineReady").and_then(Value::as_bool),
            Some(false)
        );
        assert_eq!(
            payload.get("status").and_then(Value::as_str),
            Some("blocked-human-format-review")
        );
        assert!(payload
            .get("routes")
            .and_then(Value::as_array)
            .is_some_and(|routes| routes.iter().any(|route| {
                route.as_str() == Some("POST /fabrication/design/import/review")
            })));
        assert!(payload
            .get("workerLanes")
            .and_then(Value::as_array)
            .is_some_and(|lanes| lanes
                .iter()
                .any(|lane| { lane.as_str() == Some("lightweight-cad-pmi-inspector") })));

        let review = payload
            .get("designInputReview")
            .expect("design input review should be present");
        assert_eq!(review.get("inputCount").and_then(Value::as_u64), Some(4));
        assert!(review
            .get("inputs")
            .and_then(Value::as_array)
            .is_some_and(|inputs| inputs.iter().any(|input| {
                input.get("inputId").and_then(Value::as_str) == Some("private-onshape")
                    && input.get("sourceUri").and_then(Value::as_str)
                        == Some("https://redacted@cad.onshape.com/documents/demo")
            })));

        let conversions = review
            .get("conversionPlan")
            .and_then(Value::as_array)
            .expect("conversion plan should be present");
        let solidworks = conversions
            .iter()
            .find(|step| step.get("inputId").and_then(Value::as_str) == Some("solidworks-part"))
            .expect("solidworks conversion should be present");
        assert_eq!(
            solidworks.get("workerLane").and_then(Value::as_str),
            Some("professional-cad-converter")
        );
        let ambiguous = conversions
            .iter()
            .find(|step| step.get("inputId").and_then(Value::as_str) == Some("ambiguous-prt"))
            .expect("ambiguous conversion should be present");
        assert_eq!(
            ambiguous.get("status").and_then(Value::as_str),
            Some("blocked-human-format-review")
        );
        let jt = conversions
            .iter()
            .find(|step| step.get("inputId").and_then(Value::as_str) == Some("jt-pmi"))
            .expect("JT conversion should be present");
        assert!(jt
            .get("requiredEvidence")
            .and_then(Value::as_array)
            .is_some_and(|evidence| evidence
                .iter()
                .any(|item| item.as_str().is_some_and(|item| item.contains("PMI")))));

        let error = design_import_review_response(DesignImportReviewRequest {
            request_id: Some("notes-only-import-review".to_string()),
            design_inputs: Some(vec![DesignInputFile {
                id: Some("notes-only".to_string()),
                file_name: None,
                source_uri: None,
                format: None,
                source_system: None,
                role: Some("source CAD".to_string()),
                notes: Some(vec!["looks like SOLIDWORKS".to_string()]),
            }]),
        })
        .expect_err("notes-only design import review should be rejected");
        assert!(error.contains("must include fileName, sourceUri, format, or sourceSystem"));
    }

    #[test]
    fn design_import_result_endpoint_reviews_boundaries_artifacts_and_learning() {
        let payload = design_import_result_review_response(DesignImportResultReviewRequest {
            request_id: Some("unit-design-import-result".to_string()),
            source_job_id: Some("design-import-review-job".to_string()),
            input_id: Some("scan-mesh".to_string()),
            worker_id: "mesh-import-worker-01".to_string(),
            worker_lane: Some("mesh-repair-converter".to_string()),
            source_format: Some("stl".to_string()),
            source_system: Some("field-scan".to_string()),
            success: true,
            machine_ready: false,
            release_ready: Some(false),
            checks: Some(vec![DesignImportResultCheck {
                check_id: "mesh-topology-check".to_string(),
                check_kind: "mesh-topology-and-scale".to_string(),
                status: "blocked".to_string(),
                passed: Some(false),
                release_blocker: Some(true),
                requires_human_intervention: Some(true),
                evidence: Some(vec![
                    "non-manifold scan mesh has unknown scale and open shell".to_string(),
                ]),
            }]),
            failure_boundaries: Some(vec![DesignImportResultBoundary {
                boundary_id: "split-repair-required".to_string(),
                boundary_kind: "mesh-repair-and-split-boundary".to_string(),
                code: "mesh-open-shell-scale-unknown".to_string(),
                message: "Imported scan cannot be converted into machine-ready geometry without scale review and split repair.".to_string(),
                release_blocker: Some(true),
                human_intervention_required: Some(true),
                split_required: Some(true),
                combine_required: Some(false),
                recommended_action: Some("human-scale-review-split-and-remesh".to_string()),
                evidence: Some(vec![
                    "repair worker found open shell across intended split line".to_string(),
                ]),
            }]),
            artifacts: Some(vec![DesignImportResultArtifact {
                artifact_id: "mesh-import-report".to_string(),
                artifact_kind: "mesh-import-report".to_string(),
                input_id: Some("scan-mesh".to_string()),
                uri: Some("s3://fabrication/design-import/mesh-import-report.json".to_string()),
                sha256: Some("b".repeat(64)),
                format: Some("json".to_string()),
                evidence: Some(vec!["retained mesh topology report".to_string()]),
            }]),
            warnings: Some(vec![
                "scale and split repair must be reviewed before conversion".to_string(),
            ]),
            review_metadata: Some(json!({"scanSession": "shop-floor-17"})),
        })
        .expect("design import result should validate");

        assert_eq!(
            payload.get("schemaVersion").and_then(Value::as_str),
            Some("dd.fabrication.design-import-result-review.v1")
        );
        assert!(payload
            .get("routes")
            .and_then(Value::as_array)
            .is_some_and(|routes| routes.iter().any(|route| {
                route.as_str() == Some("POST /fabrication/design/import/result")
            })));
        assert_eq!(
            payload.get("reviewStatus").and_then(Value::as_str),
            Some("design-import-result-checks-release-blocked")
        );
        assert_eq!(
            payload.get("releaseBlocked").and_then(Value::as_bool),
            Some(true)
        );
        assert_eq!(
            payload.get("machineReady").and_then(Value::as_bool),
            Some(false)
        );
        let priority_dispositions = payload
            .get("priorityDispositions")
            .and_then(Value::as_array)
            .expect("design import priority dispositions");
        for expected in [
            ("import-check-closure", "blocked"),
            ("failure-boundary-closure", "blocked"),
            ("artifact-evidence-retention", "needs-review"),
            (
                "learning-feedback-after-disposition",
                "pending-blocker-resolution",
            ),
        ] {
            assert!(
                priority_dispositions.iter().any(|disposition| {
                    disposition.get("priorityId").and_then(Value::as_str) == Some(expected.0)
                        && disposition.get("disposition").and_then(Value::as_str)
                            == Some(expected.1)
                }),
                "missing design import priority disposition {}",
                expected.0
            );
        }
        assert_eq!(
            payload.get("checkBlockerCount").and_then(Value::as_u64),
            Some(1)
        );
        assert_eq!(
            payload.get("boundaryBlockerCount").and_then(Value::as_u64),
            Some(1)
        );
        assert_eq!(
            payload.get("splitBoundaryCount").and_then(Value::as_u64),
            Some(1)
        );
        assert_eq!(
            payload
                .get("missingArtifactEvidenceCount")
                .and_then(Value::as_u64),
            Some(0)
        );
        assert!(payload
            .get("learning")
            .and_then(|learning| learning.get("observations"))
            .and_then(Value::as_array)
            .is_some_and(|observations| observations.iter().any(|observation| {
                observation.as_str() == Some("design-import:split-required")
            })));
        assert!(payload
            .get("learning")
            .and_then(|learning| learning.get("observations"))
            .and_then(Value::as_array)
            .is_some_and(|observations| observations.iter().any(|observation| {
                observation.as_str()
                    == Some("design-import-action:human-scale-review-split-and-remesh")
            })));

        let outcome_draft = payload
            .pointer("/learning/outcomeDraft")
            .expect("design import learning outcome draft");
        assert_eq!(
            outcome_draft.get("schemaVersion").and_then(Value::as_str),
            Some("dd.fabrication.design-import-learning-outcome-draft.v1")
        );
        assert_eq!(
            outcome_draft
                .get("recommendedSubmitRoute")
                .and_then(Value::as_str),
            Some("POST /fabrication/learning/outcomes")
        );
        assert_eq!(
            outcome_draft.get("success").and_then(Value::as_bool),
            Some(false)
        );
        assert_eq!(
            outcome_draft.get("rewardHint").and_then(Value::as_f64),
            Some(-0.7)
        );
        assert!(outcome_draft
            .get("checkHints")
            .and_then(Value::as_array)
            .is_some_and(|hints| hints
                .iter()
                .any(|hint| hint.as_str() == Some("mesh-topology-and-scale"))));
        assert!(outcome_draft
            .get("boundaryHints")
            .and_then(Value::as_array)
            .is_some_and(|hints| hints
                .iter()
                .any(|hint| hint.as_str() == Some("mesh-open-shell-scale-unknown"))));
        assert!(outcome_draft
            .get("recommendedActionHints")
            .and_then(Value::as_array)
            .is_some_and(|hints| hints
                .iter()
                .any(|hint| hint.as_str() == Some("human-scale-review-split-and-remesh"))));
        assert!(outcome_draft
            .get("featureHints")
            .and_then(Value::as_array)
            .is_some_and(|hints| hints
                .iter()
                .any(|hint| hint.as_str() == Some("split-boundaries:1"))));
        assert!(outcome_draft
            .get("priorityDispositions")
            .and_then(Value::as_array)
            .is_some_and(|dispositions| dispositions.iter().any(|disposition| {
                disposition
                    .get("learningObservation")
                    .and_then(Value::as_str)
                    == Some("design-import-priority:failure-boundary-closure:blocked")
            })));

        let job = stored_design_import_result_job(&payload);
        assert_eq!(job.record.kind, "design-import-result");
        assert_eq!(
            job.record.status,
            "design-import-result-checks-release-blocked"
        );
        assert_eq!(job.record.severity, "error");
        assert!(!job.record.ok);
        for artifact in [
            "design-import-result",
            "design-import-checks",
            "design-import-failure-boundaries",
            "design-import-artifacts",
            "design-import-priority-dispositions",
            "design-import-learning-observations",
        ] {
            assert!(
                job.artifacts.contains_key(artifact),
                "missing design import result artifact {artifact}"
            );
        }
    }

