    #[test]
    fn material_catalog_endpoint_exposes_feedstock_compatibility_and_release_contract() {
        let payload = material_catalog_response();
        assert_eq!(
            payload.get("schemaVersion").and_then(Value::as_str),
            Some("dd.fabrication.material-catalog.v1")
        );
        assert!(payload
            .get("materialCount")
            .and_then(Value::as_u64)
            .is_some_and(|count| count >= 20));
        assert!(payload
            .get("routes")
            .and_then(Value::as_array)
            .is_some_and(|routes| routes
                .iter()
                .any(|route| route.as_str() == Some("GET /fabrication/materials/catalog"))));
        assert!(payload
            .get("responseSurfaces")
            .and_then(Value::as_array)
            .is_some_and(|surfaces| surfaces
                .iter()
                .any(|surface| surface.as_str() == Some("materialPlan.routeRequirements"))));
        assert!(payload
            .get("releasePolicy")
            .and_then(Value::as_array)
            .is_some_and(|policy| policy.iter().any(|item| item
                .as_str()
                .is_some_and(|item| item.contains("machine-ready release remains blocked")))));
        let checklist = payload
            .get("materialReadinessChecklist")
            .and_then(Value::as_array)
            .expect("material readiness checklist should be present");
        for check_id in [
            "lot-certificate-and-traceability",
            "conditioning-and-shelf-life-state",
            "quantity-scrap-and-runout-capacity",
            "machine-material-process-compatibility",
        ] {
            assert!(
                checklist
                    .iter()
                    .any(|item| item.get("checkId").and_then(Value::as_str) == Some(check_id)),
                "missing material readiness check {check_id}"
            );
        }
        assert!(checklist.iter().any(|item| item
            .get("blocks")
            .and_then(Value::as_array)
            .is_some_and(|blocks| blocks
                .iter()
                .any(|entry| entry.as_str() == Some("machineRelease.blockers")))));
        assert!(checklist.iter().any(|item| item
            .get("learningSignals")
            .and_then(Value::as_array)
            .is_some_and(|signals| signals.iter().any(|entry| entry
                .as_str()
                .is_some_and(|entry| entry.contains("runout-risk"))))));

        let families = payload
            .get("families")
            .and_then(Value::as_array)
            .expect("families should be present");
        for family in ["metal", "polymer", "photopolymer", "composite"] {
            assert!(
                families.iter().any(|item| item.as_str() == Some(family)),
                "missing material family {family}"
            );
        }
        let feedstock_kinds = payload
            .get("feedstockKinds")
            .and_then(Value::as_array)
            .expect("feedstock kinds should be present");
        for kind in [
            "filament-spool",
            "photopolymer-resin",
            "qualified-metal-powder-lot",
            "sheet-plate-or-panel",
        ] {
            assert!(
                feedstock_kinds
                    .iter()
                    .any(|item| item.as_str() == Some(kind)),
                "missing feedstock kind {kind}"
            );
        }

        let materials = payload
            .get("materials")
            .and_then(Value::as_array)
            .expect("materials should be present");
        let aluminum = materials
            .iter()
            .find(|item| item.get("material").and_then(Value::as_str) == Some("aluminum"))
            .expect("aluminum material should be present");
        assert_eq!(
            aluminum.get("family").and_then(Value::as_str),
            Some("metal")
        );
        assert!(aluminum
            .get("compatibleMachineKinds")
            .and_then(Value::as_array)
            .is_some_and(|kinds| kinds
                .iter()
                .any(|kind| kind.as_str() == Some("vertical-mill"))));
        assert!(aluminum
            .get("boundarySignals")
            .and_then(Value::as_array)
            .is_some_and(|signals| signals.iter().any(|signal| signal
                .as_str()
                .is_some_and(|signal| signal == "material-machine-boundary:aluminum"))));

        let resin = materials
            .iter()
            .find(|item| item.get("material").and_then(Value::as_str) == Some("resin"))
            .expect("resin material should be present");
        assert_eq!(
            resin.get("family").and_then(Value::as_str),
            Some("photopolymer")
        );
        assert!(resin
            .get("conditioning")
            .and_then(Value::as_array)
            .is_some_and(|conditioning| conditioning
                .iter()
                .any(|item| item.as_str().is_some_and(|item| item.contains("wash")))));
    }

    #[test]
    fn material_planning_endpoint_returns_feedstock_conditioning_and_release_contract() {
        let policy = LearningPolicySnapshot {
            outcome_count: 0,
            successes: 0,
            failures: 0,
            average_reward: 0.0,
            method_preferences: Vec::new(),
            method_combination_preferences: Vec::new(),
            machine_kind_preferences: Vec::new(),
            operation_sequence_preferences: Vec::new(),
            assembly_preferences: Vec::new(),
            split_combine_preferences: Vec::new(),
            remediation_risks: Vec::new(),
            neural_training_examples: Vec::new(),
            boundary_learning_examples: Vec::new(),
        };
        let response = plan_fabrication_with_policy(
            FabricationPlanRequest {
                request_id: Some("unit-material-plan".to_string()),
                objective:
                    "reserve aluminum stock and material evidence for a milled bracket before release"
                        .to_string(),
                material: Some(material("6061 aluminum", "metal")),
                stock: None,
                tolerance_mm: Some(0.05),
                quantity: Some(2),
                machines: Some(vec![MachineProfile {
                    id: "material-vmc".to_string(),
                    kind: "vertical-mill".to_string(),
                    controller: Some("haas-gcode".to_string()),
                    materials: Some(vec!["metal".to_string(), "aluminum".to_string()]),
                    work_envelope_mm: Some(vec![500.0, 400.0, 300.0]),
                    axes: Some(3),
                    operations: Some(vec!["milling".to_string(), "drilling".to_string()]),
                    profile_evidence: None,
                }]),
                constraints: Some(FabricationConstraints {
                    max_setups: Some(2),
                    allow_human_intervention: Some(true),
                    allow_multi_part_assembly: Some(false),
                    require_dry_run: Some(true),
                    preferred_methods: Some(vec!["milling".to_string()]),
                    preferred_assembly_strategy: None,
                }),
                parts: Some(vec![RequestedPart {
                    id: "material-bracket".to_string(),
                    description:
                        "milled aluminum bracket needing stock form, lot, and conditioning evidence"
                            .to_string(),
                    material: None,
                    preferred_method: Some("milling".to_string()),
                    tolerance_mm: Some(0.05),
                }]),
                design_inputs: None,
                existing_instructions: None,
                learning: None,
            },
            Some(&policy),
        )
        .expect("material planning should succeed");

        let payload = material_planning_response(&response, &policy);
        assert_eq!(
            payload.get("schemaVersion").and_then(Value::as_str),
            Some("dd.fabrication.material-planning.v1")
        );
        assert!(payload
            .get("routes")
            .and_then(Value::as_array)
            .is_some_and(|routes| routes
                .iter()
                .any(|route| route.as_str() == Some("POST /fabrication/materials/plan"))));
        assert_eq!(
            payload.get("machineReady").and_then(Value::as_bool),
            Some(false)
        );
        assert!(payload
            .get("routeRequirementCount")
            .and_then(Value::as_u64)
            .is_some_and(|count| count > 0));
        assert!(payload
            .get("materialRouteBlockerCount")
            .and_then(Value::as_u64)
            .is_some_and(|count| count > 0));
        assert!(payload
            .get("conditioningStepCount")
            .and_then(Value::as_u64)
            .is_some_and(|count| count > 0));
        assert!(payload
            .get("requiredEvidenceCount")
            .and_then(Value::as_u64)
            .is_some_and(|count| count > 0));
        assert!(payload
            .get("materialPlan")
            .and_then(|plan| plan.get("routeRequirements"))
            .and_then(Value::as_array)
            .is_some_and(|requirements| requirements.iter().any(|requirement| {
                requirement.get("feedstockKind").and_then(Value::as_str)
                    == Some("block-plate-or-sheet-blank")
                    && requirement
                        .get("releaseBlockers")
                        .and_then(Value::as_array)
                        .is_some_and(|blockers| {
                            blockers.iter().any(|blocker| {
                                blocker
                                    .as_str()
                                    .is_some_and(|blocker| blocker.contains("declared stock"))
                            })
                        })
            })));
        assert!(payload
            .get("responseSurfaces")
            .and_then(Value::as_array)
            .is_some_and(|surfaces| surfaces.iter().any(|surface| {
                surface.as_str() == Some("materialPlan.routeRequirements.requiredEvidence")
            })));
        assert!(
            payload
                .get("learning")
                .and_then(|learning| learning.get("engine"))
                .and_then(|engine| engine.get("crateName"))
                .and_then(Value::as_str)
                == Some("des_engine")
        );

        let job = stored_plan_job(&response);
        for artifact in [
            "material-plan",
            "machine-selection",
            "tooling-plan",
            "quality-plan",
            "release-package-plan",
            "machine-release",
            "mdp-request",
        ] {
            assert!(
                job.artifacts.contains_key(artifact),
                "missing material planning artifact {artifact}"
            );
        }
    }

